/* 平成21年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h21.committeeSessions.push(...[{"id":"h21-20090309-3","meetingId":"h21-c-budget","date":"2009年3月9日","dateIso":"2009-03-09","committee":"予算特別委員会","time":"午前１０時０２分～午後６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を157件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"１１６ページ、１１７ページのところで、五反田駅周辺のところから質問させてほしいと求めました。ですから、いろいろなことがあるでしょうけれども、実際に区のほうに、ざっくり全体でどのぐらい入れたか。","respondent":"青木都市開発課長","answer":"地元の方々ともお話し合いを進めながら考えていこうということで、今、検討中です。具体的なビジョンを持ち合わせていませんので、現在のところ、まだ確定していないというお答えになろうかと思います。","id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"投資をされていくわけですから、当然それに関する戻りがなければ、何のために入れるのかと。投下するものに対する保全措置がとられているのかどうか、どうでしょうか、お考えを。","respondent":"青木都市開発課長","answer":"これが今、こちらに関しては約１.５８という数字がありまして、１の投資に対して１.５８倍の経済効果が見込まれるというような試算があります。経済的、あるいは税収負担もなく、効果的な事業が進んでいるとご理解いただければと考えています。","id":"exchange-002"},{"speaker":"原委員","kind":"意見","question":"どういったところに、全体的に、区として今度は区民に対して何を還元するのか。いろいろな施設関係等、等があるかどうかというのを、ちょっとお聞かせほしいと求めました。","respondent":"青木都市開発課長","answer":"企業と地域住民、あるいは子どもとの連携というんでしょうか、そういったものが進んでおります。人々が憩えるような施設もあわせて整備していているという形で、ソフト、ハード両面で整備を進めているところです。","id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"これは要望として、そういった面で、一層お願いをしていければと思います。地域の方々がどういうふうになっていくんだという話がありまして、情報というか、インフォメーションが出てくるのをもう少し早くお願いしたい。","respondent":"市川教育次長","answer":"基本的な考え方につきましては、北品川五丁目の再開発事業の進捗状況を見極めた上で改築をするという基本的な考え方を示してまいりました。今、計画の基本的な方向性が定まった時点で、早い時期にお知らせをするという態度で臨んでまいりたいと思います。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"この辺は、民間の場合には、最近はトラブルは出てこないんです、もうご存じのように。ところが学校ということになりますと、それはちょっとまた観点が違うものですから、その辺について、一言ほしいと求めました。","respondent":"青木都市開発課長","answer":"日照の確保を最大限できる方向で検討してあるということ、南側の校庭になる部分、極力影を落とさないように建物を低くするなどの配慮をしております。これは、引き続き詳細に検討しながら、計画を進めいきたいと考えています。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"火曜日の延長窓口ですかと、それ以外にもあるわけですけれども、どのような分布になっているのか。地域的に多い、少ないとかいう傾向があるのか、どうか、お伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"大井と武蔵小山の２カ所のサービスコーナーでやってありますが、それから１３地区の地域センターで半数弱、サービスコーナーは８８０万円余です。そのまま比較はできませんが、サービスコーナーで見ますと…","id":"exchange-006"},{"speaker":"浅野委員","kind":"提案","question":"振込確認後に送付するとか、７５０円かかってしまうとか、そういうところもあるわけです。さらに、利便性を考えたこういう取り組みも、品川区としては、今後も必要ではないかと考えますが、ご所見をお伺いしますとの意見を述べました。","respondent":"原情報システム課長","answer":"社会保障カードといったものとの組み合わせ、それから、コンビニで住民票を取れないかというような検討も進めております。そういった意味では、品川区といたしましては、そういった動向に十分に注意しながら、拡大を検討してまいりたいと考えているところです。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"１カ所だけに、これは確認を含めて、要望しておきます。住民基本台帳の件ですけれども、改正案が３月３日に閣議決定をされておりまして、その概要と効果について、ごく簡単にお願いします。","respondent":"上川内戸籍住民課長","answer":"使い勝手が悪いという声がかなり前々から多うございまして、その要望が通って閣議決定で決まったのは、全国共通のカードにしていくということです。表面が偽造されても、全国共通というような仕組みにしていこうということが閣議決定され…","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"公明党がもう１０年間がかりで取り組んできた政策でございまして、いよいよ実現化する、３年以内に実現化されるという運びとなったと感じております。新しいものについては、政策分としてやっているわけですけれども、この内訳についても、その政策と経常の違いを、簡単にお願いします。","respondent":"中川原広報広聴課長","answer":"しながわガイドの内訳ですが、これは、数年に一遍、全戸配布を行うものです。そのほか、毎年、転入者用に印刷しているということで、平成２１年度は全戸配布分と、その配布までの転入者分、両方を予算要求しているものです。","id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"１号、３号、５号、たしか６号だったと思うんですけれども、そのような区別があるのは、やはり見え方かなと思います。広告料収入については、今回、新しいしながわガイドを出すために何か考えられたことがあれば、お願いしますとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"しながわガイド全戸配布の時期に合わせまして、２２万５,０００部刷るということで、事業者のほうに広告料の勧誘をするところです。特別に考えていることとしましては、そういった意味では、従来の広告とは少し変わった広告の注文を取っていきたいと考えているところです。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"いろいろ工夫をこらして、増収というんでしょうか、そういうような計画はあるのか、ないのか。検索のほうは随分とよくなって、非常に使いやすくなったのは歓迎するところですが、広告についてもお願いします。","respondent":"中川原広報広聴課長","answer":"ホームページにつきましては、できれば、運営維持経費の自己資金調達という意味も含めまして取り組んでいるところです。１年間様子を見ましたら、私どものホームページの運営経費に充てするという考えから、今後もやっていきたいと考えているところです。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"そしてまた、区から送付する封筒なんかに広告を掲載するというところもあります。ここら辺についてのお考えがあれば、お伺いします。","respondent":"中川原広報広聴課長","answer":"本来お伝えする情報を邪魔しない程度に、デザイン面にも配慮してやっていきたいと考えています。封筒等につきましては、戸籍住民課でもやった経験もありますし、今後、広告料の収入ということで、検討してまいりたいと考えています。","id":"exchange-012"},{"speaker":"浅野委員","kind":"質問","question":"庁舎のロビーなどに設置されているテレビモニターが２台ありますけれども、こちらのほうに広告を流すという件はどうか尋ねました。","respondent":"中川原広報広聴課長","answer":"さまざまなものについて、広告について、今後、検討していきたいと考えています。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"３７０万円余というのは、八潮に増設する特別養護老人ホームの出来高３％分ということなんですが、お聞きしたいと思います。もう１点なんですけれども、５００名からの方が申込をされていますけれども、この辺もちょっとお聞かせ願いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"計画内に建設をするということで計画化していることですので、具体的には、実施計画の中で具体的に上げていくところです。２番目の適地の部分ですが、当然、適地の情報収集には努めてまいりたいと思います。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"希望者は増加をし続けているわけですから、２％ぐらいのベッド数が必要なのかな、需用があるのかなと考えます。５００名の待機者は、ほんとうにあす、あさって困っているわけですから、その辺をきっちり考えて年次計画をつくるべきではないかと思います。","respondent":"冨岡高齢福祉課長、木下福祉高齢事業部長","answer":"明確な基準というのはございませんけれども、例えば、広さですが、大体３,０００m2の広さは必要だと理解をしております。 現在、八潮南中学校の特別養護老人ホームは予定しておりますけれども、具体的な計画を区として明確に持っているものはございません。そういう面では、いろいろな諸条件が熟した段階で明らかにしていく…","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"平成２０年から２２年の間でしょうか、１ベッド当たり従来の１.５倍の加算がされて、６５４万円の補助金が投入されるとなっていますよね。八潮の８０ベッドを入れても１.０未満ですから、固めるべきだというふうに思いますけれども、その辺はいかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"私ども仕事を進める上で非常にやりにくい部分になっておりまして、国土交通省のほうは、土地についての補助金も用意されている。そのようなことも含めまして、今後、諸条件を見極めながら考えていこうというのが区の考え方です。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"５００名という待機者たちをどういうふうにとらえているのかということが、非常に疑問になる、今の答弁なんです。その後どうなるかはわかりませんけれども、少なくとも３年間しかこれを使えないわけですから、目標を出すべきではないかと思うんです。","respondent":"木下福祉高齢事業部長","answer":"そういう点では、八潮の特別養護老人ホームの整備をすることによって、その部分については、より磐石なものになるだろうと考えています。その後のことにつきましては、この辺の整備をまずは優先をさせていただきたいと考えています。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"真に必要な方が入れていなかったという現状を見ての上ではないんですか。そうでなければ、増設の必要はないわけですから、おかしいでしょ、今の答弁は。","respondent":"木下福祉高齢事業部長","answer":"今後１０年間を見据えて、高齢者人口が増えていくということを前提に、今回の八潮の部分については整備をするです。そういう意味では、現時点での入所調整の一定の対応の部分と、今後の高齢者人口の増の部分で政策については考えているです。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"３,０００m2ぐらいの土地が必要だと言っているんですけれども、十分に特別養護老人ホームをつくる土地を探すことは可能だと思います。収入でも、介護の面でも大変な状況にあるわけですから、やはりきっちり目標を持った流れをつくり出すべきだということを言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"１０８ページの都補助金、そして１３０ページの過料について、１３８ページのリサイクル資源売払収入についてお伺いいたします。軽自動車税についてお伺いしたいんですが、調定額が１億２６０万円と書いてあるんですが、その辺を説明を求めました。","respondent":"武内税務課長","answer":"５月３１日が納期になるんですけれども、賦課して１００％歳入になるということは、過去の例でもないわけです。１億２６０万円ほどの金額の課税をする予定で、その後、収入率として９４.５４％を見込みまして。","id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"たばこ税についてお伺いをしているんですが、マイナス６.１％ということで、品川区としてどうお考えなのか。今回、３０億円を切っている状況の中で、どんどん減少傾向にあるのではないかと、私は思っているんですが、その辺、説明をお願いします。","respondent":"武内税務課長","answer":"税のあり方を国のほうで検討しますと、たばこ税率が上がるということが、過去にも行われている。引き続き３０億円前後の歳入が、財政運営上、よりいいのかなと考えております。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問・要望","question":"先ほども返ってこなかったんですが、５年後、１０年後、今後、減らさないようにする努力はあると思うんですが、実際にどうなるのか。今回６.１％だったけれども、例えば５年後にはマイナス１０％ぐらいになるのではないか、その見通しがわかれば教えていただきたいんです。","respondent":"武内税務課長","answer":"健康志向ということで、たばこ離れということも、当然、影響してきますし、また社会のルールということで、喫煙できる場所がかなり制限されていくという状況が、今後生れますので、今後５年間、どういう数字になるかという部分については、マイナスになっていくと考えております。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"１１８ページの都補助金の中の密集住宅市街地整備促進事業についてなんですが、この中味についてお伺いしたいのです。都が３分の１と書いてあるんですが、一番上の２分の１という部分は、どういう部分に利用されるのか説明を求めました。","respondent":"吉川住環境整備担当課長","answer":"都補助金の２分の１の内容について、お答えいたします。内容といたしましては、東京都だけで補助対象にしているということで、東京都の２分の１となっているものです。","id":"exchange-023"},{"speaker":"稲川委員","kind":"質問・要望","question":"１３８ページのリサイクル資源売払収入についてなんですが、これは、実際に役所の中で出たリサイクル品を売り払ったという解釈でよろしいんですか。例えばダンボールは年間どのぐらい出るのかとか、そういった部分、詳細を教えていただきたいんですが。","respondent":"秋山資源循環推進課長","answer":"リサイクル資源の売払収入ですけれども、まず、資源回収ステーションで区民の方が出されました資源が大部分です。鉄缶が２,５００万円程度、その他が１３０万円ということで、１億２,８００万円の売払収入が上がっているというものです。","id":"exchange-024"},{"speaker":"稲川委員","kind":"質問・要望","question":"ちょっと勉強不足で、１回、お伺いしたいんですが、普通に資源回収をして、ペットボトルとかを、工場かどこかに持って行って売り払っているという話なんですが、それはどこに載っているのか、教えていただきたいんですが。","respondent":"秋山資源循環推進課長","answer":"プラスチック製の容器包装のことだと思うんですけれども、それにつきましては、売払の収入ではなくて、処分代がかかりますので、歳出のほうで計上させていただいているものです。","id":"exchange-025"},{"speaker":"井桁委員","kind":"質問","question":"１１９ページ、５目土木費補助金の水辺景観助成事業の、この二つについてお伺いしたいと思います。平成１７年、１５年と開設をされておりますが、ちょっとお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"入居の引き継ぎの関係で１カ月、２カ月、ほぼ満室の状態が続いているという状況にあります。創業支援施設というものですから、製造業の創業を支援するという趣旨で、その周辺の産業の方も含めて入居をさせているところです。","id":"exchange-026"},{"speaker":"井桁委員","kind":"質問","question":"ここでひとつお伺いしたいのが、やはり出て行った後にどうなっているのか。その後どうなっていっているのかといった現状の把握は、現在されていらっしゃいますか尋ねました。","respondent":"金子産業振興課長","answer":"現在までに出られた方が１９件あるわけですけれども、あるいは廃業された方は４件、逆に発展的に出られて行った方が８件という状況です。その後については、なかなか把握しきれないところがありますので、現在、掌握しているのは以上です。","id":"exchange-027"},{"speaker":"井桁委員","kind":"質問・要望","question":"区としてもやはり、その後の後追いでありますとか、フォローというのをしっかりしていっていただきたいなと考えています。そこから区で活躍していただきたいといった思いも強くありますので、意気込みといいましょうか、そういったものをお伺いできればと考えています。","respondent":"金子産業振興課長","answer":"かつ、事業の計画が比較的安定されている方というような基準で選んでおります。今後とも、私どもとしては、品川区の産業の発展に資するような形で運営していきたいと考えております。","id":"exchange-028"},{"speaker":"井桁委員","kind":"質問","question":"１１９ページの都支出金の中の水辺景観助成事業についてなんですけれども、都の水辺景観形成等、水辺の条例の中の一つで行われるということなんです。その中で、やはりこういった水辺に対するとか、全体的なまちづくりに対する景観への考え方と、今後の方向性をお伺いできればと考えています。","respondent":"梶都市計画課長","answer":"一般的なことが中心となってまいりますので、そういったきめ細かな品川区の独自性を生かしたような景観計画をつくっていきたいと考えております。景観行政団体を品川区のほうに移らさせていただいて、その中で品川区独自の景観計画をつくっていきたいと、そのように考えておりま…","id":"exchange-029"},{"speaker":"井桁委員","kind":"質問","question":"２３区の中では江東区、２点、お伺いできればと考えています。","respondent":"梶都市計画課長","answer":"あるいは昨年１０月、１１月に基本的な考え方のパブリックコメントを行いましたけれども、東京都のほうと打ち合わせをしています。２３区を含めた景観計画ができておりまして、また、区民の皆様と一緒に実効性のある取り組みを行っていきたいと思っているところです。","id":"exchange-030"},{"speaker":"井桁委員","kind":"質問・要望","question":"いろいろな課題が出てくると想定されるんですが、住民とのしっかりした話し合いというのを、今後していただきたいと考えています。そういったものも、今後、出てくるのか尋ねました。","respondent":"松代管理工事課長","answer":"今現在は東京都の条例ということで進めておりますけれども、景観計画を進めていく中で、看板等があります。景観づくりはどういったものかといったことを、今後、地域の皆様といろいろと検討してまいりたいと考えているところです。","id":"exchange-031"},{"speaker":"井桁委員","kind":"質問","question":"都の条例で、今度、区に移管したときに、お金といいますか、そういったものの負担は、今後、お考えか尋ねました。","respondent":"松代管理工事課長","answer":"景観づくりの中で、地域の方といろいろと話をする中で研究、検討していきたいと考えておるところです。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"平成２１年度の当初予算案のところを見ますと、これは新規事業ということになっておりまして、低所得者対象の生活相談と書いてあります。ここのところを、理解がちょっとできていないものですから、もうちょっと詳しく教えてほしいと求めました。","respondent":"志村生活福祉課長","answer":"この事業は、昨年の８月から開始されております。平成２０年６月に補正の議決をいただきまして、平年度化ということで、１２カ月実施をしていこうという内容です。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問・要望","question":"今、就職チャレンジ支援事業とか、生活サポートとか、いろいろ教えていただきましたけれども、何か受けるための条件とか、また、対象がどういうことなのか、もう少し詳細に教えてほしいと求めましたけれども、。","respondent":"志村生活福祉課長","answer":"扶養者がある方については６０万円以下、都内に在住が１年以上、こういうことが基本的な要件であります。先ほど申し上げた、いろいろなサポート事業が出てまいりますので、これについて個別の説明をさせていただいているという内容です。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問","question":"我が品川区もスタートするということで、実際にいろいろな貸付事業が始まるわけですけれども、いろいろな項目にある程度目標といいますか、助成を受けられる人数の枠というんですか、そういうものはあるんか尋ねました。","respondent":"志村生活福祉課長","answer":"例えば資金の貸付ですとか、もっと言いますと、最終的には生活保護とかということになってまいります。ですので、いろいろお聞きする中で判断していくべきものだと考えています。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問・要望","question":"すみません、大きな間違いをしていましたが、昨年の８月からスタートしているということで、今までの実績といいますか、実際にどういうことがあるのか教えてほしいと求めました。","respondent":"志村生活福祉課長","answer":"品川区では、そのうち２５０件、２３区平均ではやや低いかなと思いますけれども、こうした内容です。いろいろ正規雇用に向けての取り組み、具体的な内容は、個々千差万別です。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"貸付事業ということなので、やっぱり返済はしなければいけないんですよね、いかがか尋ねました。","respondent":"志村生活福祉課長","answer":"それからもう一つは、この方が、今度就職に向けて一時金等が必要な場合は、限度額５０万円までお貸しすることができます。ですので、これにつきましては、就労してから返していただくということになっております。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問","question":"すみません、しつこくて申しわけないんですが、返済するその期間といいますか、年数はあるんでしょうか。それとも、いつでもいいということなんか尋ねました。","respondent":"志村生活福祉課長","answer":"額にもよりますけれども、一応１０年が基本です。ですから、その利率につきましては、直近の利率を算定してと聞いております。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"歳入の１２６ページ寄附金の部分で、１３６ページの広告料収入について、２点お伺いしていきます。たしか寄附は一口５万円だったかと思うんですが、１基設置するためにかかるコストはどのぐらいなのか、先にお休み石のところから伺っていきます。","respondent":"永尾高齢事業課長","answer":"しながわお休み石ですが、開始が平成８年４月です。それから、設置の場所についてですけれども、やはり国道につきましては、なかなか国の了解を得るのが難しい状態になっております。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"広告料収入で伺いたいのが、どういう媒体で広告を募っているのか、わかればいろいろ教えていただきたい。ほかにいわゆる広告収入という部分で、何か、今後考えていくのかがあれば、方向性を踏まえて説明を求めました。","respondent":"中川原広報広聴課長、日下部企画財政課長","answer":"年間の予算としましては３１２万円、料金は違うんですけれども、今年度の全戸配布のときにつきましては４１７万円ほど予算を上げています。１バナー広告２万円のところ、毎月４０社お申込いただいているところで… ネーミングライツについて、私のほうからお答えをします。いろいろ候補になるところがありますので、検討した経緯はあるんですが、なかなかそれが思うような形では進んでいないという現状です。","id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"こういう時代ですから、ネーミングライツ等を新たな財源確保という観点から検討してほしいと求めましたが、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"ネーミングライツ、区の独自財源の確保といった点では非常に重要な課題だと、我々も思っていますし、そういった意味では、今後ともその辺の可能性については、できる限り追求をしてまいりたいと考えております。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"８８ページからの国庫支出金、１０６ページからの都支出金の中で、お伺いいたします。国庫支出金と都支出金の中にあったんですが、この辺に一体どういう中味が含まれているのか、おおもとのところを説明を求めました。","respondent":"日下部企画財政課長","answer":"財政調整交付金の関係ですけれども、保育園に係わる経費、運営費、人件費も含めて、これが算定対象として中に算定をされているというものです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"国庫支出金と都支出金の中にも、私立保育園の部分があったんですが、この部分に算定されるのは一体どういう中味なのか、説明を求めました。","respondent":"小林保育課長","answer":"お手元の説明書の８９ページの国庫支出金のところに児童保育費というところがあります、これが一番大きい私立保育園に対する経費かと思います。標準経費のうち２分の１が国の負担金、そして、４分の１が都の負担金というのが基本構造です。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公立保育園が４０園あるわけですが、在園児数が３,６４６人となっていますが、実人員のところを教えてほしいと求めました。総数で、できましたら、職種別のところで、わかったらその部分も説明を求めました。","respondent":"榎本人事課長","answer":"保育園の財政調整交付金算定人員なんですけれども、平成２０年４月１日で算定した形で、保育園につきましては７７８名で、職員数は６７１名というものです。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"職種別がわかるかどうか、再度、お伺いをしたいのと、保育園の場合、モデル園というか、基準の保育園、例えば１００名で、０歳をやっているとか、基準の保育園のところの職員の配置の基準がありましたら、そこも総数と、職種別にわかったら、その辺も説明を求めました。","respondent":"榎本人事課長","answer":"今の財政調整交付金算定人員７７８名の職種別の部分は入っておりません。総数で財政調整交付金としてカウントしているというものです。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"財調のモデル園の職員の総数と、職種別にわかったらということを２点目にお伺いしました。","respondent":"日下部企画財政課長","answer":"標準算定というふうに申しておりますけれども、そこにおける人員の配置の一つの事例といいますか、考え方といたしましては、１園、児童１００人入所という前提でありますけれども、保育士１５名、調理２名、用務１名という形で算定の一つの基準が出ているというものです。","id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"職種別のところで、看護師とか、調理員とか、保育士１５名は施設長が含まれているのかどうか。財調の基準という考え方は、都基準と一致するのか、しないのかというところと、品川区の基準があるんだったら、その辺の違いを説明を求めました。","respondent":"小林保育課長","answer":"ご説明させていただきました参考としての配置例に対して、ですけれども、おおむね同じような考え方で標準算定されているものと思われます。旧都基準というものが、現在、既に存在していない関係上、定かに照合することはできません。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"都の財調の部分において、今までどおり事業をしている者に対しては、そのままお金が行っているという話だったんです。そういったところにおいては、看護師とか、栄養士の部分は入るんではないかなと思うんですが、いかがか尋ねました。","respondent":"小林保育課長","answer":"普通だと２名程度の調理職員がいますよねということですけれども、ご承知のとおり、各園２名の調理師は配置しておりません。区としての判断の結果と考えています。","id":"exchange-048"},{"speaker":"飯沼委員","kind":"意見","question":"子どもが４４８人増えているにもかかわらず、私は、ここが品川区の考え方があらわれているところであると思うんです。どう考えていらっしゃるのか、ここがきっと品川区の工夫とおっしゃるんだと思うんですが、ここの考え方を聞かせてくださいとの意見を述べました。","respondent":"小林保育課長","answer":"４月１日の想定しております定数は５９１名、それは定数の増、あるいは新規の需用に対応した増です。５１０名に対して、人数が５９１名と多いのは、必要な保育士をきちっと配置しているととらえていただければと思います。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区もそうしてほしい」といった声とか、お散歩なんかもほんとうに減っているという状況が出ている」といった切実な声をたくさんいただいています。こういった保育の質、私は、この職員の問題で明らかに低下をしていると思うんですけれども、いかがか尋ねました。","respondent":"小林保育課長","answer":"すべて１００％ないと言い切ることはできませんが、基本的には、見聞きしてございません。職員間の連携を密にして対応していく、意欲を持って対応しているところでございまして、子どもに十分対応できていないというふうには。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私立保育園の運営費助成の見直し案が出ているんですけれども、都基準をきっちり守ってほしいなと思うところでは、ぜひ保育水準を守っていただきたい。それから、十分な話し合いをお願いしたいという声も届いていますので、この点、お答えください。","respondent":"小林保育課長","answer":"私立保育園は、区立保育園と同様に認可保育園として、この間、品川区の子どもを育ててきていただいております。その状況に応じて、しかしながら時代の背景をしっかりととらえた上で、将来を見据えたご協議、ご相談を、今後も続けてまいりたいと思います。","id":"exchange-051"},{"speaker":"渡辺委員","kind":"質問","question":"１２１ページ、１３９ページ、里山再生活動参加費（早川町）のことを伺いたいと思います。児童センター事業の品川区の独自な部分、そして国と都の財源の割合を、最初に伺いたいと思います。","respondent":"諸岡児童課長","answer":"０歳から１８歳まで、それから小学生、中高生に至るまでの全面的な事業が展開されております。すくすく訪問事業でありますとか、あるいはティーンズプラザ事業、こういった事業を展開しているものです。","id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"先ほど伺った財源のほうの割合ということを簡単にお答えほしいと求めました。それから、委託先等のこれまでの経緯だとか、変更がある、そして経緯と影響等を伺えればと思います。","respondent":"諸岡児童課長","answer":"そして、職員数でありますけれども、児童センターの職員数でありますが、大体１館当たり３名ないし４名、規模に応じて配置をしております。この委託館につきましては、事業者につきましては、事業者の都合と、また契約の変更等に応じて、年度によって事業者の変更が生じておりま…","id":"exchange-053"},{"speaker":"渡辺委員","kind":"質問","question":"今、少数館を中心に委託先の変更の経緯、いろいろな変更点があるかと思いますが、その辺のところを、ちょっと詳しく伺えればと思います。こういった委託先の変更が生じる場合、決定する経緯とか、決め方、あるいは、今現在で把握されている影響点等ありましたら、お願いします。","respondent":"諸岡児童課長","answer":"委託先の変更につきましては、事業者のほうから、事業縮小に伴っておろさせてほしいような申し出がある場合もあります。基本的にはこちらのほうで受託要件、仕様書を定めまして、職員についての資格と要件等を定めまして、入札により業者を選定しております。","id":"exchange-054"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう意味で、公園の必要性はまた別の機会に要望してまいりますが、それゆえに、児童センターが大変注目されているんだなという気がしています。たくさんあると思うんですが、特記すべき点だけ、背景として教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"ティーンズプラザということで施設整備を行いまして、中学生、中高生の利用も増えてきております。あるいは、創作活動等の活発な活動が展開されておりまして、その辺が品川区としてもその辺が大きな特徴であると考えています。","id":"exchange-055"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その辺の把握と、今後の対応の２点、伺いたい。それと児童センターという拠点の今後の全体の、長期的な考え方を伺えればと思います。","respondent":"諸岡児童課長","answer":"児童福祉法の改正が平成２１年４月に予定されておりますけれども、乳幼児への対応、それから核家族化に伴う育児の孤立化に伴う対応も。それに伴いまして、ティーンズプラザでは、そこと連携を図りまして、今後、青少年事業を活発に展開していきたいと考えているところです。","id":"exchange-056"},{"speaker":"渡辺委員","kind":"提案","question":"最後に、児童センターに対しまして、要望、提案をさせてほしいと求めました。平成１３年に進められたという経緯を伺ったのも、品川区では現在、どのような考えをお持ちか伺えればと思いますとの意見を述べました。","respondent":"諸岡児童課長","answer":"この３年間、児童センターの美化作戦ということで、３年間努めてまいりました。そのご趣旨につきましては、今後、私どもとしても研究させていただきたいと考えています。","id":"exchange-057"},{"speaker":"渡辺委員","kind":"質問","question":"次に、１２１ページでオリンピックムーブメント事業について、伺いたいと思います。１０月に開催箇所選定に向けて、東京都も相当、力を入れる年度になるかと思いますが、概要を伺えればと思います。","respondent":"久保田行財政改革担当課長","answer":"会場につきましても、当初、荏原文化センターを予定をしておりましたけれども、平塚小学校等学校施設も使いながら展開をしたいと思います。スポーツの振興という意味も込めまして…","id":"exchange-058"},{"speaker":"渡辺委員","kind":"質問・要望","question":"５月のＥＢＡＲＡ夢フェスタもそうなんですが、１０月までの継続的な動きも、その辺を伺いたい。品川区として、１０月のぎりぎりまでこだわりを持って取り組んでいただきたいという要望とあわせて、ご見解を伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"スポーツ振興のためには、ぜひ継続して、こういった事業も続けていきたいと考えているところです。オリンピック開催に向けましても、１０月の開催都市決定までは、オリンピック招致へ向けていろいろと協力はしていきたいと考えております。","id":"exchange-059"},{"speaker":"武内委員","kind":"質問","question":"それから、医療保健政策包括補助金については、ここに感染症対策費ほか２事業とありますが、この２事業について、お伺いします。この辺の関係、品川区としてはこの二つだけなのか、お伺いしたいと思います。","respondent":"片田建築課長、小林保育課長、山岡健康課長、志村生活福祉課長","answer":"公布されてから６カ月以内の施行ということで、６月４日の予定で考えられているところです。三年の中で、新築物件の１割ぐらいが認定申請を受けるだ… ３区分以降で補助金額が増額するような制度に修正をするということで、現在、東京都の予算特別委員会でも審議されていると聞いております。来年度以… ここに記載されています感染症対策費ほか２事業ですが、一つが飼い主のいない猫対策事業です。もう一つが、予防接種支援事業です。 現在のところ、まだまだ貸付実績が伸びておりません。今後…","id":"exchange-060"},{"speaker":"武内委員","kind":"質問・要望","question":"品川区ですべて委託されているので、六つ、七つある事業全部受けてやっているのかどうか、もう１回、確認をしたいと思います。２３区で初めてＨｉｂワクチンということでやりますけれども、この補助金が使えるのかどうか、確認をさせてほしいと求めました。","respondent":"志村生活福祉課長、片田建築課長、山岡健康課長","answer":"この事業そのものの実施主体は東京都が一手に行っているものです。例えば居宅で生活の安定のことに乗ってくる事業もありますので、そのときは… それから、職員の対応の状況のお話がございました。トータル的な評価については行政が行いますけれども、民間との連動の中で評価できるものと考えておりま… 今回、ここで予算計上していただいているものにつきましては、現在、やっている任意予防接種、水疱瘡、おたふく風邪の分です。…","id":"exchange-061"},{"speaker":"武内委員","kind":"質問・要望","question":"品川区はやっているわけですから、積極的に東京都から予算を取るような形でやってもらいたい、これはぜひ要望します。もう１点、その辺を何か聞いていれば、説明を求めました。","respondent":"片田建築課長、山岡健康課長","answer":"ご案内のとおり環境共生住宅ということで助成支援ということで、３０万円を限度として、工事費の１０％という形で助成を行っております。それらの認定基準と連動することによって、そういうことを考えられる要素もあると考えていますの… Ｈｉｂワクチンの供給量についてですが、メーカー側とも情報交換をしながら、一定の供給量を確保できるように努力してまいりたいと考えております。よろしくお願いします。","id":"exchange-062"},{"speaker":"川西委員","kind":"質問・要望","question":"使用料でもう一つお伺いしたいんですが、地域のシルバーセンターによって、大幅に１桁から３桁まで使用回数が違っております。これは、地域事情とか、使い勝手がいい、悪いとかいろいろあるかと思いますが、その辺についてお伺いいたします。","respondent":"堀越生涯学習課長、永尾高齢事業課長","answer":"そのほか、しながわ中央公園の多目的広場につきましては、９割程度の使用率です。平成２１年度計画をしております荏原平塚中学校の跡地のグラウンドの計画ですとか、今後も整備を進めていきたいと考えているところです。 １９年度の目的外の使用の状況を判断して、平成２０年４月以降の状況の推移などを勘案して、回数等を決めております。なお、南品川、旗の台シルバーセンターにつきましては、平成２１年度は工事に入る関係で…","id":"exchange-063"},{"speaker":"川西委員","kind":"質問・要望","question":"来年すぐのことではないんですけれども、それを伺ったわけなので、展望をお知らせいただきたい。シルバーセンターで伺ったのは、地域によって、１桁から３桁まで使用回数がこんなに違うのは、どういう事情によるものか伺いたい。","respondent":"堀越生涯学習課長、永尾高齢事業課長","answer":"運営につきましても、地域の方々がより主体的にかかわれるような、そのような形で地域スポーツの振興を図っていきたいということを考えています。ソフトの面でも… シルバーセンターにつきましては、例えば平塚橋などについては、複合の施設があるので、そちらのほうに流れたりというような関係で、近隣に集会所等があると、そちらに流れる傾向があると考えています。","id":"exchange-064"},{"speaker":"川西委員","kind":"質問・要望","question":"使っていらっしゃる関係者の要望から、そういう区民要望をどう取り入れて、区政の中でつくっていこうとされるのか。所有している民間会社が譲ってくれたら、少年野球場にしたいと思っているという話を伺ったんですけれども、これはどうなったんか尋ねました。","respondent":"永尾高齢事業課長、濱野区長","answer":"こちらの予算書のほうに載っているのは、使用料を全額、ないし５割取る方について載っているという状況です。 これは、その地域の方々からは大変要望が強かったわけです。区内で非常に需用の高い運動の施設として使わせてほしいという声が、ほかの地域から起きますね、ということで申し上げたものです。","id":"exchange-065"},{"speaker":"川西委員","kind":"質問・要望","question":"区から、シルバー人材センターを使ってほしいということを依頼されているのかどうかということを、伺います。物理的にいろいろなリニューアルとかありますから、そういうものも含めて、どのぐらいの月数があくのか教えていただきたい。","respondent":"諸石交通安全担当課長、齋藤住宅課長","answer":"料金につきましては、まずその日にどのぐらいの収入があったか、翌日に区のほうに報告が上がってまいります。それから、シルバー人材センターの委託の関係ですが… 自主的に退去された方が３件ほどいらっしゃいます。次に、あいてからリフォームをする期間は大体２カ月、３カ月ぐらいかかっております。","id":"exchange-066"},{"speaker":"川西委員","kind":"質問・要望","question":"４３m2なんですが、これでどうしてこんなにあいているんでしょうと、自治会長がおっしゃるんです。その辺、一言、二言で結構ですから。","respondent":"齋藤住宅課長","answer":"都営住宅にあきがあるということで、私も何度も問い合わせをいたしました。あいているわけではないんだと、募集期間に合わせてあかしているんだという言い方をしておりますので、なかなか難しゅうあります。","id":"exchange-067"},{"speaker":"川西委員","kind":"質問・要望","question":"これはどういう故なのか。やる気があるのか、ないのかということをお答えほしいと求めました。","respondent":"阿部経理課長","answer":"科目存置ですけれども、この売払の希望の方はいらっしゃいますけれども、決定までにかなり時間がかかるということと、今現在、平成２１年度について、売り払うと確定しているものは、まだ１件もございませんので、今回は、科目存置という形になっております。","id":"exchange-068"},{"speaker":"川西委員","kind":"質問・要望","question":"まちづくりの点から、できるだけ解決できるものはしていただきたいというのが要望です。それから最後に、１４２ページの城南小学校の用地買収の経緯と、今後の使用目途についてお答えください。","respondent":"田村庶務課長","answer":"それと合わせて購入しようです。昭和３０年前半でございましたので、それも見込んで、購入したものです。","id":"exchange-069"},{"speaker":"藤原委員","kind":"質問","question":"１１４ページ、１２０ページ、お伺いします。オリンピックムーブメント事業から伺いますが、この事業の目的は、２０１６年に東京にオリンピックを誘致するということのためにあるんか尋ねました。","respondent":"久保田行財政改革担当課長、堀越生涯学習課長、金子産業振興課長","answer":"オリンピックムーブメント事業について、お答えいたします。当然、そういう考えはあるんですけれども、そういった面もとらえながらオリンピックムーブメン… 都から委託を受けまして、地域スポーツクラブの設立に向けた準備を、地域の方々に中心になっていただいて準備を進めているものです。… 広域観光まちづくり支援事業についてのお尋ねですけれども、２年ほど前に、この４者で合意して実施することに至ったものです。…","id":"exchange-070"},{"speaker":"藤原委員","kind":"質問","question":"行財政改革担当課長の答弁を伺って、どんなことをしてでもオリンピックに来てほしいという気持ちが全然、すごく感じておりました。何で今回、こういう形で補助が来たのか、改めて説明を求めました。","respondent":"堀越生涯学習課長、金子産業振興課長","answer":"これをさらに拡充をさせていきたいと考えているのが、地域スポーツクラブの設立の目的です。より自主的な事業の企画運営をさらに広めていく、これが設立の目的、趣旨です。 平成２０年度は、それから周辺の民間の整備の補助、例としてはこの程度ですね。広域観光まちづくり支援事業を、そちらは実施に至らなかったんですが、施策を東京都のほうで組み立てたものです。","id":"exchange-071"},{"speaker":"藤原委員","kind":"質問・要望","question":"スポーツクラブと広域の観光については、自分でもずっと追っていきたいと思っていますので、よろしくお願いします。熱い思いといいますか、反論があるなら、ぜひちゃんと言ってほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"オリンピック招致についてですけれども、基本的には、オリンピック招致活動については、区としては賛成の立場であるです。オリンピック招致といった部分も当然ですけれども、私どもは、東京都のオリンピックムーブメントに協力をしていきたいと考えています。","id":"exchange-072"},{"speaker":"山内委員","kind":"質問・要望","question":"考え方をお尋ねさせていただきたいんですが、そして耐震シェルター等設置助成とありますけれども、この二つの考え方を伺いたいんです。これを利用する人は、どちらを利用したらいいのかというところがあるんですけれども、その二つの考え方を、まずちょっとお尋ねさせてください。","respondent":"片田建築課長","answer":"基本的には、耐震化率を、平成２７年度を目途に９０％ということで考えております。ある意味ではつなぎといいましょうか、そういう中での位置づけで、すぐに工事はできませんという方を対象に考えていきたいと考えております。","id":"exchange-073"},{"speaker":"山内委員","kind":"質問","question":"建築課長から答弁いただきましたけれども、つなぎでシェルターを設置するんだったら、普通はそこで耐震化を考えると思うんです。そのつなぎという意味はどういうことなんか尋ねました。","respondent":"片田建築課長","answer":"できるだけ１部屋を補強する、さらに願わくばそれを強化するということも可能ですけれども、やはり短い期間で簡単にできないかと。そういう中で、間を埋めるような施策ということで、今、考えているところです。","id":"exchange-074"},{"speaker":"山内委員","kind":"質問","question":"品川区も上限で３０万円助成をするという考えの中で、例えば上限の３０万円を超えちゃった場合は、持ち出しでお金を出さなきゃいけない。今住んでいらっしゃる方にとって、いわゆる二重投資になりかねないのではないかなと思うんですけれども、その辺はどうお考えなんか尋ねました。","respondent":"片田建築課長","answer":"大体区の診断を受けて、２割ぐらいの方が何らかのことを考えている、区の助成を受けて改修した方も中にはいらっしゃいます。基本的には、昭和５６年以前の建物、それを対象にしていきたいと考えているところです。","id":"exchange-075"},{"speaker":"山内委員","kind":"質問","question":"では、シェルターを仮に設置されましたと、設置された方が助成を受けたということは、もう区のほうで認識されているわけですよね。耐震化に向けたお声がけというか、まちづくり事業部の中では考えていらっしゃるということで、いいんですかね。","respondent":"片田建築課長","answer":"アメリカなんかですと、大体５５年、イギリスだとを８０年弱ぐらいですかね。やはり本来の建替えの中で耐震化率を上げるのが基本と考えていますので、引き続き、耐震化に向けた働きかけをしていきたいと考えております。","id":"exchange-076"},{"speaker":"山内委員","kind":"質問","question":"木造住宅の耐震診断をするときに、やっぱり行政のほうから補助が、たしか６万円でしたか、出ますよね。診断をする際の助成、それからシェルターを設置するときの助成は併用して使える制度と考えていいんか尋ねました。","respondent":"片田建築課長","answer":"６５歳以上、あるいは２００万円以下の低所得の方であれば、３０万円を限度として支援しましょうと。そういうことの活用もできると思いますけれども、主には、診断を受けなくても新しいものについては考えていきたいと考えております。","id":"exchange-077"},{"speaker":"井上委員","kind":"提案","question":"補助金のほうで１１２ページの都補助金、９４ページの国庫補助金の衛生費補助金、伺います。最後に実施設計、契約、工事着工のスケジュールを伺いますとの意見を述べました。","respondent":"桑村区議会事務局長","answer":"傍聴席のエレベーター設置等ですけれども、私どもが検討させていただきました、営繕部門等に相談させていただいて計上しているものです。おっしゃったように、一定の設計の部分で時間がかかると考えておりますので…","id":"exchange-078"},{"speaker":"井上委員","kind":"質問・要望","question":"コストの面や税金のむだ使いということにならないように、前向きに検討をしていただきたい、区の適切な判断を求めておきたいと思います。２００７年の決算特別委員会で、委員会傍聴者への資料の閲覧を求めた折に、議会側と相談していきたいという答弁をされました。","respondent":"伊勢総務課長","answer":"その後、傍聴人に資料云々ということがありますけれども、基本的にはまずは、議会の内部で十分にご議論いただきたいと思います。それで結論が出た中で、また我々とどういう形がいいのかということをご相談させていただきたいと思います。","id":"exchange-079"},{"speaker":"井上委員","kind":"提案","question":"今、２００５年の予算特別委員会で生活ネットワークは、シルバーセンターの目的外使用をもっと ＰＲしてはどうかという提案をいたしました。２００３年の夜間休日の稼働率が１１.９％ということでしたけれども…","respondent":"永尾高齢事業課長","answer":"本来はそういう目的でつくっておりますけれども、やはり夜間空かしておくのはもったいないということで、目的外使用というものを開始しております。地域の方からのお問い合わせの際には、こちらのほうでも…","id":"exchange-080"},{"speaker":"井上委員","kind":"提案","question":"まだまだいろいろな工夫があり、この二つだけでも十分に利用が広がると思いますので、その辺を進めていただきたいと要望しておきます。主に駅舎のエレベーターの補助なのかなと思いますけれども、ほかに充当している事業があれば、お伺いしますとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"都の補助金のやさしいまちづくりの計画推進費ですが、委員、ご指摘のように、この部分につきましては、平成２１年度予定をしております青物横丁のエレベーター設置の補助金、２基分です。","id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"ここの部分では、それだけということなので、ちょっと款が別になってしまうので、また社会福祉協議会への点字誘導ブロックの敷設などが、こういったやさしいまちづくり計画推進のところで、利用ができないのかなと思ったんですが、そういったところは、これは使えないんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"社会福祉協議会では、その経費については計上しておりません。その意味では、実施できないです。","id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"次は、国庫補助のほうの在宅難病患者訪問介護員派遣について、お伺いいたします。それから、この方たちが訪問介護を受ける仕組みがどのようになっているのか、説明を求めました。","respondent":"高橋障害者福祉課長","answer":"したがいまして、私どもで予定しているのは、２人が対象の予定です。このサービスの提供が中止になりまして、別のサービスに移っていく、つなぎと考えていただければいいかと思います。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問","question":"そのときに、その方たちが難病指定された方というのは、外見でわからなかったりすると思うんです。そこら辺が、利用する方がはっきりとわからないということもあると思うんですが、そういった連携の状況がどのようになっているんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"所定の申請を出していただいた中で、障害者福祉課のほうでは、必要があればサービス提供ということになります。その辺につきましては、保健師の状況の把握の中で、サービスの提供が具体的な形になっていくかと思います。","id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"そうしますと、派遣事業者は、どういった方になるんでしょうか。それが多分家事援助になるんじゃないかなと思うんですけれども、その辺のルールというのはあるんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"それから調理、洗濯択等の家事援助が基本ですので、いわゆる福祉的なヘルパー派遣と同じような形かと思います。その辺のところについては、どうしたらいいのかということでご相談をしていく中で、サービスの提供が具体的な内容になってくるかと思います。","id":"exchange-085"},{"speaker":"井上委員","kind":"確認","question":"利用されるこういった方たちは、保健師が窓口になると考えてよろしいんでしょうか。そこのところだけ確認をさせてください。","respondent":"高橋障害者福祉課長","answer":"難病ですので、基本的には、保健所、保健センターの保健師のほうにご相談し、具体的な内容を、サービスの提供等も含めまして、継続的な相談になるかと思います。","id":"exchange-086"},{"speaker":"若林委員","kind":"質問・要望","question":"昨年の夏でしょうか、品川区とともに国と都の４者で、これから進んでいくという。ここら辺についても、支援事業が、お金がついてくるんでしょうか、含まれてくるのか、そこら辺を教えてほしいと求めました。","respondent":"志村生活福祉課長","answer":"私どもで生活相談等を実施していますけれども、平成２０年７月から、相談件数等が増えてまいりました。例えば、東京都の緊急対策がありますので、そういうところにつなげていくというような対応をとっているところです。","id":"exchange-087"},{"speaker":"若林委員","kind":"質問・要望","question":"どういうふうに自立支援に向けた成果といいますか、そこら辺の様子を、エピソードなんかも含めてお聞かせほしいと求めました。自立の意欲のない方、ここら辺の支援の考え方も、ちょっとお聞かせほしいと求めました。","respondent":"志村生活福祉課長","answer":"アセスメントを行いまして、進路を定めまして、それについてそれぞれ取り組みを図ってまいります。こうした就労支援員が共同して取り組んでまいりますので、毎四半期ごとにチェックを入れて、的確に。","id":"exchange-088"},{"speaker":"若林委員","kind":"質問","question":"はカウンセリング等の１対１のご相談とか、実際にやられているのかどうか、お聞きしたいと思います。もう１点、これからあるのかどうかということを、一つお聞きしたいと思います。","respondent":"志村生活福祉課長","answer":"それから、現在入院されている病院の関係者等の連携なくしては、こうした自立は図れません。ですので、この辺につきましても、引き続きいろいろな角度から模索しながらやっていきたいと考えているところです。","id":"exchange-089"},{"speaker":"若林委員","kind":"意見","question":"でも生活応援としてご案内をしていく、そういう自分の部署内でのつなぎとか、また他の所管との連携を、もう一つお聞かせください。それから、民間についても、お聞かせ願いますとの意見を述べました。","respondent":"志村生活福祉課長","answer":"そうではなくてこうした生活資金の貸付で解決ができてしまうということがありますので、相互に関係が、当然のことながら増えてまいります。この辺につきましても、連携をとりながら、社会福祉協議会も含めてですけれども、民間との連携も不可欠だと考えています。","id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"平成２０年度の滞納率というんでしょうか、収納未済額というんでしょうか、どのぐらいの数字になりそうなんでしょうか。そこから見える特徴は、どのようなものか尋ねました。","respondent":"武内税務課長","answer":"平成２０年度の見込みですけれども、滞納者に対して一生懸命対応させていただいているということで、３０％程度の徴収率を見込んでおります。所得階層別の滞納者の状況ですけれども、平成１９年度と１８年度の資料に基づいて説明しますと…","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"２００万円以下の層の滞納が増えてきているということですね。そして平成１９年度は３５％と上がってきているんですが、２０％という見込みよりも、もうちょっと上に目標を上げてもよろしいのではないか尋ねました。","respondent":"武内税務課長","answer":"やはり景気の状況と失業率の状況等を考えますと、歳入が確実という部分で、まず当初予算は設定しています。","id":"exchange-092"},{"speaker":"高橋委員","kind":"意見","question":"今、担税力というお話でしたが、ところで地方税法の改正があって、区民税と年金を受けている方との年金と区民税との関係が変わるのではないかということなんですが、そのあたりのことをご説明いただけますかとの意見を述べました。","respondent":"武内税務課長","answer":"６月の時点で納付書をお送りして、今年の１０月からは、そこから差し引きするということです。納税されている方に対して、年金のほうから差し引きするという制度ですので、ご理解のほどをよろしくお願いいたします。","id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"平成１９、２０、２１年度、すべてそうなっているんですが、全然使われていない減債基金はどこに行ってしまうのでしょうか。どのような仕組みになっているのか、説明を求めました。","respondent":"日下部企画財政課長","answer":"３６０ページに出てまいりますけれども、これは平成２１年度におきまして償還必要な金額で、この総額が４１億７,０００万円ほどあります。財調算定されたものについて、一般財源のほうから、一種の振り替えをしていくという形で対応をしているというものです。","id":"exchange-094"},{"speaker":"高橋委員","kind":"質問","question":"いろいろな使い道があるというか、こういう言い方をしたらあれかもしれませんが、かなり自由に使える基金ということで、いろいろな歳出の調整をしているという認識ではいけないんか尋ねました。","respondent":"日下部企画財政課長","answer":"広い意味では財政調整の基金の一つの種類でありますので、そういった意味では、いろいろ幅広い財源の調整にも活用している。例えば自治体によっては、あえて減債基金を設けないで、財政調整基金一本で減債にも活用しているという自治体もあります。","id":"exchange-095"},{"speaker":"高橋委員","kind":"意見","question":"１０年間に基金全般の繰入の状況、今年度は３８億円マイナスですが、お願いしますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"実は、これから１０年間を考えてみますと、起債の償還が必要な部分が、大きく見まして約３００億円あります。年間３０億円に相当する返済が必要ということで、もう少ししっかりとした返済についての計画性を持って対応していく必要があるだろうと考えています。","id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"今、起債のお話が出たんですが、１４２ページの特別区債なんですが、一般財源等が余裕というわけではありませんが、一般財源等があるのに、わざわざ起債をするというのは、７億円なんですが、平成１９、２０年度は０円で、今年度は７億円起債したのは、どのような事情なんか尋ねました。","respondent":"日下部企画財政課長","answer":"起債にもよるんですが、実は、こちらの城南小学校の用地の購入につきましては、財調の中で、起債償還分については基本的に全額面倒を見ると、つまり区の持ち出しはございませんので、こういう形で活用を図っていくというものです。","id":"exchange-097"},{"speaker":"高橋委員","kind":"質問","question":"最後、品川歴史館に行ったときに、領収書をもらったんですが、Ａ４版の半分ぐらいのすごく大きいものだったのですが、それをその大きさでやらなければいけないという、何か条例とか、法律の決まりがあるのか尋ねました。","respondent":"堀越生涯学習課長","answer":"領収書なんですが、すみません、ちょっと調べて、後ほどご答弁します。","id":"exchange-098"},{"speaker":"本多委員","kind":"質問・要望","question":"２点、質問いたします。１２６ページの財産売払収入なんですけれども、平成２１年度は、その点を説明を求めました。","respondent":"堀越生涯学習課長、阿部経理課長","answer":"スポーツの部分は首長部局のほうに移すような弾力的な組織の運営ができることになっておりますが、文化財の部分については除くとなっております。そういった法の趣旨を受けまして、文化財については、引き続き教育委員会事務局で… 平成１９年度には旧旗の台寮を売却していますけれども、金額はわからなかったので、補正をお願いしているです。今後も、年度途中の中で売却額がはっきりするものということについては、補正でお願いをするという形になろうかと思います。","id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"区内でどのぐらいの可能性というか、規模があるのか、もしわかれば教えていただきたい。不動産のほうは１目なんですけれども、２目の物品売払収入のことも、内容について教えてほしいと求めました。","respondent":"堀越生涯学習課長、松代管理工事課長、島袋品川区清掃事務所長","answer":"特に平成２０年度予算と平成２１年度予算というところで、予算の組み立てについては対応をしてまいりたいと考えております。… 引き続き機能を残しながら通路化する方針といったものが６７路線、廃止等々で払下げが十分可能だろうとしているものが８８路線あります。今後は… 不用品売払代金としまして、清掃の平成２１年度に取り換える小型プレス６台分かける４０万円ずつということで、２４０万円の代金です。","id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう点から見て、予算の数字から見ると、この事業のあり方があまり変わっていない点がどうなってくるのかなということを教えていただきたい。その辺が売払に入ってこないのか、ちょっと素朴に思ったので、説明を求めました。","respondent":"堀越生涯学習課長、島袋品川区清掃事務所長","answer":"もう１点、中味についてですが、いろいろ文化財の保護の奨励金ですとか、修理の補助金といったものも計上しておりまして、執行しています。新たな掘り起こし周知、それから保護をあわせて… コンテナにつきましては、１０月からクレーンのごみが少なくなりましたので、平成２０年度内に、５０台のコンテナを売却しております。残りがあと７９台なんですけれども、売った代金よりも処分代金のほうが高いはずなので…","id":"exchange-101"},{"speaker":"阿部委員","kind":"質問","question":"１３１ページ、１４７ページ、本会議録・委員会記録作成経費についてお伺いしたいと考えています。犬の登録料は、これを見ると１件３,０００円計算になっていると思うんですけれども、これは鑑札料実費と考えていいんか尋ねました。","respondent":"河野指導課長、上川内戸籍住民課長、荒井品川区保健所衛生課長、島袋品川区清掃事務所長、桑村区議会事務局長、伊勢総務課長","answer":"私のほうからは、教育費負担金、旧八潮北小学校跡校舎利用に関するご質問にお答えいたします。保守点検費用の５５.０７％を明晴学園… 平成２０年８月に、総務部と区民生活事業部と協議をしまして、品川区の基本方針を定めました。現実に当たった場合に… 私のほうからは、犬の登録、鑑札の交付の手数料について、お答えいたします。犬の登録・鑑札につきましては、鑑札の札の交付と… 現在のところ大体、１日に１０件か２０件あるんですけれども、ほとんどは現状回復命令に従っております。…","id":"exchange-102"},{"speaker":"阿部委員","kind":"質問・要望","question":"指導に従っているということで、多分ないだろうけれども、とりあえず予算書に上げるために１件書いたと考えてよろしいでしょうか。これは要望ですけれども、要望としては、ご検討ください。","respondent":"市川教育次長、上川内戸籍住民課長、島袋品川区清掃事務所長","answer":"旧八潮北小学校で教育活動を展開するに当たりまして、区のほうでは、明晴学園の教育活動に対して一定の理解を示した上で支援をしてまいりました。… プライバシーをむやみに取ることは犯罪ですというポスターも、各自治体の窓口に掲載するようにということで、国も取り組んでおります。… 本区の場合、持ち去りパトロール隊、どちらかというと、過料をかけることよりも、追い払うということが中心になっております。…","id":"exchange-103"},{"speaker":"阿部委員","kind":"質問・要望","question":"原則がそうであることを踏まえた上で、あえて品川区として何かできないかということをお尋ねいたしました。問題意識を持って内部で検討していただきたいと思うんですけれども、その点について、ご答弁を一言お願いします。","respondent":"市川教育次長、上川内戸籍住民課長","answer":"先ほど申し上げました繰り返しになりますけれども、私立の学校の運営については、やはり公と私の区別をつけた上、区としては対応すべきものと考えております。 私どもも考えてまいりますが、国のほうとも相談しながら考えていきたいと思っています。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問","question":"５０ページの特別区民税について、伺います。うち２００万円以下の人数、先ほど紹介いたしました、生活保護基準１６０万円以下の方は何人おられるか尋ねました。","respondent":"武内税務課長","answer":"はっきりとした数字はまだ出ておりませんけれども、大体、２万５,０００人ぐらいと予定しております。２００万円から７００万円の方が８万１,１４３人、７００万円を超える方は１万５,０６２人で、平成２０年度は１９万５,６１２人となっております。","id":"exchange-105"},{"speaker":"安藤委員","kind":"質問・要望","question":"平成１７年度、２１年度のそれぞれの住民税の額、これは年金２００万円の単身者の方の例でお聞きします。住民税、国保料、介護保険料、それから所得税、それぞれの額と、合計金額、平成１７年度と平成２１年度を比較して教えてほしいと求めました。","respondent":"武内税務課長","answer":"２００６年については、住民税は１万円弱、所得税については３万円弱というような金額だと思います。住民税はフラット化がありましたので、平成２０年度と２１年度は、税源移譲が行われておりますので、住民税と所得税の関係は変わっておりません。","id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"ほぼ１８万円なので、何と約１カ月分の年金が消え、４年間で１２万円上がっております。これは憲法違反なのではないでしょうか、いかがか尋ねました。","respondent":"武内税務課長","answer":"あるいはまた少子高齢化のため、全員が社会保障料を負担していくというもとで行われておりますので、特にこれが憲法違反だとは考えておりません。","id":"exchange-107"},{"speaker":"安藤委員","kind":"質問","question":"品川区独自の方法などで検討できる部分は検討していきたいとお答えされておりますけれども、具体的に、１週間前に相談したらどうなるんでしょうか。１週間前に相談できますということを区民が知っていないと、そういった相談体制の周知、通知というのは具体的にどのようにするのか尋ねました。","respondent":"武内税務課長","answer":"さまざまな住民の会合等、一つには民生委員協議会、あるいは高齢者クラブ等に説明に入っております。そういった中で、委員、言われるとおり、生活の激変がありましたら、どうぞ事前にご相談くださいということは説明しています。","id":"exchange-108"},{"speaker":"安藤委員","kind":"質問・要望","question":"１週間前に、どのような態勢をとってくれて、どのように相談に乗ってもらえるんですか。そこら辺、具体的なところを詳しく教えてほしいと求めました。","respondent":"武内税務課長","answer":"委員言われるとおり、納付日というのがありますので、それ以前に相談にきていただければ、ストップするということも、当然できますので、それは私どものほうの徴税の担当の職員のところにお出でいただければと考えております。","id":"exchange-109"},{"speaker":"安藤委員","kind":"質問","question":"６月に税制が変わりますというお知らせが行くと思うんですけれども、そういった対応があるのかということを、一つお伺いします。第３６条の減免の周知徹底、活用をすべきだと思うんですけれども、あわせて伺いたいと思います。","respondent":"武内税務課長","answer":"もし納付期日までにお支払いできない場合については、必ず連絡をしていただきたいということをお願いしております。これは何も、年金の特別徴収の方に限って言うことではなくて、品川区民皆さんに周知を図っているところです。","id":"exchange-110"},{"speaker":"安藤委員","kind":"質問・要望","question":"年金天引きの方に限ってではないということですけれども、年金天引きの人は、今までとは違って年金から否応なしに天引きされてしまうわけですから、特別に天引きの前に通知を行うぐらいのことを、ぜひやっていただきたいと、私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"山路委員","kind":"質問・要望","question":"午前中の質問で、産業振興に生かされるところまで突っこんでもいいのではないかと思いますが、確認の意味でお伺いいたします。両方がうまくいくような交流のあり方も、今後考えてもいいのではないかと思いますが、どのようにお考えか尋ねました。","respondent":"金子産業振興課長、冨岡高齢福祉課長、河野指導課長、小野区民課長","answer":"ベンチャー創業支援センターのお尋ねですけれども、若干ご説明申し上げましたが、さらに一層積極的に取り組んでいきたいと考えております。 そちらから訪問ができ、あるいは住宅にお住まいの方が高齢者になっても、ケアを利用できるという形で整備をしてまいりたいと考えています。… 平成１９年度から始まりまして、主に実験、観察のときにご協力をいただくという内容です。１９校、１,２５２時間、支援員に協力をお願いした実績で… 水と緑の市町村交流についてのお尋ねにお答えいたします。私どものほうも…","id":"exchange-112"},{"speaker":"山路委員","kind":"質問","question":"これから基本設計で、来年から建築に入っていくと思いますので、コーディネーターという非常に大事な役割が必要になってくると思うんです。その辺については検討されているのか、お伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"建物がいろいろな目的をあわせて持っているという意味におきましては、コーディネーター機能は大事かと考えています。これからの課題ですけれども、大体、そんなような図かなと考えています。","id":"exchange-113"},{"speaker":"山路委員","kind":"質問・要望","question":"もう少しあるみたいのですので、この国庫補助金は、説明のときに、林町という説明がありましたので、それについてお伺いしたんですが、今度、住情報センターも、平成２１年度からやるということですが、その中でコーディネーター機能を強くしていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"大沢委員","kind":"質問","question":"７７ページ設備使用料等、今度は８５ページの土木手数料、表記の仕方を伺いたい。それから後半、１３９ページのリサイクル資源売払収入、資源回収事業、それから、時間があれば９９ページの目黒線の緑道を伺いたいと思います。","respondent":"堀越生涯学習課長、松代管理工事課長","answer":"６９ページ、文化センターでお使いいただくマイクですとか、そのような設備機器のことです。等というところが、荏原文化センターの部分でありますが、こちらは、喫コーナー、行政財産の使用料という形で、この等の中に含んでいるもので… それに気づきまして、m2に改めて訂正したものです。ご理解のほどを、よろしくお願いします。","id":"exchange-115"},{"speaker":"大沢委員","kind":"質問・要望","question":"１３９ページになります。そこの部分について、品川区の現状をお聞かせ願いたいと思います。","respondent":"秋山資源循環推進課長","answer":"行き場がない、まだ引き取りを拒否されたということはございませんで、順調に資源化センターのほうで処理をしているという状況です。","id":"exchange-116"},{"speaker":"大沢委員","kind":"質問","question":"これで済んだということで、これから古紙のリサイクル市場が落ち着いてくるのかなと、いくらか好転するのではないかと思います。１kg６円を支給するということで、そこら辺の見通しを、ちょっと伺いたいと思います。","respondent":"秋山資源循環推進課長","answer":"平成１９年度は１億６,０００万円程度、平成２０年度も、１億９,０００万円程度入る予定ではあります。これにつきましては、市況とは関係なく支払っているというのが状況です。","id":"exchange-117"},{"speaker":"大沢委員","kind":"質問","question":"平成１８年度については６,３００万円余、平成１９年度は６,８００万円余ということで、年々増えております。そういう危機感を持たれたほうがいいと思うんですけれども、そこのところは、いかがお考えになりますか尋ねました。","respondent":"秋山資源循環推進課長","answer":"集団回収につきましては、回収した古紙について、業者のほうの収入ということになりますので、私どもの売払収入の中に入っておりません。すべての資源ですけれども、１kg当たり６円をお払いしているという状況ですので…","id":"exchange-118"},{"speaker":"大沢委員","kind":"質問・要望","question":"ようやく今度、完成を見るわけですけれども、そこの中で、協力をしていただいた方たちに対する対応の仕方を、私は今回、お伺いをしたいと思います。長くなっちゃうので、第１緑道と第２緑道の沿線で結構です。","respondent":"浜脇街路事業担当課長","answer":"それの大体３分の２ですので、約１,５００件ぐらい、順序よく洗足のほうに向かってやっています。まだそのうちの１,２００件ぐらいが、若干、残っているというのが現状です。","id":"exchange-119"},{"speaker":"大沢委員","kind":"質問・要望","question":"補償交渉をやっていただいている。東急なわけですけれども、東急が補償交渉の窓口になっているのは東急本体なんでしょうか、どちらか教えてほしいと求めました。","respondent":"浜脇街路事業担当課長","answer":"一時的には、東急、あるいは土木会社といったものが組んでご説明をしているです。最終的な責任を負うのは、事業団である４社です。","id":"exchange-120"},{"speaker":"大沢委員","kind":"質問・要望","question":"最終的な責任を負うのは４社ということですけれども、交渉に当たっているのはどのような会社なのか、教えてほしいと求めました。","respondent":"浜脇街路事業担当課長","answer":"私どもから、東急を通して委託をしている補償会社です。それらについて、私どもが判断をいたしまして、最終的にはその会社に任せてやってあります。","id":"exchange-121"},{"speaker":"大沢委員","kind":"質問","question":"当事者は事故の過失によって保険会社と交渉をしているわけではなくて、あくまでも協力の代償として、そういうような交渉を行わなければならない。交渉を運んでいるきらいがあるということで、そのような話を聞くんですけれども、そこのところはどのようにご認識をされておりますか尋ねました。","respondent":"浜脇街路事業担当課長","answer":"それに基づいてやっているものですから、４社が指示して、補償会社に指示をしているですので、決して補償会社が勝手にやっているのではございません。もう１回フィードバックして、我々の中で検討した結果を持って、東急も含めて行かせているところです。","id":"exchange-122"},{"speaker":"大沢委員","kind":"質問・要望","question":"算定に当たっては、そこのところを斟酌されながら交渉に当たっていただきたいということで、区のほうからご助言をしてほしいと求めました。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"やはりおいしいということもありますので、改築されている小学校、中学校はどういうふうな考え方を持っていくのかということお聞きします。それの進捗状況がどうなっているのかというところを、お聞きします。","respondent":"田村庶務課長、久保田行財政改革担当課長、堀越生涯学習課長","answer":"やはり全都的に、大体３割ぐらいを目途に事業を推進したいという目標値がありますので、さらに延長してやりたいという考え方です。… 東京都と区市町村によります共同推進事業と位置づけられておりますので、運営主体につきましては、東京都と区が共同で進めていくといったところです。 そして平成２１年度の３カ年の事業で、平成２２年４月のスポーツクラブの設立に向けまして、品川・大崎地区で検討を進めているところです。…","id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"ですから、その方たちと一緒に気運を高めていくということが仕掛け的には必要なのではないかと思いますので、それに関してのお考えをお聞きします。これは、ほかのところで、うまくいっている例はあるんか尋ねました。","respondent":"田村庶務課長、久保田行財政改革担当課長、堀越生涯学習課長","answer":"平成２２年度まで東京都のほうが実施するということで、１０分の８の負担金というのはすごく大きな比重なので、そのように考えております。 実際の事業を進めていく中で、そういった事業を進めてまいりますので、連携は必要だと考えています。ぜひきていただきたいと考えておりますので… 検討を進めているメンバーの方々と、視察、調査等も行っているところです。品川・大崎の状況を見ながら、自分たちの地区においても…","id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"区としてどういう方向でやっていくのかというのは、その間に見極めていただきたい、推進をしていただきたいと思っています。それこそ、子どもたちも含めて一緒に取り組むことによって、自分たちの夢というか、希望が出てくると思いますので、ぜひお願いしたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-126"},{"speaker":"須貝委員","kind":"質問","question":"私は、４９ページ、歳入、１２８ページ、基金繰入金、９０ページの学校施設整備費を絡めて質問します。年間３００万円以下の所得者は、今後も区民税や各種交付金はさらに減少するのですか、ちょっと説明を求めました。","respondent":"日下部企画財政課長","answer":"本会議等でご答弁申し上げてまいりましたように、それが地域経済、それから区民生活にもかなり影響が出ているということで認識しています。このような形で、これから先、かなり収入面は厳しい見方をせざるを得ないだろうと考えております。","id":"exchange-127"},{"speaker":"須貝委員","kind":"質問","question":"歳入約１,４００億円に対して、２０％の約２８０億円が、いいんでしょうか。今、このような日本経済の状況から見て、いいんか尋ねました。","respondent":"日下部企画財政課長","answer":"そのときどきのいろいろな政策の展開によりまして、例えば福祉施設の整備を重点的に進めるときには、やはりどうしても民生費がかなり大きくなる。そういう投資的な経費、これがどういう形で組み立てをしていくのかによってかなり増減をしてまいりますので…","id":"exchange-128"},{"speaker":"須貝委員","kind":"質問","question":"物を大事にしろという中で、物の大切さを子どもたちに教えているのに、子どもたちの教育にとって果たしてこれはよいことなんでしょうか。その辺をちょっと、ご見解を説明を求めました。","respondent":"日下部企画財政課長","answer":"品川区で学校の改築等を進めておりますけれども、やはり一応建築後５０年を経過した、またこれは一品川区だけの問題ではございません。ほかの２３区におきましても同様でありますし、いろいろ厳しい状況はありますが、最善の努力を尽くすのが行政の責務ではないかと考えておりま…","id":"exchange-129"},{"speaker":"須貝委員","kind":"質問","question":"よく濱野区長も、今は１００年の一度の大不況、大変な時代を迎えたと。こういう事業を急速に一気に押し進めるということが果たしていいんでしょうか、果たしてこれがいいんでしょうかというふうに、再度説明を求めました。","respondent":"日下部企画財政課長","answer":"平成２１年度は、いろいろな要素が重なりまして、かなり学校関係の経費がかさんだ。改築に踏み切るというようなケースもありますし、この間の経過もありますけれども、全体的な状況を踏まえて判断をしたというものです。","id":"exchange-130"},{"speaker":"須貝委員","kind":"意見","question":"今、こういう状況を見ても、堂々とやれる。国民、区民の所得が落ち込んでいる中で、もう少しそこに予算をシフトするというようなことも大切ではないかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-131"},{"speaker":"堺委員","kind":"質問・要望","question":"１００年に一度という思ってもみなかったような厳しい状況下での船出となってくるという意味から、プレス発表でしたでしょうか、出ておりました。そういう中で今後の確認といいましょうか、勉強のために教えていただきたいのは、計上されているわけです。","respondent":"武内税務課長、日下部企画財政課長","answer":"そういう数字を考えますと、実質的にはもっと大きなマイナスになっているです。平成２０年度の決算の見込みにつきましては、平成２１年度につきましては、全体的にマイナス５％以上あるということで計上をしています。 平成２１年度の見込みでまいりますと、約２割企業収益の悪化に伴いまして、市町村民税法人分が２割落ちるという見込みに立っております。私ども、品川区の見込みといたしましても…","id":"exchange-132"},{"speaker":"堺委員","kind":"質問・要望","question":"２２、２３年度の３カ年の総合実施計画が、ご説明いただきたいと思うんです。その辺も含めまして、ちょっとお考えを教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"先ほど来のご質問の中にもありましたが、一般財源が財調と区民税でマイナス３０億円、それに対しまして、基金の繰入が３７億円ほど増えております。実施計画につきましても、今、最終的な詰めをしているという状況です。","id":"exchange-133"},{"speaker":"堺委員","kind":"質問・要望","question":"総合実施計画について、今、詰めをしているですので、ぜひ、そういう中で、基金の効果的な運用といったものを通しまして、区民サービスが低下しないように、ひとつ充実した計画が練られるように期待したいと思います、要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"活用事業で５３６万５,０００円かけますよということになっているんですけれども、ここら辺のものごとの考え方を教えていただきたい。どこに住みたいですかと言えば、品川区に行ったらどうですかってお勧めがあった人が、お一人あった。","respondent":"小野区民課長、工藤環境課長、志村生活福祉課長","answer":"品川荘につきましては１億１,０００万円等の財政投入がありますし、６,０００万円余、私どもも認識をしております。… 市町村交流を実施している早川町の里山を活用しまして、環境保全に一歩踏み出す契機となる事業を実施するものです。… 今回、環境の視点から事業に取り組むという部分で、今まで６回行っているうちの１回をそういう特徴を持たせたものにする。の５回につきましては… 港区に住民登録がある方でも、大井町の駅で倒れて窮迫した状態になりますと…","id":"exchange-135"},{"speaker":"石田（秀）委員","kind":"提案","question":"３年前は、箱根荘も含めて、それはもう１回提案をしてもらうべきだと思うんですよ。それで、今後、どういうふうに動いていくんだということは、やっぱり実施をするべきだろうと思うので、そこら辺の見解をお聞きしたいとの意見を述べました。","respondent":"小野区民課長","answer":"民間の提案も含めまして、受けて、我々のほうで十分に研究をしてまいりたいと考えております。この１年間でかなりの部分ができてまいりましたので、その成果をごらんいただいて、またいろいろとご意見を伺えたらと思います。","id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"意見","question":"ほんとうに、保養所はぜひ、そういう行動をしてもらいたいと思います。ぜひ皆で１回、そればぜひ、また考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-137"},{"speaker":"土井委員","kind":"質問・要望","question":"もう一つは、１３３ページ、りんかい線のことで伺いたいと思います。そこで伺いたいんですけれども、今の事業をやるのに、特に一番最後の部分ですね、これらの考え方はどう考えたらいいんだろうか。","respondent":"日下部企画財政課長、齋藤住宅課長","answer":"補助金の見込み、でき高がどのぐらい見込めるのか、予算の要求として上がってまいります。財調の算定が特にどのぐらい見込めるのか、全体の事業の組み立て、特に歳入の構成を整理をさせていただいているというものです。 借上型区民住宅、７９ページにあります使用料の見込みですが、９６％を見込んで調定を立てております。","id":"exchange-138"},{"speaker":"土井委員","kind":"質問","question":"これからだんだん厳しくなってくると、その辺はちゃんとやっておかなきゃいけないと思うんですが、いかがでしょうか。ちょっとそこら辺の説明をお伺いいたします。","respondent":"日下部企画財政課長、齋藤住宅課長","answer":"それはまさしく、ご指摘のとおりであります。最大限当初予算の段階で見通しをしっかり立てて、できる限り精度の高い予算内容にしていきたいと、基本的にはこのように考えているところです。 うち今、転居の時期ですので、うち１０戸は埋まります。長期の空き室は２９戸ということになっております。","id":"exchange-139"},{"speaker":"土井委員","kind":"質問","question":"これについて、どういう状況になっているのか、ちょっとお伺いをしたいと思います。それから、もう一つは、東京臨海高速鉄道なんですが、今回、貸付金の返還が始まったと伺ったんです。","respondent":"島袋品川区清掃事務所長、梶都市計画課長","answer":"年末になると大体１００件近くになりまして、かなり浸透してきたなと。今、そういう状況です。 ただいまのりんかい線のお尋ねです。前年同期比で見ますと、乗車人員が１０.３％の増という形で伸びているということを聞いておりますので、順調に営業していると考えております。","id":"exchange-140"},{"speaker":"土井委員","kind":"質問・要望","question":"ぜひ、進めていただきたいという意味で、お話をいたしました。それらに期待する向きもあるんですけれども、そんな見通しは、今はまだ立ちませんか。","respondent":"梶都市計画課長","answer":"ただいまの、もっと線がというお話なんですけれども、今現在の状況は、今ある線をもちろん充実していくと同時に、あるいはＪＲとの乗り入れの本数をもう少し増やすとか、そういった形で、今、話が進んでいるということは聞いてあります。","id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"残りの２８億円余りが区の負担ということでいいのか、どうなのか確認したい。これが区の負担になるかどうかということ、まず、そこのところを確認させてほしいと求めました。","respondent":"青木都市開発課長","answer":"同じ９７ページだったかと思うんですけれども、やはり３１７ページあたりになるかと思うんですけれども、歳出が記載されてあります。１４０ページに都市基盤整備費収入というものがありますけれども、事業者負担の分として、品川区の支出軽減に使っているという内容です。","id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問","question":"財政調整交付金のほうの算定基準は、この２８億円そのまま１００％みているということになるのか、どうかということを伺いたいと思います。差があるとすると、幾らぐらいなのかということを伺いたいと思います。","respondent":"青木都市開発課長","answer":"再開発補助金に対する財政調整は全額ということでご理解いただきたいと思います。","id":"exchange-143"},{"speaker":"宮崎委員","kind":"確認","question":"２分の１とか、３分の１とかいろいろあるんですけれども、かなり区が持っていくということでいいんでしょうか。そこを確認したいと思います。","respondent":"青木都市開発課長","answer":"都市再生総合整備事業は、公共施設を整備するものですので、制度要綱に基づいて、国が区市町村に対して直接補助をするというものです。原則として補助金以外のものについては、区の一般財源からの支出ということで、ご理解いただければ間違いございません。","id":"exchange-144"},{"speaker":"宮崎委員","kind":"質問","question":"着手する北品川五丁目第１地区なんですが、本会議でもちょっと質問しましたけれども、総事業費９５０億円だったと。２倍以上の１３４億円も増えているんですけれども、そこのところはどういうふうに変わっていくのか、伺いたいと思います。","respondent":"青木都市開発課長","answer":"事業計画をまとめ上げましたのが平成２０年で、ちょうど鋼材価格等が急激に上がっている段階でしたので、当初の予定よりも高くなっております。補助金全体が上がれば、あるいは国からの補助金もその分割合に応じて増額されますので…","id":"exchange-145"},{"speaker":"宮崎委員","kind":"質問・要望","question":"あるいは、区のほうとしては、どういうふうに考えているのか、そこのところをお聞かせいただきたい。そこのところは、例えば時期がずれれば、全然変わってくると思うんですけれども、どうなんか尋ねました。","respondent":"青木都市開発課長","answer":"保留床の処分が見込めないであるとか、参加組合員に不適格なものがいるといったような判断がなされれば、認可がされないということになります。おそらく認可はされるであろうという見込みで事業を進めているところでございまして、個人も含めて、品川区および東京都の判断です。","id":"exchange-146"},{"speaker":"宮崎委員","kind":"質問・要望","question":"住民感情から見たら、そういうところはほんとうにおかしいことだと思うんですけれども、そういう角度からの点検というのはないのか、どうなのか。あるいは、区としては、そういうことがあっても進めるということなのか、どうなのか、お聞かせほしいと求めました。","respondent":"青木都市開発課長","answer":"再開発をやろうということで検討してきたのが組合施工の再開発ですから、事業計画、資金計画がかなり高いものになっている。もし認可されるとすれば、着々と進めていくべきであるということで、ご理解いただきたいと考えています。","id":"exchange-147"},{"speaker":"宮崎委員","kind":"確認","question":"２を超えるところもあると言っていましたけれども、教えてほしいんですけれども、具体的にどういうものか。何をどういうふうに計算しているのか、ここのところをちょっと伺いたいと思います。","respondent":"青木都市開発課長","answer":"ここの大崎駅周辺の開発が進めば、１の投資に対して１.７とか、場合によっては２を超えるような経済波及効果があると算定するものです。ちょっと複雑になり過ぎますので、これ以上の答弁は控えたいと思います。","id":"exchange-148"},{"speaker":"宮崎委員","kind":"質問","question":"最初の方の質問にありましたけれども、ほんとうに返ってくるのは少ないということを、改めて感じました。見直しをお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-149"},{"speaker":"三上委員","kind":"質問","question":"この件と、それから、１３１ページの歩行喫煙防止過料について、ちょっとお伺いしたいと思います。平成２０年度は途中ですけれども、過料をお払いいただいた方の実績はどういうふうになっていますか、ちょっとお教えいただけますか。","respondent":"堀越生涯学習課長、高濱生活安全担当課長","answer":"そのほか、一般の利用の方が倍の１,６００円の金額。これは、例年の実績に基づきまして、実績見合いで歳入として算出をしたものです。 過料の実績についてですが、本年度は、これまでに１６件の取り締まりをしております。これまで、平成１５年の制定当時から１４７件の取り締まりを行っております。","id":"exchange-150"},{"speaker":"三上委員","kind":"質問","question":"それから、歩行喫煙防止で１４７件指導したということで、少し悪質だというので過料を科したということで１６件ということなんでしょうか。それとも、まだまだ中途半端なところもあるんだというような考え方でいるのか、そこらあたり、現状をどうお考えになっているのか、お伺いします。","respondent":"堀越生涯学習課長、高濱生活安全担当課長","answer":"夜間照明の設備が設置してある校庭ですが、１７地区のスポレクのエリアに１カ所を基本に設置しておりまして、現在、１８校に設置をしています。 ご説明が足りない点がありましたので、再度、説明いたします。１４７件と申しますのは、平成１５年から取り締まりを開始しまして、これまで過料を徴収した累計です。","id":"exchange-151"},{"speaker":"三上委員","kind":"質問","question":"夜間の照明をつくってはどうでしょうかと、皆さんに対する取り組み方をしているのか、どうか。そこらあたりの考え方というのは、これはまたちょっと取り組み方として問題があるんじゃないかなと思うんですけれども、いかがか尋ねました。","respondent":"堀越生涯学習課長、高濱生活安全担当課長","answer":"校庭の夜間照明の件ですが、昼間なかなかスポーツができない方のために、設備を備えるように設置をしてきたものです。子どもたちのサッカーですとか、比較的照度が低くても対応できるようなスポーツについて… 両者の併存を目指しながら進めております。指導を担当しております者について、オレンジ色の目立つ服にかえまして、指導についてはよくわかるようにいたしています。","id":"exchange-152"},{"speaker":"三上委員","kind":"質問・要望","question":"だけれども、商店街を外れた２６号線とか、そのほかのところで、そういう人たちに会うということはなかなかない。どこまでそれを実現していこうかということについて、もう少し真剣に取り組んでいっていただきたいと、課題として申し上げておきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-153"},{"speaker":"鈴木（真）委員","kind":"確認","question":"最初に、６,５００万円ぐらい歳入が入っているんですけれども、開発か何かやっているときに使っている土地ということでよろしいんでしょうか。予算書をどういうふうに変えたのか、１,０００万円という基準がどういう基準なのか、説明を求めました。","respondent":"青木都市開発課長、片田建築課長","answer":"私からは、７９ページ、土地建物使用料のまちづくり事業用地等について、お答え申し上げます。それの貸付料金、厳密に言いますと、行政財産の使用料の料金がここに計上されているものです。 工事費前年度は１,２００万円ほど予定しておりましたので、当初１億２,０００万円ほど予定してございましたので、４,０００万円。実情に合わせたものです。","id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１億６,５００万円という細街路拡幅、かなり大きな金額なんで、もっとこれからも出てくるのかどうか。大体どのぐらい、これからの見通しだけちょっと説明を求めました。","respondent":"青木都市開発課長、片田建築課長","answer":"たしか５０％減額だったと思うんですが、通常の算定価格よりも安く算定して貸し付けてあります。その結果として、駐車場などでは、幅広く利用いただけるように、安く料金設定をするように、そういったこともあわせて指導しています。 例年、整備件数につきましては、２００件強を行ってきております。今後、増えてくる可能性が十分にあると思いますので、実態を踏まえて調整していきたいと考えております。","id":"exchange-155"},{"speaker":"鈴木（真）委員","kind":"提案","question":"これが１年とか２年の範囲ですから、そのバランス的なものを、現状でどうとったらいいのか。本来、各事業部からこれだけのことをやりたいという提案が出てきたところを、あまり考えないということでよろしいか尋ねました。","respondent":"日下部企画財政課長","answer":"事業部からの提案、これは最大限尊重すべきだと思います。財政上の内容を抜きにはできませんので、また先ほど出てまいりましたが、こういう判断も出てまいります。","id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それは区民サービスに向かう話でしょうから、ただ、そこら辺もうまく運用しなきゃいけないと思うんです。全体として、これからも健全経営をしながら、行政サービスを果たしてもらうように、ぜひ、お願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-157"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":124110,"voices":390}},{"id":"h21-20090310-3","meetingId":"h21-c-budget","date":"2009年3月10日","dateIso":"2009-03-10","committee":"予算特別委員会","time":"午前１０時０２分～午後６時１９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件整理しています。","topics":[{"id":"topic-01","title":"平成２１年度品川区一般会計予算","agenda":"平成２１年度品川区一般会計予算","exchanges":[{"speaker":"井桁委員","kind":"質問","question":"は１７１ページの文化芸術・スポーツ振興ビジョン等策定経費についてお伺いをいたします。今後具体的にどういった計画になるのかということと、あと今後について簡単にお伺いできればと考えています。","respondent":"小野区民課長","answer":"そして、品川区の基本計画等の中で立てられております文化・スポーツに関する施策を具体的にするために作成をするものです。９月ごろに中間のまとめを行いまして、そしてパブリックコメントを行いまして、年度内に策定というふうなことを考えております。","id":"exchange-001"},{"speaker":"井桁委員","kind":"質問・要望","question":"この文化芸術・スポーツのまちづくり条例というのは、議会からつくられた条例ですので、ぜひ上手に進むようにしていただきたいと考えています。１５５ページの庁舎整備等に関連して、来庁した方がスムーズに運ぶようにしていただきたいと思っておるんですが、お伺いをしたいと考えています。","respondent":"阿部経理課長","answer":"４月１日の組織改正に向けまして、今レイアウト変更していますけれども、従来から３階あるいは２階のエレベーター前で案内を差し上げております。もう既にどういうレイアウトになるのかは配っておりまして…","id":"exchange-002"},{"speaker":"井桁委員","kind":"質問・要望","question":"かなり元気なもので、ぜひともその点は今後とも皆さんがより使いやすい、そういった庁舎を目指していただきたいなと考えています。次の質問なんですけれども、１５９ページの広報経費の全般についてなんですが、その辺はいかがか尋ねました。","respondent":"中川原広報広聴課長","answer":"この間、平成１９年度までにホームページのリニューアルをしてまいりました。時代に合った、費用対効果も含めて、皆さんに頼りがいのある広報ツールとして活用していただけるホームページにしていきたいと思っているところです。","id":"exchange-003"},{"speaker":"井桁委員","kind":"意見","question":"どなたにでもというのは、やはり行政にとっては非常に大切なことだと思うんですけれども、やはり検索のことであったりとか、あとはいろんなところに飛んでしまうのもまだまだ見受けられるかなと考えていますので、その点ぜひ改善をお願いしたいと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"携帯電話、一斉同報システム等につきまして、一般質問での積み残しも含めまして質問させてほしいと求めました。こちらの事業内容についてお伺いしたいんですが、こちらのほう、こちらのほうは参考にされたのかどうかということについてお伺いします。","respondent":"原情報システム課長","answer":"そういったときにトラブルがありますと大変なことになりますので、その辺については臨機応変に対応していきたいということで考えているところです。当然のことながら…","id":"exchange-005"},{"speaker":"浅野委員","kind":"提案","question":"例えば、一般質問でも地域ＳＮＳの提案もさせていただきました。いよいよ２月２６日から、こちらのほうを一部一般質問でもご回答いただいておりますけれども、わかっている限り教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"ケーブルテレビのほうに確認しましたところ、２月の末に基地局１台目を自社ビルの戸越台ビルの屋上に設置したというふうに聞いております。基地局を設置したことによりまして…","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問・要望","question":"平成１７年の第１回定例会で、犯罪者情報などを協力員に配信をするという質問をしましたところ、検討するという回答をいただいております。ハード的に耐え得るものなのか、それとも改編とかそういうものができないものなのか、そこら辺について考えを説明を求めました。","respondent":"高濱生活安全担当課長","answer":"今行っています協力員への協力者情報などの配信についても、そういうふうなものができればすばらしいと思い検討しておりました。これを改修いたしますと、他の部分に思わぬ影響が出る可能性もありますので、現状では一斉配信はできないというご回答になります。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問・要望","question":"この４月の時期とかそういうときに、教育も含めてぜひともそういう機会を定期的に求めていっていただきたいと、そのように思います。それとも徐々に減っていって平均で７０人にするのか、この１年間、この二つについて計画を含めてご回答をお願いします。","respondent":"中山防災課長","answer":"町会長、あくまでもこれは私どもの見込みでございまして、７割程度の方が多分お返しになるんじゃないかという見込みです。ですから、実態とそぐわない点が出てこようかと思いますけれども、その辺につきましては、また臨機応変に対応してまいりたいと思ってあります。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"今年度中ぐらいに実施をされるというふうに伺っておりますけれども、具体的な策というものがあれば、この点をお伺いします。これは実際に２３０台、どのぐらいの時間がどのぐらいに短縮されるのかということを、目安で結構ですのでお願いします。","respondent":"中山防災課長","answer":"防災テルてるの関係ですけれども、今般機器を変更する場合は、そして簡単に取り扱いできるようなものということで機種を選定してまいる予定です。８分程度です。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"時間がなくなりましたけれども、１点だけ、こちらのほうは要望で終わりにします。区長からも直接区民の方にお知らせができるようなシステムというんでしょうか、今年度どういう計画なのかということと、簡単にお願いします。","respondent":"中川原広報広聴課長","answer":"仮設スタジオについては、既にいざというときのためにセットは置いておりますので、ご要望のとおり頼りがいのある災害時の発信に努めていきたいと考えています。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは、１４８ページからの総務費に関連しまして、品川区の職員給与費の考え方と行革との関係について幾つか質問したいと思います。もう一つ、この１０年間で８６９人との説明がありましたけども、一体これで給与費だとお幾らのコストダウンという考えなのか教えていただきたい。","respondent":"榎本人事課長","answer":"２８人の減というか、平成２０年度予算と平成２１年度当初予算で比べますと、全体で５億５,０００万円の職員給与費の減という形になっております。最近ですと生活福祉関係の就労支援相談員とか、そういう形でのもの、そういう非常勤が増えているというふうに思っております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"品川区はみずからワーキングプアをつくっていることをどう考えているのか、その認識と反省があるのか伺いたい。伺いたいのは、品川区は区内の雇用悪化と区民生活の深刻な影響との関係、ここをどう考えているのか、ご説明ください。","respondent":"福田企画部長","answer":"本会議でも申し上げましたけれども、品川区は過日ご議決いただきまして、総合的な緊急対策を展開しています。この認識は現在の経済情勢が区民の生活それから営業活動、こういう認識に基づくものですが、これは国が対応するべきことでございまして。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"少し具体的に伺いますけれども、そこをしっかり貫くべきだと思うんですけど、この点はどう考えているのかということ。こういった話を伺うんですけれども、ご存じなのか、ちょっと現状を教えていただけますか。","respondent":"榎本人事課長","answer":"時給換算でそれほど低いという形、全部１,０００円を上回っている非常勤の賃金単価ですので、それほど低いという形という認識はございません。委託の関係の賃金というのは、その場合の賃金関係については…","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"調べてびっくりしたのは、１日３時間の非常勤は、交通費すら出さない。同じように職場に向かっているのに出さないとはけしからんと思うんですけれども、交通費についてはいかがか尋ねました。","respondent":"榎本人事課長","answer":"必ず上限額があります。それからあとは、勤務時間が短い場合についてはその部分は報酬単価のほうに含めてという考え方で、一律の部分で思っているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"行革の名でコスト削減の名目で地方自治体がワーキングプアをつくることが正しいのかと伺いたい。それで、地方公共団体が雇用に対する責任をどのように考えているのか、果たすべきだと思うんですけれども、いかがか尋ねました。","respondent":"榎本人事課長","answer":"ガバナンスの部分は私も記事を読みましたけれども、地方自治体が生み出しているとか、そういうものではないというふうに認識をしております。なるべくコストを押さえていくという形は課せられた使命であると思っていますし…","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"例えば児童センター、中小企業センター窓口などの窓口業務の委託、この庁舎の清掃などでも業者が変わって時給が下がったという話を伺いました。こういうことが委託先で起きていることが許されるのか、正しいと思うのか、ぜひ区の見解を説明を求めました。","respondent":"榎本人事課長","answer":"その仕事の選択というのは、各個人がどういう仕事をするかという選択の問題だと思います。逆にいけば、区の立場からいけば、要は貴重な税金をより効率的に使うためにはそういう形での入札という形での仕事を委託しているというものです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"改めて私は税金でワーキングプアをつくるのは間違っている、品川区は雇用責任を果たすべきだと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"稲川委員","kind":"質問","question":"私は地域の活動拠点というのは、現在２０３町会ですか、この中でまず町会会館を持っていない町会が何町会あるかというのがまず１点。今度建て替えについて今どんどん老朽化、耐震とかも含めて建て替えなければいけない町会というのは実際あるのかどうか、その辺をお伺いします。","respondent":"中山地域活動課長","answer":"支援ですけれども、建て替えあるいは新築の経費の２分の１助成ということで、最大１,８００万円までの助成を行う補助を行っているです。年間大体七、八件前後のご相談がありますから、現在このような要望が大体年平均で出てきているというような状況です。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"例えば、町会があって、その町会がどうしても町会会館が欲しいと。例えば区のあいている土地があれば、そこを有償で貸すとか、そういうお考えはありますか尋ねました。","respondent":"中山地域活動課長","answer":"先ほどご説明した助成金というのは、ご質問のいわゆる土地部分に関しての助成という考え方は従来から持っておりません。最近では、地域コミュニティの活性化の核である町会という観点での支援のあり方は、さまざま検討の可能性はあろうかというふうに考えております。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問","question":"地域のコミュニティと非常によく私も言うんですけど、幅が広くて、何のコミュニティなのかなと。例えば、さまざまあると思うんですが、このコミュニティの助成というのはどういった部分に助成されるのか説明を求めました。","respondent":"中山地域活動課長","answer":"その基本認識は、主体等は考えられるわけですけれども、基本となるのは町会・自治会であると。その町会・自治会の抱える課題を支援する観点から、新たに支援の底上げをしていくという観点から今回の予算を計上させていただいたというものです。","id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"例えはバス旅行もあれば、地域親睦を含めた野外でやるお祭りみたいなものもあると思うんですが、そういうのに対して助成をしていただける制度ということでよろしいか尋ねました。","respondent":"中山地域活動課長","answer":"現在実際の給付について鋭意検討していますが、基本的には全町会・自治会に幅広く支援ができるような形で考えているところです。ですから、これを基本に考えております。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"多分審査があると思うんですが、審査をスピーディーにしていただいて、この制度を利用しやすい基盤をつくってほしいと求めました。１８７ページの区民消火隊に関してなんですが、町会以外にもあるのかどうか、まずそれを１点お伺いします。","respondent":"中山防災課長","answer":"防災区民組織ですけれども、これは地元の地域の町会・自治会等で編成されてあります。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"ここにある６８隊というのは、６８町会の部分で組織しているのかという受け取り方でいいのか。３消防署があるんですが、荏原消防署の属する町会では何隊あるのか、個々教えてほしいと求めました。","respondent":"中山防災課長","answer":"それから区民消火隊が２０隊、荏原消防署管内がミニポンプ隊が７３隊、いわゆる区民消火隊が２４隊となっています。したがいまして、１８２隊あるです。","id":"exchange-023"},{"speaker":"山内委員","kind":"質問・要望","question":"総務省のこの前の１月の発表ですか、１月時点で地デジの普及率が４９.１％、半分にも届いていない。２０１１年の７月からですか、２年後でそのような方が出られても、まずその辺の見解を伺いたいなと思います。","respondent":"久保田行財政改革担当課長","answer":"経済的に難しい方への対応ということですけれども、そちらのほうの動向等を見ていきたいというふうに思っております。基本的に地上デジタル放送につきましては、そういった動向も踏まえながら、対応のほうも推移を見守っていきたいというふうに思っております。","id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"今課長のほうから品川区の環境が整っている世帯が８割ですか、１５％以外の人というのは、調査はしていないということでよろしいんですかね。「何ですか、それ」と言われる人がいまだにいます。","respondent":"久保田行財政改革担当課長","answer":"テレビ受信者支援センターというところと私ども、また個別の町会からケーブルテレビ品川のほうに説明をしてもらいたいといったような要望もあると。それに対応しているということも聞いておりますので、細かく対応はしていきたいというふうに思っております。","id":"exchange-025"},{"speaker":"山内委員","kind":"意見","question":"とにかくこれは何とか普及させていかなくてはならない事業なので、ぜひとも努力のほうをよろしくお願い申し上げます。このパンフレット、これを作成して、どのような形で普及をさせていくのかということをまずお尋ねをさせてくださいとの意見を述べました。","respondent":"中山地域活動課長","answer":"残りの８地区分を来年度作成し、来年度でもって１３地区すべてのパンフレットができてくるです。ただし、例えば地区によっては、そういうところに重点的に配布する等のアレンジは各地区の中でされているです。","id":"exchange-026"},{"speaker":"山内委員","kind":"質問","question":"競馬場から出ているんですか、それは何でなんですかね。","respondent":"中山地域活動課長","answer":"端的に言うと、競馬場の来客者等の影響、地元に迷惑・負担があるということから、設置以降、地元の町会に助成がされている、こういうことです。","id":"exchange-027"},{"speaker":"山内委員","kind":"質問","question":"各町会だと思うんですけれども、この２,０００万円というこれ、どういう配り方をするんですかね。それによって後から報告、こういうことをしましたよという報告書を上げてもらうのか、その辺をちょっと。","respondent":"中山地域活動課長","answer":"端的に言いますと二百何町会ですから、それを２,０００万円ということですから、平均すると１０万円近くが幅広くわたるようなことを考えております。こういうものを支援対象にしながら、できる限り幅広く行き渡るように考えていきたい、このように考えております。","id":"exchange-028"},{"speaker":"山内委員","kind":"質問","question":"わかりました。その後、もっとやりたいんだけどどうなんですかといったときに、それはやっぱりなかなか難しい助成なんですかね。","respondent":"中山地域活動課長","answer":"今回の考え方としては、やはり現下の中で抱えている課題を共通する部分を底上げしていくというのを基本に考えております。これは例えば協働の提案制度なども含めて町会の独自の活動の支援というのは別途考えていくもので。","id":"exchange-029"},{"speaker":"山内委員","kind":"質問","question":"すみません、２００ページの指定統計費の全般についてお尋ねさせてください。何か名称が変わってこれはどう今後変わっていくのかということと、農林業センサスの中身を説明を求めました。","respondent":"小野区民課長","answer":"センサスというのは、経済センサスについては、経済活動の幅広い分野の部分を一定の期間にやるというもの。農林業も同じように、３ha以上の年間１５万円以上の営農をしている方、あるいは林業としては３ha以上の林業ということが対象となっております。","id":"exchange-030"},{"speaker":"山元委員","kind":"質問・要望","question":"１５３ページの人権啓発費の中から、また１５７ページの結婚サポート事業経費、そして１８１ページの区民斎場運営費についてお伺いいたします。最初に、１５３ページの人権啓発費の、この男女共同参画センター運営費についてちょっとお伺いいたします。","respondent":"吉岡人権啓発課長","answer":"あるいは相続の問題もありますし、あるいは離婚の問題、それから中にはＤＶの問題もあるというふうな幅広いものです。","id":"exchange-031"},{"speaker":"山元委員","kind":"質問","question":"特にいろいろ取りざたされているドメスチック・バイオレンスですか、ＤＶはそういうご相談というのは、ここ近年いかがなんでしょう、多いんですか、少ないんか尋ねました。","respondent":"吉岡人権啓発課長","answer":"人権啓発課、若干年度によってばらつきはあるんですが、ここ数年特に増えているという形でもございません。男女共同参画センターだけではなくて、いろいろなところで受けておりますので、区全体としては若干増加傾向かなというふうにとらえております。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"たしか第３次計画は、平成２２年までかなと思います。ここに計上されているということはどういうことなのかなという素朴な質問というか、教えてほしいと求めました。","respondent":"吉岡人権啓発課長","answer":"現在第３次の行動計画品川プランということで、平成１３年度から平成２２年度までの１０年間の計画で実施をしています。その上位の計画を受けまして若干一、二年ですけれども、繰り上げをして改定をしていきたいというふうに現在検討しています。","id":"exchange-033"},{"speaker":"山元委員","kind":"質問","question":"具体的にまだ内容はこれから詰めるということになりますか尋ねました。","respondent":"吉岡人権啓発課長","answer":"それから学識経験の委員をお願いして推進会議体を設置してございまして、そのご報告がこの３月にいただけるような予定になっております。パブリックコメントを経て、平成２１年、今年の９月には新しい計画としてスタートしたいなというふうに考えているところです。","id":"exchange-034"},{"speaker":"山元委員","kind":"質問・要望","question":"１５７ページの結婚サポート事業についてお伺いさせてほしいと求めました。年齢の幅、一番お若い方から、また最高年齢と言っていいかどうかわかりませんが、その年齢を教えてほしいと求めました。","respondent":"小野区民課長","answer":"こちらは９月と２月に２回ほど実施をしておりまして、男女２０名ずつの４０名を対象として実施をしております。男性の一番年上の方は４０歳から４４歳の間の方が５名、こういう状況になっております。","id":"exchange-035"},{"speaker":"山元委員","kind":"質問","question":"このセミナーの会費というんでしょうか、１人当たりの負担額というんですかね、それはどのぐらいの金額になりますか。","respondent":"小野区民課長","answer":"セミナーの参加費は、セミナーの後に続きます飲食を伴いますパーティーの経費ということで、５,０００円をいただいております。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問","question":"１年たって、まだカップルとかというのはできているかどうかわからないんですが、できているかどうか、ちょっと教えていただけますか。","respondent":"小野区民課長","answer":"９月に実施をいたしました第１回目のセミナー、交際申し込みを受けて、その後のフォローアップのアンケートを２月に実施いたしました。これは４０名の方にアンケートを出しまして、１６名の方から回答をいただいております。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"ぜひカップルができたけれども、他区に行くようなことのないように努力をしていただきたいし、また現実に、今年はぜひカップルになるようにお願いをしたいと思いますが、いかがか尋ねました。","respondent":"小野区民課長","answer":"こういう紹介の中で将来を一緒にできるような恋人ができて大変喜んでいるというふうなお答えもいただいておりますので、何らかの、これがうまく進んでカップルが誕生ということを期待しているものです。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"１７３ページ、地域スポーツ推進経費からその下にかけての中で幾つか質問をしていきます。この地域スポーツとはどういった意味で地域スポーツという言葉を使われているのかというようなところをまず初めに説明を求めました。","respondent":"堀越生涯学習課長","answer":"私どもの考え方といたしましては、地域で、身近なところでスポーツを楽しむと。そのような中で、それぞれの目的に従った形で地域の中でスポーツを振興していく、これが地域スポーツというように受けとめているところです。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"わかれば登録数と、逆に登録数プラス人数ですね、区民の方がどれぐらい登録されているのか教えてください。これのいわゆる違いの考え方、民間事業所とあるこの民間事業所というのは何なのかというのを説明を求めました。","respondent":"堀越生涯学習課長","answer":"団体の支援ですが、これはこれまで社会教育法の考え方に基づきまして団体の育成を図るということで進めてまいりました。名称につきましては、そのようないろいろな新しい取り組みもありますので、またそれも検討の要素として加えていきたいというふうに考えております。","id":"exchange-040"},{"speaker":"渡部委員","kind":"質問・要望","question":"１,０００もの団体が１７のスポレクに分かれて活動されているというのは、この中で今学校施設という考え方を伺いました。いわゆる何か案分方法というんでしょうか、教育費の部分と何か案分とかというのが金銭的にはあるのでしょうか、お願いいたします。","respondent":"堀越生涯学習課長","answer":"そのような形で周知に努めているところです。それから、ランニングの経費につきましては教育委員会のほうで行いますが、こちらのほうの学校施設のほうの費用の中に含まれているものです。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"最後に一つだけ教えてください。どのような形で、どのような普及をされていくのか尋ねました。","respondent":"堀越生涯学習課長","answer":"使えなくなった場合、スポレクの中、地域の中で調整をしていただきながら使っていただくという形で今調整を進めていただいているところです。ウォーキングの事業でございまして、年４回ウォーキングの事業を行っておりまして、大変ご好評をいただいているところです。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"４０人分の在学資金と入学準備金ということで、そしてまた事務費として計上されていますけれども、貸し付けの状況をまず伺いたいと思います。今後の平成２２年度竣工ということなんですけれども、どういうスケジュールで懇談調整をしていこうとされているのか、その辺を聞きたいと思います。","respondent":"小野区民課長、日下部企画財政課長","answer":"奨学金に関するお尋ねです。現在４８人と２４人の７２名ということで、一応８０名以内という形になっておりまして、来年度については８０名を見込んでいるところです。 今の検討状況をご報告して、一定の今の検討している中身につきまして、このように考えております。ただ、平成２２年度中できるだけ早い時期に開設をできるように私どもとしても努力をしてまいりたい、このように考えております。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"おそらく全国調査ですから、区がきちんと支える、そういうことを施策として持つべきだというふうに思うんですね。先ほど申し上げたような授業料滞納者が２.７％になっているという状況についてのまず認識を伺いたいのと、そういう方がいらっしゃるかどうかという。","respondent":"小野区民課長、日下部企画財政課長","answer":"７２名のうちの２０名はこういうご家庭の方だということで、そういう部分について、大変力になっているのではないかなというふうに考えております。今、そういうところを相談していただいて… 触れ合い、学んでいただくことができるようなさまざまな機能を持った、そういう施設として整備をしていく。ですから、子どもさんからお年寄りまで…","id":"exchange-044"},{"speaker":"南委員","kind":"質問","question":"そういう状況で、１年後から返済が開始されるわけですから、そういう点で分納だけで果たしていいのかどうかということだと思うんですね。したがって、やっぱりきちんとした調査をして、実態に則した対策を持つべきだというふうに思うんですけども、その辺の見解を伺います。","respondent":"小野区民課長","answer":"滞納している方に直接ご連絡をとりながら収納しておりますけれども、この間、ずっとその辺のところの収納の額が上がってきております。そういうところも含めて返還についてはきちんと相談に乗ってきめ細かく対応してまいりたいというふうに考えております。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱりもう少し配慮、考慮があっていいんじゃないかというふうに思いますので、もっともっとちゃんと実態を調査するべきだというふうに思うんです。そして、十分な対策をとるべきだということを強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"渡辺委員","kind":"提案","question":"当然背景には議会提案でありました条例の制定、区民要望など、大きな流れがあった中での品川区の意欲のあらわれであると解釈しています。予算への反映の仕方、平成２１年度だけを見ると、ちょっと希望もある中で心配になった部分もあったので確認したいと思いますとの意見を述べました。","respondent":"堀越生涯学習課長","answer":"平成２１年度の主な特徴といたしましては、五反田文化センターのリニューアルオープン、平成２２年度に予定しております。これらを予定しておりまして、これらのいろいろな施策を取り混ぜながら総合的に進めていくという、そういうような考え方です。","id":"exchange-047"},{"speaker":"渡辺委員","kind":"提案","question":"これは本当に今すぐというわけではないんですが、絶えず意識をしていただきたいなという要望も踏まえた形で決意を伺えればと思います。見ること、そして支えるという点で、支えるに該当するのかなという点で伺えればと思いますとの意見を述べました。","respondent":"小野区民課長","answer":"こういうことが今後の文化・スポーツの振興ビジョンの中では、一つの検討の課題になっていくだろうというふうに考えているところです。教育委員会とも連携をとりながら、そういうふうな機会、こういうものも考えていきたいというふうに考えているところです。","id":"exchange-048"},{"speaker":"渡辺委員","kind":"提案","question":"でも、スポーツドクターやトレーナーの知識・見解からすると、あるいはこれから部分的にも導入できたらという提案も含めて見解を伺いたいと思います。靴ひもをしっかり結んだり、そういったことも知識として学べればと思いますので、その辺のご見解を伺いたいと思いますとの意見を述べました。","respondent":"堀越生涯学習課長","answer":"そういった支えてくださる方々に対してどのような形で支援ができるかというのもあわせて考えていきたいなというふうに思っています。いろいろなバリエーションを持って、そういった支えてくださる方々に対しての支援についても…","id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問","question":"２３区をはじめ、その点をお伺いしたいのが一つと、消耗品であるという点があると思います。二件だけじゃなくて複数結構聞きますので、そういったときの件数的なものと、あと各家庭の負担がその際に生じるのかという点で伺いたいと思います。","respondent":"高濱生活安全担当課長","answer":"今年度東京都でＩＴＣを使った子どもの見守りサービスというものの調査研究を始めまして、来年度には実証研究に入る予定であるということです。修理件数なんですけれども、おおむね記憶の範囲ですけれども、大体月になくすのも含めて３０件内外だったと記憶しております。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"私は３点、１４９ページの情報システム運営費、１６１ページの品川区サイン基本計画策定、１６９ページの訪問ボランティア事業経費について伺います。大勢の方が被災すると思うんですけども、こうしたことはしっかり行っていくためのシステムの整備というのは、今されているんか尋ねました。","respondent":"原情報システム課長","answer":"それから災害の要支援者、そういった形での管理、こういったものを実施しています。そういったところを今区としても研究しながら実際に遭われたところの実態の中でつくられたシステムですので、その辺を研究しています。","id":"exchange-051"},{"speaker":"武内委員","kind":"質問","question":"鳥インフルエンザ、つくっていらっしゃるということなんで、このＢＣＰとも関連してくると思うんですね。総務省のほうから１月１７日、こういうことをお聞きしましたもので、あと区のほうでどう考えているのか説明を求めました。","respondent":"原情報システム課長、中山防災課長","answer":"文書の中で、３月３１日までというのは、サポートセンターを設けまして、そこでいろいろな質問を受けるというような状況です。私どものほうにつきましても… 「被災者支援システムVer２.００」ですか、十分情報システム課とも検討いたしまして、採用については検討してまいりたいと思ってあります。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望します。続いて、１６１ページの品川区サイン基本計画策定ですが、これについての策定に当たっての経緯と、また主な内容について説明を求めました。","respondent":"中川原広報広聴課長","answer":"品川区のサインの基本計画についてのお尋ねですが、現在品川区には昭和６２年に策定しました品川区のまちのサイン計画があります。景観、今回昭和６２年策定のまちのサイン計画をベースに、こういった時代の要請に合ったものにリニューアルしようということで考えているところで…","id":"exchange-053"},{"speaker":"武内委員","kind":"質問","question":"どういった方々でつくられるかということと、あと去年の３月にできましたこのすべての人にやさしいまちづくり推進計画と、つくるに当たっての考え方を説明を求めました。","respondent":"中川原広報広聴課長","answer":"今やさしいまちづくり計画のほかにも、観光アクションプランとか、景観の考え方とか、区内にはさまざまサインにかかわる所管があります。個々の計画が固有で引っ張っていく部分と考え分けをして、品川区としての一定の基本的な考え方をまとめようというふうな形で進めております。","id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"すみません、策定委員会の主な構成メンバーを説明を求めました。","respondent":"中川原広報広聴課長","answer":"失礼いたしました。産業振興課、それから高齢福祉課、それから戸籍住民課と広報広聴課が事務局でやっております。","id":"exchange-055"},{"speaker":"武内委員","kind":"質問・要望","question":"案がまとまった段階でしっかり見ていただいた上で、本当にだれが見てもいいなと思えるようなものをつくっていただきたいなというふうに思います。最後の質問については、ちょっと時間がなくなりましたので、またどこかでやらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"本間委員","kind":"質問・要望","question":"過日の一般質問の中でも既に区長のほうから現在の景気状況をかんがみてということで、私どもは随分この件につきましては関心を持っております。しかし、ここを取り上げて力を入れていくというようなことですので、具体的な内容があれば教えていただきたい。","respondent":"伊勢総務課長、中川原広報広聴課長、中山地域活動課長、堀越生涯学習課長","answer":"ご意見をいただいて、また地域との交流をできるかと、この辺の懇談会の話をヒントにしながら進めていきたいと思ってあります。… 法律相談に限ってお答えをいたしますと、法律相談につなぐ相談の内容は非常に紛争を前提としたような難しい相談になっております。… 地域の活性化に向けての町会・自治会支援のあり方ですけれども、６,２００万円余の町会・自治会の支援を行っているわけです。… 国道３５７号線の拡幅工事、大井ふ頭の野外活動広場、昨年の８月末で返還をしております。オープンにつきましては…","id":"exchange-057"},{"speaker":"本間委員","kind":"質問・要望","question":"区民の相談に、十分期待にこたえていただきたいという意味での質問でございましたので、よろしくお願いします。青少年対策費の中のキャンプ場整備というふうに書いてあったものですから、例えば大井ふ頭のみなとが丘ふ頭公園というふうなことでございましたね。","respondent":"堀越生涯学習課長","answer":"３分の１程度、３分の１から４分の１程度になろうかというふうな形で今準備を進めておりますので、準備を進めているところです。電気設備等を予定しておりまして、それからかまどについては１０カ所程度を今予定して準備を進めていると、そういう状況です。","id":"exchange-058"},{"speaker":"本間委員","kind":"意見","question":"それから、雨天の場合のバーベキュー広場みたいなことを考えているかどうかを最後に一言お願いしたいと思います。それからもう一つ、騒音について、城南島の部分では、大変騒音が激しくて大変なことがありますが、その辺、さらっとお願いしますとの意見を述べました。","respondent":"堀越生涯学習課長","answer":"その中で、育成者の方ですとか、そういった方々に子どもたちの見守りについてもお願いするという方向で今調整を進めております。設備についてですが、できるだけ最小限の設備でという都のご意向もありますので、そういった点を踏まえて今調整を進めているところです。","id":"exchange-059"},{"speaker":"本間委員","kind":"意見","question":"羽田空港の沖合移転の関係で、かなり内陸部での騒音が最近はあまり騒がれることがないようでございましたが、特に城南島のあの付近はかなり騒音がありますので、その辺は最近の状況は刻々と変わってきているかと思いますが、との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"藤原委員","kind":"質問","question":"１６９ページ、それと１８２ページの防災対策費についてお伺いしますが、まず結婚サポートについてお伺いします。２点お伺いしますが、多分課長も担当課長ですから読んだと思いますが、どういう形で投資対効果というのを検証していくのか説明を求めました。","respondent":"小野区民課長","answer":"以前の地域社会を考えてみますと、結婚、地域の中でこういう結婚というものを支えてきたという実態があったというふうに認識しております。３組の結婚を前提として今でもつき合っているというカップルができているということからいって明らかではないかなというふうに考えている…","id":"exchange-061"},{"speaker":"藤原委員","kind":"質問","question":"３組が結婚したなら別ですけど、結婚を前提につき合っているというだけですよね。１００年に一度の不景気、こういうときに、その辺についてはいかがか尋ねました。","respondent":"小野区民課長","answer":"そして、結婚をどうしてしないのかということについては、今回の事業の中でもそういう点で交流の機会というふうなことで実施をしているところです。やはりこれは行政がそういうものをやるということでできたことであり…","id":"exchange-062"},{"speaker":"藤原委員","kind":"質問","question":"どういう形でアンケートをとったかというと、第１番目のアンケートというか、治安なんですよ。やはりこの２年間、その辺について１分しか残っていないですが、お二人のご意見を伺いたい。","respondent":"高濱生活安全担当課長、斉藤防災安全担当課長","answer":"どこの行政もまねができないようなシステムを運営しているということ自体がすごくびっくりしました。できれば、こういうシステムがほかのところに還元できればと考えています。 今回１期目だということなんで、いろいろ遠慮する部分はあったんですけども、いろんな形でアドバイスをできたらというふうに考えております。ありがとうございました。","id":"exchange-063"},{"speaker":"大沢委員","kind":"質問","question":"順を追って質問します。外国人が住みやすい環境の整備というふうにうたわれておりますけれども、具体的にはどのようなことをイメージされているのか説明を求めました。","respondent":"伊勢総務課長","answer":"外国人にも住みやすいまちになるか、この辺を検討していきたいと、こんなふうに考えてあります。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問","question":"大使館の方たちとの会議を通じてこの青写真をつくっていくという今お話を伺いましたけれども、ただ、この話が出る上において、あらかじめ行政のスタンスというものがあるはずだと思うんですが、そこら辺はお聞かせできますか尋ねました。","respondent":"伊勢総務課長","answer":"そういうことからもうちょっと文化の交流だとか、その辺まで含めて幅広い意味で交流を広げられたらと、こういうようなスタンスを持っております。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"あらかたの流れを出すという以前にやはり区のスタンスというか、区のそれに対する基本的な考え方があると思うんですけれども、そこをお持ちでしたら教えてほしいと求めました。","respondent":"伊勢総務課長","answer":"こういうものを通じて、ほかの住民の方と同じような形で参加すると、これが基本だと考えています。","id":"exchange-066"},{"speaker":"大沢委員","kind":"質問・要望","question":"この区政への参加ということで話も表現が出ておりますけれども、区政への参加、これの意味するところはどのような意味なのか教えてほしいと求めました。","respondent":"伊勢総務課長","answer":"外国人の参政権等々の問題がありますけれども、ここで考えているのは、そういう制度的なものじゃなくて、あくまでも今お住みになっている外国人の方と地域との関係、こういうのをどうしたらいいかです。","id":"exchange-067"},{"speaker":"大沢委員","kind":"質問・要望","question":"今の区政という部分で、広い意味での地域の行事に参加をするということで、単語が意味する区にまつわる政、政治に関与をするという意味合いではないということは１回確認をさせていただきたいんですけど、いかがか尋ねました。","respondent":"伊勢総務課長","answer":"ここで述べるのがどうかわかりませんけど、基本的には外国人との交流に関しては、そういうことじゃない形で身近な地域との交流、こういうことで予算化したものです。","id":"exchange-068"},{"speaker":"大沢委員","kind":"質問・要望","question":"１６５ページ、区政アドバイザー会議に移ります。この区政アドバイザー会議、この会議体を設立した目的と意義について教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"区政アドバイザー会議についてお答えいたします。区民の期待にこたえる先駆性のある区政経営を推進するために区長の政策形成を支援するために区政アドバイザー会議を設置いたしまして。","id":"exchange-069"},{"speaker":"大沢委員","kind":"質問・要望","question":"例えば区長が例年行っていらっしゃいますタウンミーティング、また区政協力委員という制度もあります。同じような内容の会議体なのか、それとも位置づけとして違うものなのか、そこがありましたら教えてほしいと求めました。","respondent":"久保田行財政改革担当課長","answer":"具体的には、それらを先駆的な区政運営ができますように反映していきたいというふうに考えて設置しているものです。そういった意味では、タウンミーティングや区政モニターとは異なるものであるというふうにお答えいたします。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"会議の必要性でしょうか、とりとめのない質問になりますけれども、必要性というのはどの程度感じていらっしゃるのか説明を求めました。","respondent":"濱野区長","answer":"今月も予定しております。あるいは区政そのものではありませんけれども、それをストレートな形ではありませんけれども、こういうふうに思っているところです。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問・要望","question":"国勢調査の調査区の設定ということで、たしか平成１８年に国勢調査が行われたと思いますけれども、そのときに問題になったことが数点あると思います。練られて、具体的なお話がありましたら、ご披露してほしいと求めました。","respondent":"小野区民課長","answer":"三つ目がオンラインによる回答ということですけれども、調査員が調査票をもらったときに、内容点検というのをしております。ということで、プライバシーの保護という部分については前回の問題点を踏まえて、かなりの対策がとられているというふうな状況です。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問・要望","question":"郵送で提出、オンラインによる回答ということで、そこのところを調査員の方に十分な周知と指導のほうをお願いしたいと思います。要望して質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"市川委員","kind":"質問・要望","question":"１５７ページの結婚サポート事業、それから１８２ページの防災対策費から普及啓発、それから１４８ページの一般管理費より伺います。それから現状とか、達成目標というんですか、どこまでこの事業を行うのかというところの目標みたいなところを教えてほしいと求めました。","respondent":"小野区民課長","answer":"それから、目標をどこに置いているかということです。セミナーをやり、そして交流会をやったというその中から少しでもおつき合いをしていただく方が出てくるということを目標にしております。","id":"exchange-074"},{"speaker":"市川委員","kind":"質問・要望","question":"区に税金を納めていただくという、公として、そのための支援をぜひしていただきたいというふうに思っているんです。今年度の予算全体を見ても、どんなことが予算の中に盛り込まれているのか、アバウトで結構ですのでちょっと教えてほしいと求めました。","respondent":"日下部企画財政課長、小野区民課長","answer":"長期的な若者支援ですが、基本的に若者支援ということでまいりますと、どちらかというとその辺が中心になろうかというふうに思います。ちょっと今おっしゃったような若者支援という観点とは若干異なるかもしれませんが… 結婚の支援、非常に大きい数字の割合がありますので、まずはここに焦点を当てて実施をしたというものです。確かに１回ですけれども、実費の５,０００円だけで参加ができる…","id":"exchange-075"},{"speaker":"市川委員","kind":"提案","question":"やっぱり若い方をきちんと支えていくという、そういう公のやる事業というところにぜひ立っていただきたいということを要望しておきます。まず開催の現状が今どうなっているのか伺いますとの意見を述べました。","respondent":"中山防災課長","answer":"理想は今全部で５４校ですか、すべての学校で避難所連絡会議が行われればいいんですが、実態といたしましては、平成２０年度におきまして、これは３月１０日現在ですけれども、学校にいたしますと２４校で開催しているのみです。","id":"exchange-076"},{"speaker":"市川委員","kind":"質問・要望","question":"大崎地区でも、抜本的に避難所というものを変えていく必要があるんじゃないかというふうに思っているんですけれども、その辺はどうでしょうか。スケジュールのようなものがもし考えられているんだったら教えていただきたいなと思います。","respondent":"中山防災課長、宮地区民生活事業部長","answer":"当然のことながら啓発に努めまして、全校でやらなければ意味のないことですので、全校でできるように努めてまいりたいと思ってあります。今小中一貫校等々ができていますし、基本はもとの学校へ避難していただくという… 今後学校がさらに小中一貫校等で、ある学校は跡地を利用した何かまた実施していく、そういった法人等とも出てきます。今後も積極的に地域のそういった訓練の場所となるように、学校が形を変えたといたしましても…","id":"exchange-077"},{"speaker":"市川委員","kind":"質問・要望","question":"当然どうするんだろうという不安もわかりますので、スケジュールのようなものを区民の方には早くお出ししていただきたいなというふうに思います。","respondent":"中山防災課長","answer":"今ご指摘のとおり、これから建て替えだとか何だとかというときに、逐次避難所は、皆さんの地域の避難所はこちらだと、この学校だということは周知してまいりたいと思ってあります。","id":"exchange-078"},{"speaker":"市川委員","kind":"質問","question":"年間１万５,０００人ぐらいの利用者があるということですけれども、利用目標をどう設定しているのか伺います。この目標に対して、この利用というところではどんなふうに考えていらっしゃるのか伺います。","respondent":"中山防災課長","answer":"その目標の件数というのはなかなか特定できないんですが、昨年はちょっとあれなんですが、韓国の中学校からも見学に来たというような実績があります。お勤めの方がいらっしゃいますので、５月２６日に予定していますけれども…","id":"exchange-079"},{"speaker":"市川委員","kind":"質問","question":"目標のことを伺ったんですけれども、後でまた目標をどう設定しているのか教えてください。映画の変更はだれが権限を持っているのか、ちょっとその辺を伺います。","respondent":"中山防災課長","answer":"定員が４０名ですので、これが２８０日ぐらいあいているはずですから、ぜひ掛けた答えぐらいの数を目標値に置きたいと思ってあります。あくまでも目標値です。","id":"exchange-080"},{"speaker":"市川委員","kind":"質問","question":"委託料から見ると、１人１,０００円ぐらいかかっているようなシアターなのかなというふうに思いますので、よろしくお願いいたします。それから、この啓発本をその後どのように啓発に活用していかれようとされているのか伺います。","respondent":"中山防災課長","answer":"昨年２時間ばかり講演会をやったときに、聴取者が９０人ぐらいいたんですけど、お二人しか手を挙げなかったんですね。地区ごとに分けてありますし、大変読みやすいものですので、あらゆる機会をとらえて普及啓発に努めているところです。","id":"exchange-081"},{"speaker":"市川委員","kind":"質問・要望","question":"幾つか意見とか要望が出ましたので、「しながわガイド」のほうが内容が詳しくて役に立つと、そういう意見も上がりました。外国人の方たちに別紙で冊子がつくられているのかどうかわからないんですけれども、これについては、ちょっとご意見を伺いたいと思います。","respondent":"中山防災課長、中川原広報広聴課長","answer":"広報からのフォローもあるかと思いますけども、私どももぜひ最低４カ国語ぐらいのものをつくってまいりたいと思ってあります。予算がつけばの話ですけれども。 今外国人に配っております生活情報誌のほうにそういった内容を盛り込んでおります。ＣＡＴＶの２分間番組をつくりまして、随時ＣＡＴＶの番組の中に挟み込んで周知を、リアリティーを持った内容としてお届けしています。","id":"exchange-082"},{"speaker":"若林委員","kind":"質問・要望","question":"３点まとめて伺います。これは文化センターのほうで１４億８,０００万円というふうに計上されておりますが、ここら辺の金額をまず教えてほしいと求めました。","respondent":"阿部経理課長、小野区民課長、堀越生涯学習課長","answer":"１点目の庁内サインの件ですけれども、今４月１日に備えまして、あるいはエレベーター前のサインを組織改正に伴って変えていく予定です。あわせまして… 平成２１年度に検討、施策をしております文化芸術・スポーツ振興ビジョンを検討する中で、大きく今の段階で私どものほうで考えていることは。… それから、そういった部分についてもいろいろそのプラネタリウムの投影とあわせて広く進めていきたいというふうに考えています。それから…","id":"exchange-083"},{"speaker":"若林委員","kind":"質問・要望","question":"そこの芸術祭という名称のとらえ方だけ一つ確認をさせてほしいと求めました。そういうプラネタリウムをぜひつくっていただきたいというふうに考えておりますけれども、この二つの点についてお話を説明を求めました。","respondent":"小野区民課長、堀越生涯学習課長","answer":"そういうものとのつながり、この中で幅広くいろんな方々の意見を取り入れながら今後中身を考えてまいりたいというふうに考えているんです。… いろいろなイベント、講演会、それから天文に関する学習等いろいろな、まだアイデアベースですが、いろいろ考えて検討をしております。ボランティアの方々にも…","id":"exchange-084"},{"speaker":"阿部委員","kind":"質問","question":"それから１７２ページからの区民施設費全般について、そして１７７ページ、そして１８１ページの民間施設の借上経費についてお伺いしたいと思います。このまま予算を通しちゃって、あと５億円好きに使ってくださいねということなのか、その辺のお考えをお伺いしたいと思います。","respondent":"久保田行財政改革担当課長、小野区民課長、堀越生涯学習課長、日下部企画財政課長","answer":"私からオリンピックムーブメント事業についてお答えいたします。そうした中で、パラリンピックというものについての精神も含まれているというふうに… 文化という概念、芸術も含めた広い概念の使われ方もありますので、省略した形で使うこともあろうかというふうに思います。それから… その中で、文化センターといたしましては、より広く文化、生涯学習、さまざまな面から社会教育を含んだ形で広く事業を担当していくという形です。… 既存の学校の建物、しかもご案内のように八潮の南小学校…","id":"exchange-085"},{"speaker":"阿部委員","kind":"質問・要望","question":"非常に教育的といったらいいんでしょうか、人材育成といったことも含めて社会教育の中でとらえている、そういったところもあると聞いております。そういった人材育成の場にもきちんと使っていただきたいと考えていますが、その辺のお考えを教えてほしいと求めました。","respondent":"久保田行財政改革担当課長、小野区民課長、堀越生涯学習課長、日下部企画財政課長","answer":"スペシャルオリンピックスについてお答えいたします。さらには文化、国籍などさまざまな差異を超えまして… 今後文化芸術・スポーツ振興ビジョンを検討する中も含めて、こういう部分についても力を入れてまいりたいというふうに考えているところです。… 文化センターですが、文化センターの施設の目的はいろいろな文化、スポーツ、レクリエーション活動の促進、これが目的です。… 今使えるものは使う、できるだけ生かしていく、そういうことで進めております。それから中身…","id":"exchange-086"},{"speaker":"本多委員","kind":"質問","question":"１５９ページのＣＡＴＶ事業、１７５ページの大崎第二地域センター移転経費について質問します。品川区がつくるものとさまざまあると思いますけれども、平成２１年度の取り組みについて、基本的なところを説明を求めました。","respondent":"中川原広報広聴課長","answer":"品川区は区広報番組としまして、毎週、１週間に起こった出来事とお知らせを中心としまして、あと特別番組というのをつくっております。そういうことで、品川区は区政の情報を中心としながら、まちの皆さんの元気をお伝えする番組をつくっているところです。","id":"exchange-087"},{"speaker":"本多委員","kind":"質問","question":"いろいろ今までも見させていただきましたけれども、そのつくり方なんですけれども、今後どのように考えているのか。買う方が全額負担でいいと思うんですけれども、そういうＤＶＤを保存して残す定着についてどうなのか、その辺を説明を求めました。","respondent":"中川原広報広聴課長","answer":"お尋ねのＤＶＤとか残す場合ですけれども、町場の方が自分たちが出た記念にとっておきたいという２種類があります。南東京ケーブルテレビのほうでご相談に乗りまして、ダビングサービスとかをする場合と、民間の事業者をご紹介する場合があるかと聞いております。","id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"従来どおりこれからも強化してやっていただきたいと思うんですけれども、今度こういうのがあるんだなとか、ＰＲの強化についてお聞きします。区外の取材とか、そういった放映、区外で何か催しをやっている区政にかかわるものという部分がどのくらいあるのか教えてほしいと求めました。","respondent":"中川原広報広聴課長","answer":"先ほどの美智子皇后の５０周年等々、番組の盛り上げ方も違ってきますので、なるだけいろんなお話を事前に早いうちにいただければと考えています。区外の取材ですが、区外の活動についてもビデオにおさめられるものについては、番組として紹介していくような形でやっております。","id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。ちょっと次の１７５ページの大崎第二地域センターのほうを聞いていきますが、移転ということについて教えてほしいと求めました。","respondent":"中山地域活動課長","answer":"大崎第二地域センターの移転ですけれども、冒頭に説明があったように。本年１０月中の移転を予定しているおるところです。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"それで、地域センターの跡利用は行財政改革特別委員会でやっていることですので聞きませんが、跡利用が決まるまでの暫定期間があるわけですよね。地域センターが移転後、１０月に移転をして、跡利用が何になるかまでは暫定期間は管理はどこでされるのか、そこだけ説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"移転後につきましては、普通財産というところで切り替えますので、経理課のほうで管理をしていくものだというふうに考えております。跡利用につきましても、今後引き続き有効な活用を考えていきたいというふうに考えているところです。","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"まず１６１ページの品川区サイン基本計画策定で、これは質問を多くの方がされたんですが、一つだけ確認させていただきたい。それが６階どこどこみたいな、そういう掲示が加わると余計区民の方がわかりやすいのではないかと思うんですが、いかがか尋ねました。","respondent":"中川原広報広聴課長","answer":"庁舎に着きましたら、総合案内から目的のところまでということを想定しまして、ご案内の仕組みということで考えていく予定です。ただし、関連課がたくさんありますので、その中で随時できるところからできるところまで調整してやっていきたいというふうに考えております。","id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"１７１ページの歩行喫煙防止推進経費ということで、特に青物横丁駅では歩行喫煙が目立つということで、以前から区民の方の声をいただきます。エリアが決まっているんですが、それ以外のところ、あるいは境目のような私道は今後どのような形で進めていっていただけるのか尋ねました。","respondent":"高濱生活安全担当課長","answer":"エリア内については、指導員を配置して指導しています。エリア外につきましても、いろんなうちの生活安全パトロール隊のテープを使った広報などで周知させていきたいと考えております。","id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"その指導員の方はエリアから出てしまうと、なかなかその指導がやはりできないということになるんでしょうか。１本内側に入ったとか、そういうところでやはり喫煙されている方が多いんですが。","respondent":"高濱生活安全担当課長","answer":"エリア内というのはうちのほうで決めておりまして、路上喫煙については禁止、そして罰則も適用するという形で厳しくお願いをしております。歩行喫煙についてしないように努めてくださいといういき方ですので、全体的なマナーアップの中で考えていきたいと考えております。","id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"公共施設のランニングコストということでお尋ねしたいのですが、そこで行革の側面からも建設時に維持管理の問題を考慮すべきではないかと思います。例えば伊藤学園のプール、そして同じような規模の日野学園のプールの年間の維持管理費、光熱費等がもし金額的にわかれば教えていただきたいんですが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"そういったことで、施設を用途替えしたり、建て替えたりするときに、維持管理のコストを検討しながら設計をしているんでしょうか。１０年から２０年と長いスパンで、どのようなお考えなのでしょうか、お願いします。","respondent":"宍戸施設担当課長","answer":"新築物件につきましては、なるべく維持管理費を考えた上で設計はしております。","id":"exchange-096"},{"speaker":"高橋委員","kind":"質問・要望","question":"さらにここを今後建て替えたりするときにも検討しながら設計し、建築していっていただきたいというふうに思います。３０％ということになっているんですが、平成１８年度から平成１９年度、平成２０年度と投資的経費は何パーセントだったんか尋ねました。","respondent":"日下部企画財政課長","answer":"平成１７年度の決算から３カ年で申し上げますと、投資的経費につきましては、平成１７年度が構成比でまいりますと２０％、それから平成１８年度が２２.６％、平成１９年度が１４.７％と、そういう内訳です。","id":"exchange-097"},{"speaker":"高橋委員","kind":"質問","question":"そして、平成２０年度は当初予算で２８.３％で、今回３０％ということなんですが、そもそも投資的経費というのは、どのような区別をしているのでしょうか、お願いします。","respondent":"日下部企画財政課長","answer":"投資的経費、ちょっととらえ方、幅がありますけれども、基本的には社会資本の整備ということでありまして、施設の建設、それから土地の取得、これが主なものです。","id":"exchange-098"},{"speaker":"高橋委員","kind":"質問","question":"それとも教育なんでしょうか、それとも福祉費なんでしょうか、それとも五つの柱で全体的なところなのでしょうか。どのような形で重点的に投資していくのか、それが結局予算の中で出てくるのではないかと思いますので、お願いします。","respondent":"日下部企画財政課長","answer":"ただし、投資的経費というのは、年度によってどうしてもやっぱり増減が出てまいります。一貫校、こういう形でさまざまな分野にわたって今後とも投資的経費については必要な対応を図ってまいりたいと、このように考えております。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問・要望","question":"１７５ページの大崎第二地域センター移転経費と、何とか時間があれば１６９ページの地域食事サービス事業のほうもお伺いしたいと思います。「あらためて利用者やほかの利用している方々に区が説明するという考えでよろしいですか」と念を押した質問に対して、「はい。","respondent":"中山地域活動課長","answer":"いわゆる利用者に対する説明会という形では開催しておりません。議会に説明していこう、そういうお話が伝わる中で、いわゆる利用者の代表になる方にご説明申し上げているという報告を受けております。","id":"exchange-100"},{"speaker":"安藤委員","kind":"質問","question":"１,０６８戸の新たな住宅もできるということで、和室の仕様でも使えるような何か工夫はできないのかとか、そういう声を聞いております。今からでも１０月に移転ということでしたので、機会を開催すべきだと思うんですが、いかがか尋ねました。","respondent":"中山地域活動課長","answer":"所長のほうから報告を受けている一つとしては、基本的にそういうことについては考えていないという説明の中では、ご了解いただいているです。あるいはお尋ねについてはきちんと説明していくというスタンスの中で対応していきたい、このように考えております。","id":"exchange-101"},{"speaker":"安藤委員","kind":"質問","question":"さまざまな団体がこれまで使っているわけですから、ここら辺はちょっときちんと実行すべきなんじゃないかなと思うんですが、いかがか尋ねました。","respondent":"中山地域活動課長","answer":"２００６年の段階で基本的な再開発との関係でのご説明をし、建物の概要が出た段階でご説明申し上げるというふうに答弁していたわけでございまして。利用者の方等々、現場での説明も含めてきちんと説明をしていきたい、このように考えております。","id":"exchange-102"},{"speaker":"安藤委員","kind":"質問","question":"そこには７８億円のいわば補助金が入っているわけですが、ただ、少なくとも地域も使えるような集会所というのを設けるべきなんじゃないかな。そちらの考えはいかがか尋ねました。","respondent":"中山地域活動課長","answer":"地域の利用の扱い等につきましては、通常のオープンの集会所の扱いとは別に検討の余地があろうかと考えています。この辺を含めてしっかりと細かい部分を決めてから、またこれについてはあらためて当該委員会にご説明申し上げたいと考えています。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"私もよりよい施設をつくる上で、そのほうがよりよい施設になるんだという思いで質問しておりますので、ぜひご検討ほしいと求めました。経済状況なのかということをつかんでいらっしゃったら教えていただきたいのと、値上げはやっぱりやめるべきだと思いますが、いかがか尋ねました。","respondent":"中山地域活動課長","answer":"ただ、対象になる方が基本的に外出困難な６５歳以上の方ということで、単身の方等が多いというのは実態です。昼で言うと７００円余、これは区の地域食事サービスの中での一定整合を図るべきだという中でのご説明を申し上げた、こういうことです。","id":"exchange-104"},{"speaker":"安藤委員","kind":"意見","question":"やはり値上げというのは軽々しくするべきことではないと思いますし、週に２回とどまっていますが、週に３回あるいは受けている方々の人数も増やしていくという形でぜひお願いしたいなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"山路委員","kind":"質問・要望","question":"日曜開庁は、区長の英断で去年の１月からスタートし、来庁者の推移はふだんの日に比べてどれぐらいのところまでいっているのかお伺いいたします。３点目は２０１ページと２０３ページ、どのような調査をされて、どのように活用をされるのか教えてほしいと求めました。","respondent":"上川内戸籍住民課長、榎本人事課長、小野区民課長","answer":"それで、今現在、来客数としては２万４１５人、これが開始以来の来庁された人数です。それで、１日平均では３４７人の方が日曜日に利用されているです。 さらにその病気休暇後の病気休職というさらに長期で休む方が、大体２０人強ということです。ただ、そのうち心の病の方が８割から９割という傾向です。 いろいろ個々についてはご説明すると細かくなるんですが、経済センサスとか、農林業センサスにつきましては１００件ぐらいのそういう対象があるです。…","id":"exchange-106"},{"speaker":"山路委員","kind":"質問","question":"こういうものをすると、今後考えてみたらどうかと思いますが、どのようにお考えでしょうか。しかし大変難しい問題、こういうものに役立つかどうかということを知りたかったんですが、この点についてどういうかかわりがあるかお伺いいたします。","respondent":"久保田行財政改革担当課長、榎本人事課長、小野区民課長","answer":"私どものほうといたしましては、各窓口の連携を強化しながら、そうした中でよりよいサービスを提供していきたいと考えています。… メンタルヘルス対策ですけれども、主に今力を入れているのは早期発見・早期対応ということで、軽いうちに対応したいということです。… さらにこの部分に対策を立てるというふうなことの中では、基本的に役に立っていくものではないかというふうに思っております。","id":"exchange-107"},{"speaker":"山路委員","kind":"質問","question":"職員の健康について、ワークライフバランスと健康に関する調査、これは当然やっていらっしゃると思うんですが、この辺についてはどのように仕事に生かされているかお伺いいたします。","respondent":"榎本人事課長","answer":"主にワークライフバランスの関係からいきますと、超過勤務のほうの把握をしております。それで、時期的には繁忙期はありますけれども、それが連続して続かないような形での対応を産業医とともにその辺を図っているところです。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、本庁舎のほうに来ないといけませんので、そういうものを準備していただきたい。これの内容、それから告知方法をどういうふうにされるのかお聞きしたいと思います。","respondent":"中山地域活動課長、中山防災課長","answer":"ただ、いろいろと動きがございまして、所定の場所の把握については努めていきたいと考えています。順次いわゆる軽いもの、キャスターつきで運びやすいようなものに変更しておりますので、計画的にやっていきたいと考えております。 内容ですけれども、１缶３１０ｇの缶を４校、９６缶購入しています。告知の方法なんですけれども、いろんな避難所連絡会議だとか、それからワークショップ等々の会議の席で告知をしてまいっております。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そういう地域活動課のところでどういう地域センターの情報を収集していくのかというところも含めてお答えをお願いしたいと思います。だけれども、アレルギーのお子さんというのは特別なものですから、１対１の世界ですから、そのお子さんがというふうな形になるんですね。","respondent":"中山地域活動課長、中山防災課長","answer":"ふれあい掲示板につきまして、繰り返しの答弁にならないように、把握については十分努めていきたいと考えています。実態を踏まえ、適切に対応していきたい、このように考えております。 ＭＡ－１ミルクの告知の件ですけれども、アレルギー児をお持ちのお母さん方のお集まりがあります。幼稚園等には、保健所などとも連携しながら、ＭＡ－１ミルクの件について十分告知してまいりたいと考えています。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"アレルギーのほうですけれども、牛乳を飲めない子は小学校に入っても飲みますので、そういういろんな事情がありますので、各関係のところといろいろと機会があったら速やかに使えるような形をとってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしても品川区はそういうことがあるならば、そういう場所を含めて考えて交渉しているかということも含めてお聞きしたい。景観、結構いろいろ政策的なことも入ってくるんじゃないかなと思うんですけど、そこら辺の点はどうお考えになっているか説明を求めました。","respondent":"小野区民課長、宍戸施設担当課長、堀越生涯学習課長、中川原広報広聴課長","answer":"そして山北町の施設として運用していますけれども、契約期間があと５年というふうな土地の契約期間があります。一つ… 区施設中長期改修計画策定、これがどういったもので、組織体としてはどういった形で検討していくのか、広がりはというふうなご質問です。… あくまでも代替です。まちづくり事業部のほうとも連携しながら区のほうの意向は伝えていきたいというふうに考えております。 サイン計画につきましては、研修チームの成果も視野に置きながら検討する予定です。景観にも配慮して…","id":"exchange-112"},{"speaker":"石田（秀）委員","kind":"提案","question":"だけど、しようがない、５年間は続けるんですか。内部的に区長がそこまで指示をして、ちゃんと内部がそういうことを判断して提案できるように内部的にもやっていくんですかということをお聞きしたいとの意見を述べました。","respondent":"小野区民課長、宍戸施設担当課長","answer":"地主、さまざまな権利の関係があるということ、委員ご指摘のとおりだと思います。今後どのような形でいくのかということにつきましては、その点につきましては慎重に検討してまいりたいというふうに考えております。 区有施設の劣化状況を調べ、劣化診断をした次のステップとしては、委員ご指摘のようないろいろな展開というのは想定できると思います。次のステップとして、いろいろな組織体についても検討していきたいというふうに考えております。","id":"exchange-113"},{"speaker":"石田（秀）委員","kind":"意見","question":"１回調べていただいてから、それをやっていくということなんだけど、それはぜひ今後のことも含めて、そこまで踏み込んでもらいたいなと思います。山北町だけはもう一度お願いしますとの意見を述べました。","respondent":"宮地区民生活事業部長","answer":"一つの節目だというふうに考えておりまして、やはり残る期間５年間を見据えて、それから区と協議をしているところです。この中で、今後そういったもろもろの方向性を見ながら、いろいろな手だてを考えていきたいというふうに考えております。","id":"exchange-114"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それと、広報のあり方について区のお考えをお聞きしたいのですが、広報のあり方についてどのような区のお考えがあるのか教えてください。昨年は８４万円ぐらいの予算で、今年は１４２万円ということなので、本格的に事業所との連携を図っていくのかなという思いの中でお伺いします。","respondent":"小野区民課長、中川原広報広聴課長、中山防災課長、伊勢危機管理室長","answer":"昨年９月に実施をいたしましたときには、定員４０名のところを６７名の希望者がございました。しばらくはここの部分を続けてまいって… 区内４０も駅がある区はありません。媒体の強みと弱みを補い合って、そういったことも含めて努力を今後も続けていきたいということでよろしくお願い… それから、いわゆる行政と地域と事業所が連携して地域防災力の向上に努めていくというものです。当然のことながら… 現在新型インフルエンザの感染拡大防止とそれから区役所の機能の維持を目的としまして、事業継続計画…","id":"exchange-115"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"広報のほうは、ぜひどこにどういった情報を届けるかをしっかりと見極めて今後も取り組んでほしいと求めました。防災のほうはぜひ事業所との関係が必要になってくると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-116"},{"speaker":"堺委員","kind":"提案","question":"私のほうから１７１ページの文化芸術・スポーツ振興ビジョン等策定経費、確認の意味でお話をさせてほしいと求めました。私も昨年の第１回定例会の代表質問の中で、これから基本方針あるいは基本計画の策定、その３点について提案をさせていただいた経緯がありますとの意見を述べました。","respondent":"小野区民課長","answer":"そして、これについてはビジョンの策定検討の中でどういうふうなものが必要なのかということを検討してまいりたいというふうに考えております。そんなふうなことが入っておりまして、あとは事務的経費というものもありますので…","id":"exchange-117"},{"speaker":"堺委員","kind":"確認","question":"将来像というんでしょうかね、これは先ほどのご答弁によりますと、基本計画に当たるかもというようなお話でございました。事業目的の中の２番目に、今そういうお答えがなかったので、ちょっと確認させてください。","respondent":"小野区民課長","answer":"申しわけありませんでした。今委員のご指摘のとおり、顕彰制度の基準等を策定するための経費が含まれております。","id":"exchange-118"},{"speaker":"堺委員","kind":"質問","question":"先ほど事業内容についてお尋ねをしたんですが、目的についはご説明いただきましたが、ちょっと内容についてご説明がなかったような気がするんですが。どういう方々が携わってくるのかということをお聞きしたかったんですが、ちょっとお知らせいただけますか。","respondent":"小野区民課長","answer":"そういう意味ではまちの活性化につながるようなことということで、区内の関係団体の方の代表の方、こういう方が含まれてまいります。こういう形も含まれておりまして、こういう方々から幅広く意見をいただきながら策定してまいりたいと考えているところです。","id":"exchange-119"},{"speaker":"堺委員","kind":"質問・要望","question":"どうしても表舞台で頑張る人が表彰の対象になってしまうきらいがあるんですが、裏で支えてくださっている方々もたくさんいらっしゃるわけですね。そういう面でそういう方々もやっぱり顕彰の対象に僕は含めていただきたいなと、こんな気がするんですが、その２点ちょっと教えていただけますか。","respondent":"小野区民課長","answer":"その流れで考えておりますので、実際の成績を上げた方、そしてそれを支えた方を含めた顕彰の事業というふうに考えております。それから商工会議所の品川支部、観光協会、体育指導委員会等の代表の方をお願いするというふうなことで検討しております。","id":"exchange-120"},{"speaker":"堺委員","kind":"提案","question":"１点ちょっと私たちのほうから言うのもおかしいのかもしれませんが、これは議員提案でできた関連のものですから、選出したほうがいいんじゃないか。どういう言い方をしていいのかよくわかりませんが、その辺のお考えをちょっとお知らせいただけますかとの意見を述べました。","respondent":"小野区民課長","answer":"今の議員提案による条例です。そのことも含めて検討してまいりたいと考えております。","id":"exchange-121"},{"speaker":"須貝委員","kind":"質問","question":"交流都市ともお話をして、当面自粛したらどうでしょうか。地方自治体にとって、外国都市との行き来する交流は必要性があるのかどうか、まずご見解を説明を求めました。","respondent":"伊勢総務課長","answer":"世界平和に貢献するというようなことで、姉妹都市、それから友好都市と提携した関係があります。自粛云々ですけれども、友好協会を通じて２５周年の公式訪問団等の派遣はやるということになっていますので、この方向で行きたいと考えています。","id":"exchange-122"},{"speaker":"須貝委員","kind":"質問","question":"区民にとって何か利便性があるのか、ちょっと今平和云々という話がありましたが、その辺についてどうなんでしょうかと。国際友好協会、実際現在これだけ困っているという人が、区民のために品川区の予算というのはもっと振り向けるということが大切じゃないんか尋ねました。","respondent":"伊勢総務課長","answer":"いろいろ考え方、大体交流が２,７８０人ぐらい出ていますので、そういう中でだんだんと国際性豊かな人材が品川区で育ってくるです。これはこれでまた地域と溶け合って交流するということは非常に大事なことですので、二つとも大切なことだというふうに考えてあります。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問","question":"民間会社の短時間労働の時給と比較して、かなり高いと思いますが、どうしてこんなに高いんですか、教えてください。そして、これは妥当なんか尋ねました。","respondent":"市岡総務部長","answer":"それで、このときの考え方は、言ってみれば、時間単価で割り返して、時給幾らというふうな性格のものなんでしょうか。経験、単純に時給で比較するような性格のものとは根本的に違うというふうな考え方で条例で定めている、こういうものです。","id":"exchange-124"},{"speaker":"須貝委員","kind":"意見","question":"確かに学識経験者云々、そういう方の知識云々もわかります。その辺は品川区としても取り組みの一貫性、一つの信念というのを持つということが必要じゃないかと思うんですが、もう一度説明を求めました。","respondent":"市岡総務部長","answer":"申しわけないですが、予算全体の執行についてもちろん効率化を図るということは私どもにとって重大な使命ですが、この一事をもってあたかも過大な経費を支払っているという考え方には私は賛成できないものです。","id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"１７０ページの文化スポーツ振興費、１８２ページの防災対策費についてお尋ねしますが、その前に今の質問がちょっとあったので。３億５,０００万円が前年度で、今度は３億円余になっているんですけども、対策費は減らされてきている事情は何かあるのかどうか説明を求めました。","respondent":"中山防災課長","answer":"緊急地震速報、調査していくうちに６,０００万円ぐらいかかるというようなことを言い出してきまして、それで７月まで私ども引き延ばしていたと。この緊急地震速報だけで２,５００万円程度の減になっているというのが主な減の理由です。","id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"本部第１救助、第２救助、そのあたりはどういうふうになるんでしょうか。防災のほうでどうなっているのか、もし違いがあれば説明を求めました。","respondent":"中山防災課長","answer":"それにつきましては、これからの作業になろうかと思います。緊急にやらなければならない作業だと思ってあります。","id":"exchange-127"},{"speaker":"須藤委員","kind":"質問・要望","question":"４月の改定ですから、そこにすぐ、そういったところも変えていただきたい。それと今言った消防団とか、そのあたりとの連携はどうなっているのか説明を求めました。","respondent":"中山防災課長","answer":"区民消火隊に合わせて１８２のミニポンプと６８のＣ級ポンプを配備していますので、機を見て、一緒に訓練をしています。やはり平常時には地域の防災リーダーとして、区民や防災区民組織の指導に当たるというのが消防団の役割ではないかと、このように理解しています。","id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"そういったものがどういうふうになっていくのか。それと、防災区民組織とどういうふうに連携するんだ、そのあたりがちょっとはっきり僕らは見えないんだけども、どんなになっているんですかね。","respondent":"中山防災課長","answer":"それと、震度５強の地震があった場合は、前々から申し上げていますように、職員全員が持ち場に着くという研修も既に進んです。そういう体制を整えてあります。","id":"exchange-129"},{"speaker":"須藤委員","kind":"質問","question":"１７０ページの文化スポーツ振興費、一つお聞きしたいのは、品川区では文化振興事業団という外郭団体がありますよね。そうだったら、その辺にギャップがあるような気がしてならないんだけども、文化振興事業団とのかかわり、それらについて説明を求めました。","respondent":"小野区民課長","answer":"そして、先ほどおおよそのイメージを私のほうでご説明をさせていただきましたけれども、実際に何をやるかということを検討していく。枠組みを検討してまいりますので、その議論と並行して進めていって、そういう形で並行して実施をしていくというふうに考えているところです。","id":"exchange-130"},{"speaker":"川西委員","kind":"質問","question":"１５３ページ、１５７ページ、マウントしながわ活用事業について伺います。それから二つ目の非核平和都市品川宣言２５周年については、内容をどのように計画して予算を組まれたのか、とりあえずこの二つを伺います。","respondent":"小林保育課長、伊勢総務課長","answer":"現在予定しております該当園は９園を予定しておりまして、本予算に計上しています。二つ目に、障害者保育の対応ですけれども、各園児数に応じて年額２０万円の助成金を区として上乗せ助成を予定しております。 非核平和都市品川宣言２５周年記念事業の内容です。記念のコンサート、コンサートの中身はまだ詰めていないんですけれども、こういうものを予定しています。","id":"exchange-131"},{"speaker":"川西委員","kind":"質問・要望","question":"定期的にどういうふうに何人ぐらいの年間を通して産業医の方と接触、相談があるのか伺います。平成２１年度のこの予算は、内容はどういうふうに進められるんでしょうか、伺います。","respondent":"榎本人事課長、小野区民課長","answer":"職員の健康管理の産業医ですけれども、全部で４名います。大体月３回ということで勤務して、いろいろな相談に当たっていただいているところです。 里山、生活の中でどんなふうに取り込まれているのかということを体験するということで、平成２０年度につきましては実施をしてまいりました。それを引き続き進めるということと…","id":"exchange-132"},{"speaker":"川西委員","kind":"質問","question":"それから、今のマウントしながわ活用事業なんですけれども、ボランティアで募集されましたよね。この人たちの意見というのを一言二言教えていただければいいと思います。","respondent":"榎本人事課長、小野区民課長","answer":"産業医の相談件数ですけれども、先ほども出ましたメンタル系のほうの相談件数が増えてきておりまして、年間１００件前後の相談件数があります。学校の産業医、それから清掃事務所という形でやっていますので、かなりの件数があります。 地元の方たちと一緒に作業するというふうなことで、人と人との直接的なつながりができたということで、一般のツアーよりも非常によかったというふうな意見を聞いております。","id":"exchange-133"},{"speaker":"宮崎委員","kind":"質問","question":"私は１５８ページの広報広聴費と、あと長期計画についても伺いたいと思います。これを具体的にどういうふうに仕組みを充実していくのか、今区の考え方について伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"一つは、意見交換が活発になる仕組みづくりとしまして、タウンミーティングの開催と新たな広聴手法の検討です。三つ目ですが、情報要支援者のための情報媒体の充実ということを考えてあります。","id":"exchange-134"},{"speaker":"宮崎委員","kind":"質問","question":"区民の立場での広報と、具体的に内容がどうなっているのかというのがわかったら、ここら辺をもうちょっと詳しくほしいと求めました。パブリックコメントのところは、私は広報のあり方、先ほどのところでもうちょっと突っ込んだところで何か考えているのがあれば伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"パブリックコメントにつきましては、平成１９年から始めまして、２年間実施してきてあります。この実施状況については、おおむね私どもが要綱で予定していました運営がなされてきているというふうに感じておりますので。","id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、これは項目で終わっていて、中身がないということですね。そういうところまで書いていないんですけれども、どういうふうに思いますか、どうでしょう。","respondent":"中川原広報広聴課長","answer":"広報紙の発行日を初日として、これからパブリックコメントが始まりますと、そういったことをまずはお知らせするのが役割です。それから懸案によっては特集号を組んだり、そういった一つの記事としてお知らせしていくという、そういった広報紙の役割としてとらえております。","id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これからパブリックコメントをやるんですからというお知らせ程度ということではやっぱり不十分だし、もう一つは、先ほどお話ししたように。やっぱり具体的な中身がどういうふうになろうとしているのか、骨子などで紙面の限界等はあると思うんですけども、そこの意見はどうか尋ねました。","respondent":"福島長期計画担当課長","answer":"といいますのも、こちらの基本構想そのものが全部で２００ページを超えるような中身ですので、それをすべて広報紙に載せるということは難しい。ただ、中身を工夫することは大切だとは思いますけども、すべてを伝えることはできないのではないかというふうに思います。","id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問・要望","question":"知らせてほしい側の、だったらこれを載っけてほしいというのが出てくると思うので、広報の仕方ということをぜひ工夫していただきたい。例えば重要なパブリックコメントの意見をいただく、その内容について、どなたがどういう責任で編集されているのか伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"広報ボランティアにつきましても、読者ボランティアというのを設定しまして見ていただいて、その意見を取り入れながらつくっております。一応区長が発行するということでやっておりますので、最終決定は区長ということで発行させていただいているものです。","id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、その点はぜひ答弁いただきたいということと、私は住民への説明会なんかもぜひやる必要があるんじゃないかと。その前は介護保険とあったんですけど、この間どんな感じでやったのか、その考え方はどういうふうに開催しているのか伺いたいと思います。","respondent":"中川原広報広聴課長","answer":"それから月３回ですので継続性も考えまして、最適の方法が新聞折り込み、そして品川区としましては新聞折り込みを補完するさまざまな方法を検討し。説明会を要綱でやると言っているところは１区もございませんで、私どものほうでは…","id":"exchange-139"},{"speaker":"宮崎委員","kind":"意見","question":"ぜひお願いしたいということと、それが全戸配布を拒否する理由にはならないというふうに思うんですけども、その辺もあわせてもう一度お願いしたいと思いますとの意見を述べました。","respondent":"中川原広報広聴課長","answer":"スピードというのは、やっぱり１週間とか８日もかかっていましたら、次の号がまたでき上がってしまいますので、今までどおりの考え方でいきたいと思います。","id":"exchange-140"},{"speaker":"三上委員","kind":"質問・要望","question":"随意契約でやらなきゃならなかったのはどういうことだったのかということについて、簡単でいいですから、お伝えほしいと求めました。それから、この学校建設に関してこういった形のものというのが今どういうふうに設置されているのか、ちょっとお伺いしたいと思います。","respondent":"阿部経理課長、中山防災課長","answer":"一番契約の予定価格に近かった業者、そこと再度起工し直しまして、私どもとしては当然のことながら法令を遵守して契約を行いました。これは考え方として契約、履行能力をあわせて評価をして… それから、その他の備蓄倉庫、井戸、受水槽の遮断装置、これは飲料水をとるためのものです。それから非常発電装置、電話の優先回線等々はすべて設置しています。","id":"exchange-141"},{"speaker":"三上委員","kind":"確認","question":"２０年度の、この流れというものがどういうことであったのか、簡単でいいですからご説明していただけますか。井戸水が現実にあるわけですから、今から計画の中に入れていくという考え方をしていくということも大事じゃないかと思いますが、いかがか尋ねました。","respondent":"阿部経理課長、中山防災課長","answer":"再度ＪＶを組み直すといたしますと、最低でもやっぱり１カ月半ぐらいの期間が必要になってまいります。平成２０年度からはそうではなくて、安定した業者を選ぶということで、先ほど申し上げた簡易型総合評価で業者を決定しているです。 学校の敷地内からそこへつなげれば、耐震化された下水道につなげることができれば、これは可能であろうというふうに考えてあります。ただ、費用対効果の面でどうかというようなことです。","id":"exchange-142"},{"speaker":"三上委員","kind":"質問","question":"しかし、井戸水を利用してできるわけですから、そういったことでの検討は今後やっぱり拡大させていくということでいいんじゃないでしょうか。平成１８年度とそちらが言っているのか、平成１９年度というのか、その金額というのがどういうふうに変遷していますか。","respondent":"阿部経理課長","answer":"平成１８年度が１,３４８万円余です。平成１９年度につきましては、４１９万円余です。","id":"exchange-143"},{"speaker":"三上委員","kind":"意見","question":"その格差はどういう判断をされたかということについて、大変私は疑問に思っているんですよね。そこらあたりの、価格というものは３倍に一遍に上がるということについてどう思っているのかとの意見を述べました。","respondent":"阿部経理課長","answer":"今申し上げましたとおり、平成１７年度、１８年度については１,３００万円代です。４１０万円代ということでございましたので、そういう検討も考慮に入れまして、これを入れたものです。","id":"exchange-144"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１６７ページの町会・自治会館建設補助関係、１６９ページ、職員費の関係等をお聞きしたいところがあります。建築費ではなく、補助の考え方がどういうふうになってくるか、その二つについて説明を求めました。","respondent":"中川原広報広聴課長、中山地域活動課長","answer":"もう一つの支援協力員というのは、支援協力員を６人委嘱しまして、さまざまな研修に今参加して資質向上に努めているところです。そのほかは… ２分の１助成、最大限度１,８００万円ということで助成しているわけですが、評価額という意味ではなくて。その案分した額を実際の購入価格に合わせまして、その建物分の２分の１を補助する、こういう形で助成しているものです。","id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"質問","question":"効率というと表現が悪いけど、事務はきちっとやっていってもらうのが大前提ですけど、その上でどういうお考えになっているか教えてください。けさ企画財政課長の説明の中で、これは今までふれあいサポートでやっていた部分が防災課の担当になるという、そういう意味なんか尋ねました。","respondent":"榎本人事課長、中山地域活動課長","answer":"ちょっと職員も定数では減しても、大ざっぱにやりますと、人件費削減額に対して委託料の増加額が大体５割前後という形の計算をしております。それで、さらに将来的な退職手当の負担を入れますと… 区民委員会でもご説明申し上げたとおり、その結果として、夕食に携わっていただいていたボランティアの方の手があくということが生じてまいります。そういう意味で言えば、予算的にそこの部分が防災課のほうに移っていく…","id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委託に関しては、その辺で区政運営のためにもぜひ詰めていっていただきたい部分だと思っています。その辺で、これからもどういうふうになるのかなという感覚、ちょっとあればと思います。","respondent":"中山地域活動課長","answer":"事務局である地域センターと十分連携をとって事業を活発にしていく、このことの重要さはむしろ増してくるものと考えております。","id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひこれからもふれあいサポートをきちんと進めていっていただきたいということは要望にします。この前本会議で質問させていただきましたけど、その技術的なものの継承、設計と現場の関係といった点ではどうなんか尋ねました。","respondent":"宍戸施設担当課長","answer":"調整・指示等についてはしっかり行っていくべきものというふうに考えておりますので、引き続きその辺については力を入れていきたいと思います。その点も踏まえまして、技術の継承については心がけていきたいと考えています。","id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後にします。区の計画がこういうふうになっているよということは１００％伝えていってほしいし、これからも努力のほう、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=914#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":127983,"voices":367}},{"id":"h21-20090312-3","meetingId":"h21-c-budget","date":"2009年3月12日","dateIso":"2009-03-12","committee":"予算特別委員会","time":"午前１０時０２分～午後６時２４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を174件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"プレス発表資料の３７ページの八潮プロジェクト、この辺から伺っていきたいと思います。この辺の「等」についてのご説明を、簡単で結構ですから、いただきたい。","respondent":"冨岡高齢福祉課長、日下部企画財政課長","answer":"平成２１年の８月まで八潮南中学校を利用されておりまして、民生費に移るということで、維持管理の光熱水費等を含めた部分を計上しています。それから、高齢者住宅のほうにつきましては… 都市計画の見直しですが、これにつきましては、一応今、予定どおり手続きを進めているという状況です。","id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"都の割合が６０％と４０％になっておりますけれども、もし新築をしていたらばというようなお考えというのが出たか、出なかったか。次の質問のときまでにお答えいただければと思うんですけれども、その２点、。","respondent":"日下部企画財政課長","answer":"まだ築２５年ということで、活用を図っていくという、これが基本的な考え方です。それから、４０％と６０％、これは改修といえども、一定の時間がかかりますので、その出来高見合いということで計上しています。","id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"これはもう１点、答えとしては、新築で計算されたかどうかという点だけ、ご答弁がなかったので、お願いします。","respondent":"宍戸施設担当課長","answer":"新築で行った場合は、約２倍ぐらいの経費がかかるのではないかと試算しております。","id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"２倍というのは高いほうで見積もったのかなということですので、考えていた質問から、先にいきます。出てくる公の施設についてご説明をいただけますか尋ねました。","respondent":"日下部企画財政課長","answer":"公の施設ということでありますけれども、私ども、幅広く使っておりますが、基本的には区民サービスとして提供する、公共目的の施設ということで位置づけをしています。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"何か法的な関係の規制とか、そういった面がありますでしょうか。わからなければ、次を進めていきます。","respondent":"日下部企画財政課長","answer":"公の施設につきましては、たしか地方自治法第２４４条、この辺を中心にしまして、必要な規定がなされている。これに基づきまして、区としても公の施設の整備運営等を図っているというものです。","id":"exchange-005"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、逆に言えば、パーセンテージが、もし、これが新築だった場合にはどうなるのかなというお伺いをさせていただきたかったんですね。その辺、もしおわかりでしたら、お願いしたいんですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"原委員","kind":"質問・要望","question":"施設の関係でありますけれども、確認をさせていただきたいということで、１ベッド当たり多分２００万円ぐらいのお金がおりてくるかと思うんですね。ざっくりの予算ですから、まだこれからなんですけれども、金額的にどのぐらいのものが来るのか。","respondent":"冨岡高齢福祉課長","answer":"都の補助金は１億５,０００万円ぐらいです。それは区のほうに入ってまいります。","id":"exchange-007"},{"speaker":"原委員","kind":"確認","question":"私、現地を確認したら、大分クラックも入っているんですね。効率的であるというようなところまで判断をしてほしかったということで、以上、お願いで終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"１点ですが、先ほどの質問で、この辺の理由についてお伺いいたします。この病児保育の２カ所で、そういう内容についてどういう展開をされていくか、お伺いいたします。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"今回、大井林町の都営住宅跡の施設について、高齢者住宅ということではなく、高齢者向け優良賃貸住宅です。予定をしております大井林町跡につきましては、元気な方も含めた高齢者住宅を想定しておりますが… 大井地区、東大井に展開することによって、既存の病後児保育室３園も含めたネットワークの中で対応できるものと考えています。１つは、各施設が有機的に連携して対応していくという点でのケア、そういった育児。","id":"exchange-009"},{"speaker":"山路委員","kind":"質問・要望","question":"一人ひとりが真剣に質問し、品川区に必要だなということで、昨年の第２回定例会で私が代表して内容については質問をさせていただきました。都の第１回定例会で、我が党が要望いたしましたが、お伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"この住宅につきましては、これは土地の取得に関しましても、国の補助金をいただけるという制度ですので、活用をしたといういきさつがあります。介護の連携ということで、小規模多機能の施設もつくってまいりたいと考えていますので、検討の課題にさせていただきたいと考えていま…","id":"exchange-010"},{"speaker":"山路委員","kind":"質問","question":"２０５０年には３５％に高齢者が増えると言われている中にあって、高齢者の１つの希望として、現在と同じ状況で資格を定められるのか。この辺についてお伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"高齢者向けの優良賃貸住宅の制度ですので、６０歳以上の方で、当然品川区民ということは前提にしています。","id":"exchange-011"},{"speaker":"山路委員","kind":"質問・要望","question":"居宅介護、訪問看護ステーション、これが非常に安心に、安全に、品川に住み続けたいという夢がかなってくるのかなという希望があると思うんですね。話題になりつつありますが、この辺のところまで将来考えられていらっしゃるかどうか、もう一度お知らせをほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"高齢者の住まいのあり方については、今後引き続きさまざまなあり方を検討させていただきたいと考えております。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"私からは、同じく２３１ページの高齢者住宅等整備費と大井林町跡高齢者向け優良賃貸住宅について伺いたいと思います。運営について伺いたいのと、この３要素で構成する、ご説明ください。","respondent":"冨岡高齢福祉課長","answer":"この施設ですけれども、用地の取得から始めまして、公設を考えておりますが、運営につきましては、今後検討を進めてまいりたいと考えています。一緒に食堂をと考えられるということで含めて、共益費という形で組み立てていこうと考えていますけれども…","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用料設定についての考え方、幾らぐらいの設定を想定しているのか、教えていただきたい。同じく品川区の助成による独自家賃の軽減制度を設ける考えなのか、あわせてご説明いただけますか。","respondent":"冨岡高齢福祉課長","answer":"バリアフリーと緊急の対応ということがありますが、そういうものも含めまして、利用料を構成していくです。それから、ほかの部分、今後どうするかということは、軽減の部分ですけれども、これは今後の検討の課題であるです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"自治体が所得の少ない区民を排除するような、こういう利用料設定はやめるべきだと思うんですけれども、そのお考えを教えていただきたい。ぜひ原小学校跡と同じく、軽減制度をお考えいただきたいと思うんですけれども、いかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"それから、基本設計に入っていくということで、具体的に最終的にどういう建物にするのかもまだこれから最終的な案は決まっておりません。いろいろな角度から総合的に判断して、最終的に決めていくべきだと思いますので、どの程度ということは今の段階ではお答えできません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用料については、総合的に検討したいということですけれども、その総合的とはどういう要素なのか、ご説明いただきたい。総合的の要素をご説明いただけますか。","respondent":"冨岡高齢福祉課長","answer":"現在利用されている施設がどのような形態で利用料をいただいているのかという部分、そういうものをさまざまな角度から項目を挙げまして検討していくという意味で、総合的にというふうに申し上げたところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほども伺いましたけれども、自治体が所得の少ない区民を使用料で排除する。私はぜひ軽減制度を考えるべきだと思いますけれども、いかがか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"したがって、家賃相当のほかに１割負担等々が必要になるわけですね。検討する中で、原小学校跡と比較しながらの論議というのは、ここについてはふさわしくないのではないかと考えています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"結局はご説明を伺っても、区民の厳しい実態を全く見ようとしない、その姿勢だと思います。重ねて軽減制度を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"２１３ページの高齢者生きがい対策事業の中にあります高齢者の趣味・健康づくり事業についてお伺いいたします。最後のところなんですけれども、カラオケ広場等と書いてあるんですけれども、等というのは何を指しているか、説明を求めました。","respondent":"永尾高齢事業課長","answer":"ただ、毎年やっている中での感想等を参考に、少しずつ改良していくように考えております。金額的に少ないので、「等」ということでまとめております。","id":"exchange-019"},{"speaker":"稲川委員","kind":"質問・要望","question":"そして、開催場所なんですが、４件あるんですが、これは簡単にお答えいただきたいんですが、どういった場所で開催をしているのか。高齢者作品展だけが９８万円ということで、１００万円近い予算なんですが、会場費になっているのかどうなのか、その辺、説明を求めました。","respondent":"永尾高齢事業課長","answer":"こちらも年に１回、秋に開催ということです。カラオケにつきましては、店舗との契約になっております。","id":"exchange-020"},{"speaker":"稲川委員","kind":"質問","question":"そういう思いがあるんですが、それはいいといたしまして、この中のゲートボール大会についてお伺いいたします。日本で人口２００万人と言われていますが、区内のチーム数、大会に出席する参加チーム数を説明を求めました。","respondent":"永尾高齢事業課長","answer":"区内のクラブ数は、申しわけありません、把握してないんですけれども、ゲートボール大会の参加のチームは２４チームになっております。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"２４チームというのは、品川区全体なのか、それとも一部地域なのか。荏原のほうとかでもやるべきだと、そちらのほうが地域の人たちが参加しやすいと思うんですが、いかがお考えか尋ねました。","respondent":"永尾高齢事業課長","answer":"普段からそういうところで練習をされているということで、大会ですので、やっぱり広いところということを考えております。あのカーンという音がうるさいとか、そういうこともありますので、その辺のことも考慮しながら場所を考えているところです。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問・要望","question":"日本でも２００万人のゲートボール人口がいる中で、大体みんな見ると、子どもというのがゲートボールのキーワードになってくるのではないかなと。小学生なのかは別にしても、一緒になって参加することも高齢者にとって最大の生きがいではないかなと私は考えているんですが、いかがお考えか尋ねました。","respondent":"永尾高齢事業課長","answer":"子どもとお年寄りの方が接していると、お年寄りの方もすごく生き生きと元気になっているように見受けられます。こちらのゲートボールについても、どういうふうにやったらいいかということは、考えていきたいと思います。","id":"exchange-023"},{"speaker":"山内委員","kind":"質問","question":"２３７ページ、それから、２１５ページの高齢福祉費の家具転倒防止対策助成についてお伺いいたします。児童扶養手当の中で、全部支給と一部支給というのがあるんですけれども、まずはその辺を教えていただけますか。","respondent":"諸岡児童課長","answer":"現在で申しますと、全部支給の方は月額ですが、４万１,７２０円という金額です。一番少ない方が９,８５０円、支給される方で一番少ない方が９,８５０円、こういうような制度です。","id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"今の児童扶養手当の一部支給のところで、これは母子家庭のみで、所得制限があるというか、所得が多い人は一部支給、そういう考え方でいいんか尋ねました。","respondent":"諸岡児童課長","answer":"規定の所得を超えますと、児童扶養手当は出ません。１０円刻みです、満額の月額４万１,７２０円、こういう金額で現在実施しております。","id":"exchange-025"},{"speaker":"山内委員","kind":"質問","question":"いきなり通知が自分のところに届いて、さあ、困ったと。なかなかお金を工面することが難しいというアンケートがあったんですけれども、その辺については、どうなんか尋ねました。","respondent":"諸岡児童課長","answer":"国の法に基づく児童手当と同じ目的で子育て世代の経済的支援のために支給しているので、税務署のほうとしては、ご回答いただけない状況です。支給決定通知書の中にも、その旨を記載させていただきまして…","id":"exchange-026"},{"speaker":"山内委員","kind":"質問・要望","question":"２１１ページの訪問介護員雇用と２級資格の取得の助成について伺いますけれども、これは非常にすばらしい、画期的な施策だと私も思っております。事業所がたくさんありますけれども、例えば平成２０年度内に事業所で申し込みをされた、区内の事業所と区外の事業所の内訳は何かありますか。","respondent":"冨岡高齢福祉課長","answer":"事業所については、対象を区内としておりますので、基本的に区内です。","id":"exchange-027"},{"speaker":"山内委員","kind":"質問","question":"わかりました。外国人介護士の質問を本会議でさせていただいたんですけれども、そこに、入学を希望されたときの対応というのはいかがなんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"実際問題として、就職につながってこないということがあれば、なかなか学校に入るということもちゅうちょされるということがあるかという状況です。","id":"exchange-028"},{"speaker":"山内委員","kind":"意見","question":"日本で介護の仕事をしたいなと興味を持つ人は多分いると思うんですね。今後を見据えますと、非常にいいことなのかなと思うんですけれども、どうなんでしょうとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"言語の問題とか、一緒に学ばれるところの環境も含めて、そういうのを整備していくというのは非常に難しい状況があると思います。介護福祉士ですので、まず、かなり条件を整えるのが難しい状況があるかなと理解しています。","id":"exchange-029"},{"speaker":"山内委員","kind":"質問・要望","question":"向こうで医学の勉強をするという方だってたくさんいらっしゃるわけですし、それは今後の要望というか、今後を見据えていきたいと考えています。答弁の中で、再チャレンジ応援講座というのが出てきたんですけれども、その辺、ちょっと教えていただけますか。","respondent":"冨岡高齢福祉課長","answer":"講習会等を開きまして、もう一度研修等で、仕事につきやすい状況をつくり出していきたいという意味の資格の講座です。","id":"exchange-030"},{"speaker":"山内委員","kind":"質問","question":"最後に、家具転倒防止対策助成、これは３００万円ついておりますけれども、地震があったときに一番の死亡率の原因というのは圧死なわけですよね。それだけを説明を求めました。","respondent":"永尾高齢事業課長","answer":"上限２万円までの部分について、９割助成をするというような制度です。〔時間切れにより答弁なし〕","id":"exchange-031"},{"speaker":"浅野委員","kind":"質問","question":"国民健康保険事業会計の４３４ページの特定健康診査等事業費、後期高齢者医療特別会計のほうで４８６ページ、健康診査費についてお伺いします。ちょっと考えてみると、母子家庭の支援というものを一くくりにしたのではないかなと受けとめられるんですけれども、この点についてまずお伺いします。","respondent":"諸岡児童課長","answer":"これまで品川区の独自のひとり親家庭支援事業ということで、母子寡婦福祉連合会のほうに委託して事業を実施しておりました。このように明確に予算書の中に明記させていただいたということで、以前は、他の事業に含めて記載させていただいたものを独立させたです。","id":"exchange-032"},{"speaker":"浅野委員","kind":"確認","question":"もう一つの質問だったんですけれども、そういうふうにくくったのかなということについては、再度確認したいと思います。そちらのほうの人数の内訳、それぞれ、平成１９年度からの助成件数と助成額などについてお伺いできればと思います。","respondent":"諸岡児童課長","answer":"これの内容ですけれども、これは母子寡婦福祉連合会のほうに委託いたしまして、託児つきで実施をしているものがあります。今年度は、初級講座ということで、ワード、エクセル、それぞれの講座を２０人の定員に分けて、年２コース実施をしたものです。","id":"exchange-033"},{"speaker":"浅野委員","kind":"意見","question":"母子自立支援助成ですけれども、実際にその成果として、就労につながったかどうかということについても、ひとつお願いしますとの意見を述べました。","respondent":"諸岡児童課長","answer":"今年度から新たに就労支援員、母子自立支援就労プログラム策定員というものですけれども、個別に実施しています。自立支援員がアドバイスを行いながら、きめ細かく対応していただいて、就労に結びつけているという状況です。","id":"exchange-034"},{"speaker":"浅野委員","kind":"質問","question":"休職している方などが、この制度が昨年の２月８日以降に急遽スタートしたと聞いているんですけれども、実際に一部削減された方がおられたのかどうか。いた場合の人数とその方の状況などを教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"さまざまに個別に対応を図りながら、連絡がとれなかったりというようなことで、２分の１の削減になった方が全体で８０人ぐらいの人数です。今申し上げました母子自立支援プログラムへの登録をアドバイスしたり、そのような個別のアドバイスをさせていただいているという状況です。","id":"exchange-035"},{"speaker":"浅野委員","kind":"質問","question":"今のご答弁で、その方々が今後どういう状況で生活されるかというのは、しっかりと区のほうでもフォローしていっていただければなと思うところです。例えば保育園に預けられないということになったら、これは困るなと思ったんですけれども、この連携についてお伺いします。","respondent":"諸岡児童課長","answer":"就労に向けて求職活動を行っている方、この方々の中にはほとんど保育園にお子さんを預けて就労活動を行っている方、多い状況があります。その中で特別な事情等があれば、私どもを通して保育課との連携を図りながら、対応をしている状況です。","id":"exchange-036"},{"speaker":"浅野委員","kind":"質問・要望","question":"実施の実績というのは１５件程度ということだと思いますけれども、母子家庭と父子家庭にも支援というものをこれからも考えておられるのか。親はだれであれ、男性でもなかなか仕事のほうが厳しいという方もおられますので、この点についてお伺いします。","respondent":"諸岡児童課長","answer":"これは日常生活等の支援のために５日以内で１日８時間以内、この実績も毎年１５件から２０件程度ということで、推移をしています。あるいは、そちらのほうをご案内したりということで、父子家庭の支援も母子家庭と同様に充実していきたいと思っているところです。","id":"exchange-037"},{"speaker":"浅野委員","kind":"質問","question":"高齢者の健康診査についてお伺いしますけれども、そして、その率についてお伺いします。将来的には平成２４年度の国の参酌標準ですけれども、平成２１年度の受診率目標、お伺いします。","respondent":"本城国保年金課長","answer":"見込みとしては３０％ぐらいを見込んでおりまして、対象者がほぼ２１％ぐらいだったですので、それに比べると向上しています。最終的に後期高齢者への支援金の関係で、いろんな方策を通じることによって、目標達成に努力していきたいと考えているところです。","id":"exchange-038"},{"speaker":"浅野委員","kind":"質問・要望","question":"最後、今度は要望だけにしておきます。平成２０年度は特定保健指導はよかったという回答であったわけですけれども、受けてない方への案内の再送とか、きめ細かい対応をお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問","question":"私は、民生費の中で、２４３ページ、特に６行目、児童センター事業について、いろいろ質問しますので、よろしくお願いいたします。実際児童センターの事業費が１５％も落ちてきている理由と、指導員とは何なのかとか、等というのが何なのかというところを説明を求めました。","respondent":"諸岡児童課長","answer":"同じ２４３ページの下から５行目をご覧いただきたいと思うんですが、保育園との連携事業の中で、２,２００万円ほど計上しています。このような理由で、指導員謝礼等が減少しているものです。","id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"職員の方もそうなんですが、それ以外のいろんな部分でのスタッフが相当減ってきているのかなという心配もありまして、伺わせていただきました。平成２０年度で派遣の方を午前中の分、職員８５名というのは、いる人間で残業等で頑張っていこうという話なんか尋ねました。","respondent":"諸岡児童課長","answer":"子育て支援スタッフ育成講座というような講座を用意いたしまして、この中で地域の方々の力を児童センターの運営にお借りしようです。今年度は地域の力をお借りして、児童センターを運営し、より充実させていこうと考えているところです。","id":"exchange-041"},{"speaker":"渡部委員","kind":"質問","question":"親じゃない部分での自立というんですかね、好きなことが児童館に行けばできるんだということで、児童館で相当活躍している。１件だけ、日曜あいているところで、中高生が来れるようなのを増やそうとかというお考えがあるかどうかだけひとつ最後に説明を求めました。","respondent":"諸岡児童課長","answer":"ティーンズプラザの整備につきましては、計画的に整備させていただいておりまして、平成２０年度、７館、今年度も１館整備が完了いたします。平成２１年度にも１館、合計９館ということで、実施してまいりたいと考えております。","id":"exchange-042"},{"speaker":"菊地委員","kind":"質問","question":"その辺で考えると、資格証の発行もあり得るということなのかどうか。その辺をお聞かせを願いたいと思います。","respondent":"永尾高齢事業課長","answer":"ですけれども、これからは、徐々にその辺のほうも浸透してきていますので、通常どおり督促を行いまして、徴収率を上げたいと考えております。検討していますので、そういうようなことはまだ言うことはできませんが、丁寧に対応していきたいと考えております。","id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"資格証を発行するかどうかというのは、財力調査をどういうふうにするのかとか、その辺の考え方ももう少しお知らせ願いたいと思います。どれぐらいの対象者がいらして、実際に申告をされた方はどれぐらいいらっしゃるのか、その辺の数字も説明を求めました。","respondent":"永尾高齢事業課長","answer":"初年度ということで、もう少しきめ細やかな対応をするようにと国からも指導が来ていますので、それに対応してやっていきたいと考えております。減免の申請についてですが、現在、３件申請がございましたが、すべて条件が整わないということで、却下になっております。","id":"exchange-044"},{"speaker":"菊地委員","kind":"質問・要望","question":"法律上はこうなっていますよということですから、実質的に今後の経過の中では、保険証の取り上げという事態も生まれてくるというふうになります。一度通知をしているんでしょうけれども、この半分以下という実態をどういうふうに改善をしていくつもりなのか、そこを説明を求めました。","respondent":"永尾高齢事業課長","answer":"それについては、こちらの高齢事業課のほうでは把握がし切れていない部分もありますので、必ずしも半分の方が何もしてないということではありません。こちらのほうにお問い合わせをいただいておりますので、この説明を聞いた上で…","id":"exchange-045"},{"speaker":"菊地委員","kind":"質問・要望","question":"今のところでは、三百数十人の方、きちんとした状況というのはとらえるべきだと思いますし、電話なんかでも十分可能な話だと思います。先ほどの話ですけれども、そこはきっちりやっていただきたいのと、中止を求めるということをやってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問","question":"資料からいろいろ評価の仕方という点で、予算書も２点ほどありましたので、ここから伺いたいと思います。サービス向上委員会等は、委員の構成、この辺を伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"これにつきましては、平成１２年の介護保険の制度の開始のときから介護福祉サービス向上委員会ということで始まっておりまして。平成１５年に事業者のサービスの質の向上に向けた取り組みの支援ということで始められた第三者機関による評価でございまして、この部分については。","id":"exchange-047"},{"speaker":"渡辺委員","kind":"質問","question":"どうしても素人には違いがわからなかった点と、悪くもあり、触れづらいだろうというところにあえて触れられている。その点を伺いたいのと、分析等調査では、独自にされているのか、委託等もあるとは思いますが、この辺、２点伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"対応の状況、区としてどのように対応していくか、努めていくかという形を組み込んで向上委員会ということでしています。区政資料コーナー、なかなか区民の目につきにくいということで、これからはもう少しわかりやすい形でまた工夫してみる必要があるなと理解しています。","id":"exchange-048"},{"speaker":"渡辺委員","kind":"質問","question":"年４回という、膨大な資料がとてもインパクトという点も含めてわかりやすさもあったものですから、今後発展されたらいいなという思いで伺いました。その辺の経緯を聞きたいのと、あと、ねらいを伺えればと思います。","respondent":"高橋障害者福祉課長","answer":"検討プロジェクトをしながら、モデル事業を実施し、次年度につなげたいという考え方を持っております。リラックス効果をもたらすことによって、より障害者の快適性が継続できるのではないかということで、新しい事業の展開を考えたものです。","id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問","question":"特に新規事業だと思われましたので、伺ってみました。こんなこともねらいにあるのかなと思ったので、その点、伺いたいと思います。","respondent":"高橋障害者福祉課長","answer":"そういうような区内の施設を活用しながらということも考えられますので、その点も含めまして検討していきたいと考えております。これをやることによって、いろいろな方がそこに参加することによって、皆様の活用もできるのかなと将来的には考えております。","id":"exchange-050"},{"speaker":"渡辺委員","kind":"質問","question":"続いて、次世代育成支援事業の点で伺いたいと思います。そして、品川区が得る効果、あるいはねらいはどのようなところにあるのか、伺えればと思います。","respondent":"諸岡児童課長","answer":"品川区の充実した子育て支援策をお伝えすることによって、現在、立正大学と清泉女子大学などと実施に向けて話を進めているところです。保育園の園長でありますとか、児童センターの館長、あるいは保健所の保健師等が講師となって実施をする予定で計画しています。","id":"exchange-051"},{"speaker":"石田（慎）委員","kind":"質問","question":"先ほども質問がありましたので、このＰＲというのは、どのような形で進められていくのでしょうか。保育課のところに和室の利用をというような話を少し耳にしたのですが、その利用方法はどのようなものがあるのか、もし決まっていたら説明を求めました。","respondent":"志村生活福祉課長、福島長期計画担当課長、阿部経理課長","answer":"こうした施設の取り組みを平成１２年から行っておりますので、こうした減少につながっていると考えております。これが３月の下旬から運営を開始すると… こちらのホームページには年間２万人ほどの方がアクセスされまして、活発に意見交換等が行われているところです。次世代のどの辺の世代を考えているかです… それをレイアウト変更に伴いまして、７階に移動するものでございまして、あるいは災害対策時に職員の仮眠室として使うというような利用方法です。…","id":"exchange-052"},{"speaker":"石田（慎）委員","kind":"提案","question":"１点だけ、これは要望なのですが、そういった点もぜひ考慮してほしいと求めました。区役所内に一時保育所を設置してはいかがというご提案をさせていただいたんですが、ぜひそういった活用、いかがか尋ねました。","respondent":"志村生活福祉課長、福島長期計画担当課長、阿部経理課長","answer":"私から、ビッグイシューという雑誌の件ですけれども、雑誌の存在は承知していますけれども、具体的な連携等はございません。確かな自立といいますか… 私のほうは、次世代のほうのホームページです。ホームページで、実は今も携帯のホームページも運用してございまして… 保育士の方を頼んで一時保育をするということがありますので、常時ということではなくて、そういう形での利用は可能だと考えています。","id":"exchange-053"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"そういった方々に、こういったのもあるよというような告知などをもしできたらと思うので、ご検討してほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"３月末までに４０万人の方が正規労働者が職を失うというような試算が出ております中で、調査すべきだと思うんですけれども、いかがか尋ねました。","respondent":"志村生活福祉課長","answer":"ネットカフェの対応につきましては、東京都が平成２０年度からですか、一元的にここでとり行っているところです。ですので、その方からのご相談ということで、お受けする中でこうした対応を図るべきだろうと考えています。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ周知を充実していただきたいと思うんですけれども、区民の方に制度の内容、趣旨などが知られていると認識されているのでしょうか。あわせてお伺いしたいと思います。","respondent":"志村生活福祉課長","answer":"ですので、生の声をお聞きした上で対応を図るべきだろうと思ってあります。今度の４月もそうなんですけれども、秋、それこそ入浴券配布等のお願いをしています。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"しかも、国会議員の方もいらっしゃっていたんですが、こうほうえんの地元の議員の方なんでしょうか、来ておられた。保育園、どういう仕事をどういうふうな割り振りをして、どういう観点でもってこれから連携をとっていくのかということをお聞きしたいと思います。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"さまざまな場所で実施をして、こういうふうな形でやってほしいという形で、要望いたしました。もう一つは、地域の方々との交流ということも含めて、さらにいい事業を目指すように話をしてまいりたいと考えているところです。 ２館を含めて４館に増やして対応していますが、全体として整合性を持った子育て支援を行っていくということで連携をとっておりまして、キッズ館は。その事業等の精査する中では…","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、無認可に入らざるを得ない、そういう状況から考えると、やっぱり立場は同じなんです。認証保育所がいっぱいで入れないわけですから、助成金はあってしかるべきではないかなと私は思いますので、そのお考えを最後お聞きします。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"地域のことをよく知るべきだという話については、お話をしてまいります。それから、今後のサービスについては、引き続き頑張るように伝えてまいります。 ただ、ご指摘のとおり、そうはいっても、入れない部分がある。これにつきましては、いろいろな制度を総合的に活用して、そういう状況が発生しないように引き続き努力してまいりたいと考えております。","id":"exchange-058"},{"speaker":"山元委員","kind":"質問・要望","question":"２０７ページの成年後見制度利用支援事業、次の２０９ページの社会福祉協議会助成金、２４３ページの児童センター事業についてお伺いします。しかし、改めてここでもう一度、成年後見制度というのはどういうことなのかということを教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"法律面で支援するとともに、本人のご意思を尊重して、希望に沿った支援が受けられるようにするのが特徴です。２つの部分がございまして、保佐、補助というような度合いがあります。","id":"exchange-059"},{"speaker":"山元委員","kind":"質問・要望","question":"この制度が施行されて約８年経ちまして、約１５万人の方が利用していると伺っております。実際品川区におきまして、こちらにも高齢者と障害者に分けてありますけれども、今までの品川区における利用者の人数を教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"法定後見が始まりましたのは平成１４年からですが、合計で、今、後見を受けております、受任と申しますが、これは９１件です。なお、そのうち、平成２０年度につきましては、２５件という数字です。","id":"exchange-060"},{"speaker":"山元委員","kind":"質問","question":"今、平成２０年度は２５件とおっしゃいましたけれども、この内訳といいますか、ご相談というか、利用なさった方は高齢者の方がほとんどなんか尋ねました。","respondent":"高橋障害者福祉課長","answer":"障害者の方で、今まで１５件の方が申し立てて、社会福祉協議会が具体的な後見人になっている方は９人おります。そのほかの方につきましては、地方の施設に入所しているため地方の方に後見にせざるを得ない方については、そちらをご紹介して、行っているものです。","id":"exchange-061"},{"speaker":"山元委員","kind":"質問","question":"私のところにもご相談がありまして、こういう制度があるんだというお話をいたします。周知といいますか、今までどのような周知をされていたのか、教えていただけますか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"これはさまざまなパンフレット類でまずお知らせをするということと、それから、当然ホームページにも載せまして、あるいは社会福祉協議会、私ども、区のそれぞれの広報紙、あるいはさまざまな機関紙等でご案内しています。","id":"exchange-062"},{"speaker":"山元委員","kind":"質問・要望","question":"そのまま引き続きまして、２０９ページのほうに移らせてほしいと求めました。成年後見センターで行われている仕事といいますか、どういうことをなさっているのか、中身を教えていただけますか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"この相談を受け付け、相談をするということと、それから、法定後見、任意後見の相談の手続きの支援ということ。それからあと、区民の皆様に対する説明会、あるいは関係機関に対して周知を図っていくというようなことが主な業務です。","id":"exchange-063"},{"speaker":"山元委員","kind":"提案","question":"区民の提案事業の中に成年後見制度、市民後見人養成講座というんですか、どのような活動をするのでしょうか。教えていただけますか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"協働事業提案制度ですので、私からお答えします。低廉な価格で、気軽に後見人になっていただけるような市民の方を養成していきたいということで、ご提案をいただいたです。","id":"exchange-064"},{"speaker":"山元委員","kind":"質問","question":"しかし、今のお話によりますと、講習を受けることによって、そういう資格といいますか、なれるということなんでしょうか。財産とかをその方に任せるわけですので、その辺はどうなのか、教えていただけますか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"社会福祉協議会の成年後見センターのほうでバックアップをしていくとお伺いしておりますので、大丈夫だと伺っております。","id":"exchange-065"},{"speaker":"山元委員","kind":"質問","question":"大丈夫というお話でしたが、実際こういう方、区民後見人はいらっしゃるんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"実際３人ぐらいおいでになるですが、先ほどの補足になりますけれども、これは社会福祉協議会のほうで後見監督のほうをするですので、そういう形で支援もし、また、東京都の後見人のための講座も受けた方たちですので、安心だと考えております。","id":"exchange-066"},{"speaker":"山元委員","kind":"意見","question":"今、３人とおっしゃいましたが、将来的に３人ではもちろんやっていけないと思いますが、区としてはある程度の人数の目標を掲げていらっしゃるんじゃないかなと思いますが、大体どのぐらいの人数を養成していこうと思っていらっしゃいますかとの意見を述べました。","respondent":"冨岡高齢福祉課長","answer":"市民後見人の会の方たちは、自主的に積極的にやっていただいている部分があります。計画的に何人にするとかという形で考えてございません。","id":"exchange-067"},{"speaker":"山元委員","kind":"質問","question":"時間がなくなってしまったので、それに関連する、この中のさわやかサービスのことでお伺いいたします。そしてまた、利用料金というんですか、と同時に、協力会員に対しての報酬はどのぐらいなのか教えていただけますか。","respondent":"冨岡高齢福祉課長","answer":"ご案内のとおり、協力会員と利用会員がおりまして、平成１９年度の実績で恐縮ですが、利用会員が４６７人、協力会員が４０７人です。協力会員に対しましては、１時間７００円の協力費をお支払いしています。","id":"exchange-068"},{"speaker":"山元委員","kind":"質問","question":"これはボランティアということなので、７００円というのは安いんじゃないかなと私としては思うんですが、これは当初から７００円ということなんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"これは平成４年に立ち上げをしたということで、当初から７００円ということで、会員制であるということ、ボランティアということで、７００円に設定をしています。","id":"exchange-069"},{"speaker":"山元委員","kind":"質問","question":"ボランティアということなので、７００円でもやっていただいているのかなと思いました。実際これは６０歳以上の方、女性関係なく、ボランティアに参加するということなんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"これにつきましては、高齢者のためのサービスにボランティア活動をしていただく方に点数を付与して、これをお金にかえていただくという形です。あるいは寄付をしていただくという形で進めているものでございまして、おおむね６０歳以上です。","id":"exchange-070"},{"speaker":"山元委員","kind":"質問","question":"今、そういう意味ではボランティア精神の方が多くいらっしゃると思うんですけれども、実際、やってくださっている人数というのは、１年間で何人ぐらいボランティア、お仕事をしていただいているんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"今の地域貢献ポイント事業につきましては、今年から始まりました事業ですが、登録者数が１月の段階で６１２名という形になっております。","id":"exchange-071"},{"speaker":"山元委員","kind":"質問・要望","question":"時間がなくなってしまいましたので、ともかく区民成年後見に対しても、ぜひ問題の起こらないようお力添えしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"本多委員","kind":"質問・要望","question":"２４３ページで何点か質問します。指導員について教えていただきたいのと、保健師、これまでの取り組みと平成２１年度の取り組みについて説明を求めました。","respondent":"諸岡児童課長","answer":"５館ないし６館ということで取り組んでおりましたが、１３館でベビーマッサージ等の講座を年間３回ということで拡大して実施させていただきました。回数も年間３回から、四半期ごとの４回ということで、実施をするよう計画しています。","id":"exchange-073"},{"speaker":"本多委員","kind":"質問・要望","question":"そういったものが解消できたりして、非常に的確なアドバイスを受けたり、そういった成果がどのように上がっているのか。成果は当然上がっていると思っているんですけれども、その辺、具体的にどのように成果が上がっていると見ているのかを教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"平成２０年度でも、それぞれの回数ごと、２５組から３０組ぐらいの多くのお母さん、それから赤ちゃんが参加されて、実施しています。さまざまな知識が、お母さん方と一緒に取り組んでいるというようなことで、さらに平成２１年度は拡大していきたいという判断に至ったものです。","id":"exchange-074"},{"speaker":"本多委員","kind":"質問","question":"その辺の乳幼児関連に対しての人材確保という点について、どのように考えられているのか、説明を求めました。","respondent":"諸岡児童課長","answer":"福祉人材の確保です。子育て支援のサポーターをしていただく、その中で、引き続きのご協力をいただきたいということでの養成活動を行っていきたいと思っているところです。","id":"exchange-075"},{"speaker":"本多委員","kind":"質問・要望","question":"同じ２４３ページの中にもありますけれども、授乳などの環境整備がされてきているという、朝の説明でもありました。その辺について教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"ここに計上していますけれども、品川区では既にそれに先行して、児童施設においてこのような施設整備を行ってきているところです。今後引き続き、この設備等の充実、またそういったＰＲについては図っていきたいと考えているところです。","id":"exchange-076"},{"speaker":"本多委員","kind":"質問・要望","question":"それに関連してお聞きするんですけれども、首都圏の鉄道会社１６社でも、ポスターを貼るだけでもかなり思いやりにつながると思うんです。いろんなもろもろの施設で、きょうは民生費の管内での施設で、そういう対応はいかがでしょうかということを教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"ご指摘のポスターの掲示等につきましては、そういった意味も含めて、私どもといたしましても、積極的に対応させていただきたいと思っているところです。","id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"障害者タイムケア事業、２３１ページの高齢者住宅等整備費、５３６ページの地域貢献ポイント事業について伺いたいと思います。民生委員経費ですけれども、民生委員法の第２６条には都道府県が費用を負担すると明記されているんですが、この理由はどういったものなのか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"この部分につきましては、都の負担金が一部出ておりますけれども、区としましても、費用負担としまして大体１,０００万円ほどいたしております。この内容ですけれども、民生委員の会長協議会等の内容につきまして、負担割合で実施しています。","id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"都道府県が負担すると書かれているのに、どうして自治体で負担しなければいけないのかということをお聞きしているので、その点についての説明だけで結構です。","respondent":"冨岡高齢福祉課長","answer":"この部分につきましては、社会福祉施設の視察等の研修事業につきまして、区から支出をしています。","id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"研修とか、いろいろな部分については都道府県というふうに民生委員法に書いてあるので、この部分については、また別途伺いたいと思いますが、本当は企画財政課のほうに伺えればと思いましたので、何かあればお願いします。","respondent":"日下部企画財政課長","answer":"地方にも一部そういう意味では利害関係が出てまいりますので、その辺につきましては、一種の割り勘的に負担をし合う。そういうものです。","id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"品川区の２９６人というのは、そういった部分で、定数に対しての充足率が幾つであるかということ。実際に幾つの事業を民生委員に品川区としてお願いしていて、その活動に対してどれだけの報酬が支払われているのかということをお伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"考え方といたしまして、その趣旨に従いまして、支出をしています。活動状況ですけれども、３０個ぐらいの業務を活動していただいております。","id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"民生委員に対して３０ぐらいの量ということで、以前にも伺ったときに、随分と困っている声も聞きました。広くだれでもできるような養成講座を進めていったり、民生委員の受け手が増える体制をとっていくことも必要ではないかということで、見解を伺います。","respondent":"冨岡高齢福祉課長","answer":"何も民生委員に限ったことではなく、広く区民の方に、お願いできる方にはお願いしたいと思っているところです。そういう部分もありますし、民生委員でなければならない、お願いできる部分はお願いしたいと思っておるところです。","id":"exchange-082"},{"speaker":"井上委員","kind":"質問・要望","question":"広く受け手が増える体制を少し検討していただきたいということを要望しておきます。昨年の予算より精神障害者の生活サポートが増額されているんですが、その理由について、２点お伺いいたします。","respondent":"高橋障害者福祉課長","answer":"それで、３９０万円が交流スペース、精神のみ、憩いの場ということでやっているものです。財源につきましては、福祉包括補助金で、東京都のほうから出ております。","id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"すぐ１年で成果が出るとは思っていませんけれども、こういった事業は、補助金等の予算化については考えていってほしいなと思っています。身体障害児の受け入れ先が非常に少ないということで、今後どのように拡大をしていくのか、お伺いいたします。","respondent":"高橋障害者福祉課長","answer":"にじのひろばということで、タイムケア事業を行っているものですが、そこの中で身体障害児のほうも受け入れてきた経過があります。平成２０年４月に開設したもので、ここの中でも、可能であれば受け入れていくということも検討してまいりたいと思います。","id":"exchange-084"},{"speaker":"井上委員","kind":"質問・要望","question":"だんだん事業展開が進むにつれて、昨年の決算特別委員会の質問で事業の補助金について、障害児の放課後タイムケア事業についての見直しを求めました。利用者の要望も把握された上で、昨年同様の２５５万円という結果について理由をお伺いいたします。","respondent":"高橋障害者福祉課長","answer":"近くの集会室を短期的に借りたりしながら、事業を進めていくというところで、場所のところは考えました。お金の問題につきましては、その中でも、場所を移ったり何かする中での今後の検討ということで、当面このままにさせていただいたところです。","id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"これに品川区を含めて５つの自治体が手を挙げたと聞いていますけれども、国、都のどういった補助金を見込まれているのか。ちょっと大きな話ですが、お伺いいたします。","respondent":"冨岡高齢福祉課長","answer":"それも含めて進めてまいりますので、一番最後に区の財源がまいりますので、幾らになるかというのは今の段階では申し上げられない状況です。","id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"補助金については伺いました。この施設について一般財源をどの程度かかると積算をされているのかということを先ほど質問しました。","respondent":"冨岡高齢福祉課長","answer":"今、用地取得の段階です。それを踏まえませんと、今おっしゃるところの内容については、お答えは今の段階では難しいです。","id":"exchange-087"},{"speaker":"井上委員","kind":"質問・要望","question":"区民ニーズに沿った高齢者住宅政策として考えていただきたいということをぜひ期待していきたいと思っていますので、お願いします。合わせて地域貢献ポイント事業も一般財源に移すべきだと私は考えたので、時間がありませんが、お答えほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"これは介護保険事業の中の地域支援事業ということで位置づけておりますので、財源がいただけるということで、この部分では介護保険特別会計に入れているところです。","id":"exchange-088"},{"speaker":"高橋委員","kind":"意見","question":"２２１ページの障害者就労訓練事業、２１１ページ、２１７ページのシルバー人材センターに関してです。今年は求人がないとか、あるいは解雇されてしまっただとか、そのような状況をお願いいたしますとの意見を述べました。","respondent":"高橋障害者福祉課長","answer":"それで、今年度について離職をした人が１人おります。退職した、また経済状況のことで退職させられたという状況につきましては、今の段階では聞いておりません。","id":"exchange-089"},{"speaker":"高橋委員","kind":"質問","question":"今、このような経済状態の中で、いろいろ離職等の話はないというお話ですが、今後、そういうことも可能性が出てくるかと思うのですが、区として、こういった状況の中で、特別に、障害者の方々の就労に関して、緊急対策といいますか、そういうようなことはいかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"今の時点でもやめさせられた方がないということは、まじめに働いているのかなと考えています。ただ、ここのところにつきましても、ジョブコーチ等がありますので、丁寧に企業を回って、相談に応じていきたいと考えております。","id":"exchange-090"},{"speaker":"高橋委員","kind":"質問","question":"このような経済状況の中ですから、企業の障害者雇用の促進等につながると考えるのですが、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"各区内の企業に対して、障害者の採用もしくは継続ということで、私どもでは、その企業ごとの経営状況がありますので、もし何かあった場合についてはお願いということもありますが、今の段階では、そのまま継続させていただいているという状況です。","id":"exchange-091"},{"speaker":"高橋委員","kind":"質問・要望","question":"今後の経済状況の悪化に伴って、また問題が出てくるかと思いますので、そのときにはぜひ支援のほうをよろしくお願いしたいと思います。確認だけさせていただきたいんですが、利用者の方の補助がなくなってしまうと伺っているんですが、そちらがどうなったかをお答えください。","respondent":"高橋障害者福祉課長","answer":"それで、ほかのかもめ第二工房、かもめ第三工房については、現在、そのまま共同作業所を継続するということになりました。３施設が同歩調をとったほうがよろしいのかなと私どもも考えたところですので、当面、交通費については継続するということになりました。","id":"exchange-092"},{"speaker":"高橋委員","kind":"質問","question":"最後、発達障害の５歳児健診についてお尋ねしたいと思います。実施することになったと伺っていますが、その中で、このような５歳児健診についての協議等があったのか尋ねました。","respondent":"太田品川区保健センター大井保健相談所長","answer":"５歳児健診につきましては、幼稚園、品川児童学園の子ども発達相談や保健所の発達健診で専門医の診察につなげるというふうに努めております。１歳６カ月健診、３歳児健診で、早期発見にこれまで以上努力しています。","id":"exchange-093"},{"speaker":"高橋委員","kind":"意見","question":"対象の９８％が通園、気づき、今年度はどれぐらいの事例があったのか。そして、その後、具体的にどこでどのような支援を受けることになったのか、お願いしますとの意見を述べました。","respondent":"太田品川区保健センター大井保健相談所長","answer":"１歳６カ月、３歳児健診で見つかった発達障害の疑いがあるお子さんというのは、約４.４％です。例年四、五％程度見つかっております。","id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問","question":"２２３ページの障害者施設、２２１ページの通所事業利用促進支援事業など、区の独自の負担軽減策についてお伺いいたします。グループホーム、ケアホーム、これは区内の施設数と、幾つかの施設名を説明を求めました。","respondent":"高橋障害者福祉課長","answer":"知的障害者の入所施設は、区立ではかがやき園が１つ、それから、区内法人で、入所施設でしたら、第一かもめ園があります。それから、グループホームですが、知的障害者については、１０カ所、精神では１カ所ということになっております。","id":"exchange-095"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ケアホームが１１カ所ということでしたけれども、グループホームをもっとつくってほしい、こういった声がたくさん寄せられています。ケアホーム、グループホームだけではなくて、ケアが充実した入所施設もこれから必要であると思いますが、この点はいかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"今後、住まいのところについても十分検討していかなくてはならないということで、私どもでは検討しているところです。その辺の趣旨を生かしながら、今後も中の改造等も含めまして、進めするという内容かと思います。","id":"exchange-096"},{"speaker":"飯沼委員","kind":"質問・要望","question":"計画をきちんと立てていただきたいというのが２点目。こういったケースが生まれてくると思うので、その辺をもう一度お答えください。","respondent":"高橋障害者福祉課長","answer":"障害者自立支援法の中で、グループホームまたは一般の住宅に住むというところで、順次そういう移行が始まっているところです。今後、十分に状況を把握した上で、建設のことを考えてまいりたいと思います。","id":"exchange-097"},{"speaker":"飯沼委員","kind":"意見","question":"でも、地域で暮らすというところにおいては、地域で暮らせるためのケアがないと、できないんですね。その辺、どう考えていらっしゃるのか、聞かせてくださいとの意見を述べました。","respondent":"高橋障害者福祉課長","answer":"区分５、区分６ということで、そこの中での暮らし方を継続できるようなことを考えております。","id":"exchange-098"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１回その辺を聞かせていただきたいのと、すごく報酬単価が非常に低いために、大変な状況の中でやられているなと思っています。ＮＰＯとか民間任せにしてしまうのではなくて、区として財政的な支援がすごく大事であると思うんですが、その辺ももう１回お願いします。","respondent":"木下福祉高齢事業部長","answer":"区でつくるものももちろん今後考えていく必要があるかと思いますけれども、区としては支援をするようなやり方で進めていきたいと思っています。地域の中でケアマネジメントをすることによってどういう暮らしを支援していくかという部分について、今…","id":"exchange-099"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして、ほとんどの方が、今まで無料で受けられていたのですから、あくまでも無料に近づけていく努力を品川区としてはしていただきたい。求めていきたいと思っていますが、利用される方々への区の独自の軽減策、どういう努力をされているか、聞かせてください。","respondent":"高橋障害者福祉課長","answer":"平成１８年に障害者自立支援法ができ、年度当初から軽減策として通所生につきましては、３,０００円の軽減策をとってきたところです。通所事業の利用促進支援事業ということで、月６,０００円の手当というか、支給を考えております。","id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問","question":"改善すべきです。だれもが補助が受けられるようにすべきと思いますが、いかがか尋ねました。","respondent":"高橋障害者福祉課長","answer":"精神障害者につきましては、これから対象を外しまして、交通費の全額負担をそのまま継続するというような方向で考えております。","id":"exchange-101"},{"speaker":"本間委員","kind":"意見","question":"２４７ページ、飛んで５３７ページ、大きく分けて３つの点についてお尋ねします。１つ目は、シルバー人材センター支援事業についてですが、この中身についてもう少し詳しくお知らせ願いたいと思いますとの意見を述べました。","respondent":"永尾高齢事業課長","answer":"今度予定しております地域コンビニサービスですが、こういう方が助かるような、何でも小さいことについてできるような事業を予定しているものです。現在、どのようなニーズがあって、どういうふうにやったらいいのか、また料金設定をどうしたらいいのか…","id":"exchange-102"},{"speaker":"本間委員","kind":"質問・要望","question":"何でも相談でお伺いします、そのような部分で、身近なことで大変小さなことで不自由しているお宅があろうかと思います。特にコンビニサービスということですから、よく利用するんですけれども、３６５日２４時間営業ですよね。","respondent":"永尾高齢事業課長","answer":"それに伴って、あと、就職の決定者につきましても、２月現在、２４４名決定している状況になっております。昨年の同じ時期の２月の累計と、こちらはほぼ同数になっている状況です。","id":"exchange-103"},{"speaker":"本間委員","kind":"質問・要望","question":"これからどんどん増えていく時代に合わせて対応してほしいと求めました。担い手等についてお知らせください。","respondent":"冨岡高齢福祉課長","answer":"６５歳以上の自立支援の高齢者の方に対しまして、最終的には昼食会を行いながら、それから閉じこもり予防につなげていくというねらいです。地域サービスの新たな担い手でありますＮＰＯ法人の方に協力をお願いいたしまして、この事業を進めさせていただいている…","id":"exchange-104"},{"speaker":"本間委員","kind":"質問・要望","question":"昨今の食育との関係をお尋ねしようと思いましたけれども、ちょっと仕事の中身が違う形のように思いましたので、ここでやめておきます。生活保護費の支払われ方というんですか、いつどのような形で支払われているのかというのを、渡し方についてお尋ねします。","respondent":"志村生活福祉課長","answer":"４月の場合ですと、４月２日に指定された口座に振り込む方法と、現金の支給を１カ月分を前渡しをするという方法です。ほとんどが銀行口座をつくっていただいてございまして、大体８０％程度の方が振込です。","id":"exchange-105"},{"speaker":"本間委員","kind":"意見","question":"そうすると、既にそういうルートにのっとってということになろうかと思いますけれども、振込、あるいは現金支給の場合に、新たなメッセージ、ご本人に対して伝える伝達事項等々は行うことがありますかとの意見を述べました。","respondent":"志村生活福祉課長","answer":"保護費の変更がありますと、その時点で保護の決定通知というのを送付しています。振込はまた別です。","id":"exchange-106"},{"speaker":"本間委員","kind":"質問・要望","question":"どういうふうにやるのか、一言でもメッセージが伝わるとよろしいかと思いますので、ご検討ほしいと求めました。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"大沢委員","kind":"質問・要望","question":"いろいろなもろもろについては整理をしなければいけないものもあるのではないかと私は思っておりますが、この点について２つお伺いしたいと思います。上のところのまさに事業の下に入れるべき、または総務費に入れるべきだと思いますけれども、そこについてお考えをお聞かせほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"定住外国人福祉給付金関係の事業ですが、高齢と障害の方を対象にするということで、定住外国人の規定の中で、重度の障害のある方ということで、重度の身体障害者、知的障害者の方に対して行われるということで、私どもで事業を計画しております。","id":"exchange-108"},{"speaker":"大沢委員","kind":"質問・要望","question":"続きまして、２３３ページ、子どもすこやか医療費助成ということ、これについて２点お伺いします。過剰投薬を防止する観点から、区ではどんなチェックを行っているのか、お答えほしいと求めました。","respondent":"諸岡児童課長","answer":"医療機関のほうから直接区のほうに請求があるということではありませんで、審査支払機関、そちらのほうに保険適用外の本人負担分を払ってもらう。このような流れになっております。","id":"exchange-109"},{"speaker":"大沢委員","kind":"意見","question":"国保連合会のほうで点検を行って、品川区にということです。ここにおいてはできないのか、ないのか、そこのところをお聞かせ願いたいと思いますとの意見を述べました。","respondent":"諸岡児童課長","answer":"これは、東京都内、すべて東京都が調整を図りまして、都内の医師会等との連携のもと、支払方法について定めたものです。各それぞれの区で実施しておりますので、その際に、要望等については申し述べる機会はあると理解しております。","id":"exchange-110"},{"speaker":"大沢委員","kind":"質問・要望","question":"無料という観点から、無料であるがゆえに重複診療が多く発生する危険性もあると思いますけれども、重複診療についてのチェックはどのようにするのか、教えてほしいと求めました。","respondent":"諸岡児童課長","answer":"診療内容のチェックにつきましては、先ほども説明させていただきましたけれども、審査支払機関、国保連合会のほうに、区が委託しているという形で、内容の審査等を行ってもらっているという状況です。","id":"exchange-111"},{"speaker":"大沢委員","kind":"意見","question":"国保連合会でという、あくまでも主たるものが国保連合会ということになっているんですが、あくまでも区の事業である以上は、区も国保連合会との何かのかかわりというか、意思というか、話し合う場が必要だと思うんですけれども、そこのところをどういうふうにお考えになりますかとの意見を述べました。","respondent":"諸岡児童課長","answer":"これは２３区、それに応じて、各区のほうで個別に契約をしているという状況です。基本的にはそれぞれの区が連携して、東京都のほうから調整を図ってもらう、このような流れです。","id":"exchange-112"},{"speaker":"大沢委員","kind":"提案","question":"その中で私、一つご提案を申し上げたいと思うのが、今、区の中では生活安全、そして交通安全、警察と連携をとりながら区で事業を行っております。そこのところ、どのように受けとめられるでしょうか、お願いいたしますとの意見を述べました。","respondent":"志村生活福祉課長","answer":"どうしてもその辺の申告のおくれといいますか、ということで、どうしてもタイムラグによって発生するものが多うあります。ただ、ホームレスの問題等については、その中でノウハウ等を教えていただけるようなことはこれから考えていきたいと思ってあります。","id":"exchange-113"},{"speaker":"大沢委員","kind":"質問","question":"生活保護費をもらうがために、わざと、そういう状況をつくってしまうような方たちも増えているということを聞きました。やはり税金、私たちがみんなで築いたお金ですので、そこのところがきちんと執行されますようにお願いを申し上げて、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"武内委員","kind":"確認","question":"２４万円以上ですか、そういう部分だと思っているんですけれども、そこをもう１回確認したいと思います。そこを説明を求めました。","respondent":"諸岡児童課長","answer":"それが２分の１にならないで済みますということを繰り返しお伝えして、大分減ってまいりまして、２４名です。２分の１の減額をしなくて済みますのでというようなことを説明して、そのような方法をご案内しながら、一人ひとり対応していきたいと思っています。","id":"exchange-115"},{"speaker":"武内委員","kind":"質問・要望","question":"では、きめ細かくお願いしたいと要望します。そこだけまず先に説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"当初予算につきましては、今おっしゃったことを含めまして、予算化している金額です。","id":"exchange-116"},{"speaker":"武内委員","kind":"質問","question":"そうですか。そこだけ説明を求めました。","respondent":"日下部企画財政課長","answer":"議会に対する説明資料の関係ですので、私からお答えします。ただ、金額の関係ということでご理解いただきたいと思います。","id":"exchange-117"},{"speaker":"武内委員","kind":"提案","question":"２基で１,０００円ですから、１,０００円と無料とどう違うんだというと、つけましょうとできないんじゃないかなと。そういう意味で、私は無料でと提案したんですけれども、そこのところをもう１回見解を説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"広くつけていただくということが必要であるということは十分認識しておりますので、広報活動もしながら、広める。できるだけ多くの方にご理解をいただいて、つけていただくという形は進めてまいりたいと考えています。","id":"exchange-118"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望を最後にします。プレス発表資料の４０ページで見させていただいて、簡単にどんな感じなのか、説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"モデル事業を実施するということで、大森団地で１つのモデル的に実施をしたのと、２つのモデルの実績を積んでいただきました。あわせまして、区のほうの体制も整えていくです。","id":"exchange-119"},{"speaker":"武内委員","kind":"質問・要望","question":"これは要望します。こうしたものもぜひ日常生活用具の中に加えてもらえないか、こういう声があったんですけれども、見解について説明を求めました。","respondent":"高橋障害者福祉課長","answer":"検討会の中でも、パソコンをやっている、しなやかネットなどとの連携ということを検討したらどうかということで検討を進めております。検討を進めてきたんですが、再度検討ということで、今年度も進めするというような状況にあります。","id":"exchange-120"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ検討していただいて、なるべくこういう形で来年度ぐらいからできるように要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-121"},{"speaker":"藤原委員","kind":"質問・要望","question":"２月の一般質問でさせていただきまして、去年の決算特別委員会総括でも待機児についてお伺いさせていただきましたが、一般質問の答弁で。将来でいいですから、品川区でこの制度をどういうふうに展望として考えていくのか、説明を求めました。","respondent":"小林保育課長、福島長期計画担当課長、諸岡児童課長","answer":"おかげさまで、品川区はそれほど、５％未満の増とは見込んでおりますが、それでも入れない方がある。緊急一時的な対応も含めて… これは企画部が、いわば立ち上がり時期、これは全庁的に企画部のほうで担ってまいりましたが、来年からは後期計画も計画してまいります。… 家庭あんしんセンター内で１カ所で実施しておりましたが、平成１９年１０月から大井の拠点ということで、開設いたしました。…","id":"exchange-122"},{"speaker":"藤原委員","kind":"質問","question":"ファミリーサポートセンターの件ですけれども、私の質問は、将来的に増設はするんですかと伺ったので、そこを答えてください。そこをお伺いしたいのと、こうなって、こう良くなるんですよということを教えていただけますか。","respondent":"諸岡児童課長、小林保育課長、福島長期計画担当課長","answer":"子育て支援でありますとか、児童虐待等の対応を図っているところですけれども、今後についてまた別の拠点についても検討していきたいと思っています。… 家庭的な保育、あるいは地域で支えられる人と一緒に育てていくという可能性も今後新たに開発しながら、地域の保育の需要に対応してまいりたいと思います。 企画部のほうの支援といいますか、応援も行っていく予定です。そのように、子育て支援については、十分充実していくものと考えております。","id":"exchange-123"},{"speaker":"藤原委員","kind":"質問","question":"今、ワークライフバランス、それがバランスじゃなくて、アンバランスになっちゃうじゃないですか。だから、課長、熱意あると思いますが、もう１回待機児の熱意の答弁をしていただけますか。","respondent":"小林保育課長","answer":"待機児の解消に向けて、いろいろな方策を講じながら、一生懸命進めてまいります。","id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"介護保険特別会計の問題と２２１ページの緊急通報システム、この問題を質問したいと思います。その辺の認識はどういうふうに持っているのか、まず伺います。","respondent":"冨岡高齢福祉課長","answer":"緊急通報システムですけれども、これはひとり暮らしの高齢者の方、また、高齢者世帯のご夫婦などの緊急事態における不安の解消と生活の安全を図るという目的で実施をしているものでございまして、不安解消ということで役に立つ事業であると理解しております。","id":"exchange-125"},{"speaker":"南委員","kind":"質問","question":"設置したらどうですかと紹介しますけれども、民間型しか今受け付けてないということで、月額１,８００円かかるんですね。２,１００円もかかるような毎月の負担をもっと低減する、こういう方向に踏み出すべきだと思うんですけれども、その点についてはいかがか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"１,０００円という形で、それ以外の方というふうに２段の費用のいただき方をしているということでございまして、低所得の方に対しては対応させていただいているという中身です。","id":"exchange-126"},{"speaker":"南委員","kind":"確認","question":"少なくとも命の問題ですから、こういう区政を続けるのかどうか、こういう問題です。保険料が上がっても仕方がない、こういう認識なんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"第１号被保険者の保険料を財源に行う、利用者の方の必要性というのをかんがみまして、こういう形で設定しています。","id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"低減させるよう努力されたわけですから、もっとそこをしっかりと太いパイプにして、区の基本姿勢に置くべきだと思うんです。３年間で２億円余も使うというのは、どういう検討の中で出てきたんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"要支援者の通院の介助サービスですとか、その部分のサービスを提供する、それを横出しをするということは非常に意義のあることである。しかも、これは保険料で特別給付で扱わせていただくというような考えで、今回の特別給付というところでなったわけです。","id":"exchange-128"},{"speaker":"南委員","kind":"確認","question":"確認をしたいと思います。これは高齢者１人当たりにすると幾らになるんか尋ねました。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"基準額３,９００円で同額ですし、所得段階が一番多い方は上がりますけれども、それ以外の方は同額か引き下げになっている。この水準というのは、２３区の中でどの水準かというと… １人当たりです。今までのリハビリの関係を除きますと、５０円ぐらいだと思います。","id":"exchange-129"},{"speaker":"南委員","kind":"質問","question":"厚生委員会では７８円とおっしゃったんですよ。どちらが正しいんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"厚生委員会での答弁はリハビリを含めておりまして、申しわけございません。除きますと、そういう額になっているです。","id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、私はもっともっと堂々と実施するべきだと。これがまた高額所得者の負担がそれなりに月額７,７００円になっているんですけれども、改めて厚生労働省の保険料設定の考え方を伺いたいと思います。","respondent":"冨岡高齢福祉課長","answer":"第４期の給付費を見込みながら、細かくできるように設定するという方針で求めておりますので、減という形の設定をさせていただいたところです。","id":"exchange-131"},{"speaker":"南委員","kind":"質問","question":"これは２３区のうちの３分の２なんですね。先ほど一番最初の質問の緊急システムの問題でも、私は、改めるべきだと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-132"},{"speaker":"須藤委員","kind":"確認","question":"その辺の統一はどういうふうにしているのかなというのが１つあるのと、高齢者世帯の安否確認事業に、火災報知機が安否確認に必要なのか。どういう意味でここに入れてあるのかなというのがちょっとわからないんだけれども、そのあたりを説明を求めました。","respondent":"日下部企画財政課長","answer":"２２３ページに出てまいります、例えば２２７ページをごらんいただきますと、必ずしもそのとおりになっていない。この辺は率直に申し上げたいと思います。","id":"exchange-133"},{"speaker":"須藤委員","kind":"確認","question":"それから、もう一つ、火災報知機が安否確認に何で入るのか。","respondent":"冨岡高齢福祉課長","answer":"ご自身の確認というようなことも含めて入っているということでございまして、この辺は、ご指摘のように整理していかなければいけない部分かなと理解しています。","id":"exchange-134"},{"speaker":"須藤委員","kind":"質問・要望","question":"どうなんだというものを意識しながら、何だろうと思っちゃうといけないので、いろんな点でご配慮ほしいと求めました。学校ができて１０年ですか、いまだに何人ぐらい継続しているのかなというあたりを教えていただきたいのと、説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"今年度の入学予定ですけれども、３月半ばの今日の段階で予定者が３５名ということで、３５名になったと最近の情報で聞いております。外国人の入学のことですけれども、在留資格等の問題があるということが１点あるかと思いますので、今は、たしか１名入ったと聞いております。","id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"わかれば教えてください。現在何人ぐらい続いているか。","respondent":"冨岡高齢福祉課長","answer":"引き続き区内で就職されている方については、申しわけありませんが、今のところは把握してございません。","id":"exchange-136"},{"speaker":"須藤委員","kind":"質問・要望","question":"それはまた次の何かの機会に教えてもらいます。次に２１１ページ、どういうふうな基準で法人の助成がされているのか、教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"例えば事業を開始するとき、そういった形で、幾つかの種類について助成をしているという内容です。したがいまして、それぞれの法人によって、状況に応じて違いますので、差が出てまいるです。","id":"exchange-137"},{"speaker":"須藤委員","kind":"質問・要望","question":"こうほうえんというのが２５０万円、こういう助成の仕組みになったのか、そのあたりを教えてほしいと求めました。","respondent":"永尾高齢事業課長","answer":"その辺については、調整をしながら、算定したものです。最後のコミュニティレストラン事業助成ですが、こちらは、区のほうで新しく始める事業ですので、区のほうの積算でお願いしたところです。","id":"exchange-138"},{"speaker":"須藤委員","kind":"質問","question":"このこと自体がどういう形になるかなというのが、非常に大変なところだろうなと思うので、見ていきたいと思います。２１５ページ、ちょっと足りないんじゃないかと思うので、そのあたりを説明を求めました。","respondent":"冨岡高齢福祉課長","answer":"いろいろ連携をとりながら、町会の方たちにも入っていただきながら、区としても連携をとりながら組織を立ち上げていく。私どもの所管ですけれども、協議会のようなものを立ち上げていくという内容です。","id":"exchange-139"},{"speaker":"須藤委員","kind":"質問・要望","question":"だんだん高齢化して、そういった地域の見守りの仕組みをしっかりつくっていただきたいなと思っていますので、よろしくお願いします。高次脳機能障害に対しての考え方、ここで対応してほしいというようなことをお願いしたんだけれども、そのあたりはどういうふうになるか尋ねました。","respondent":"高橋障害者福祉課長","answer":"心身障害者福祉会館が４月以降、事業を展開する中で、高次脳機能障害もその一部として対象として受け入れることは可能かと考えています。したがいまして、具体的に運営をそのまま継続しますので、継続しながらそこの部分の検討を含めて進めするというような内容になります。","id":"exchange-140"},{"speaker":"阿部委員","kind":"質問","question":"お考えを伺いたいと思います。あるいは、行う考えはあるのかということをお伺いしたいと思います。","respondent":"永尾高齢事業課長、諸岡児童課長、小林保育課長、冨岡高齢福祉課長","answer":"平成１９年度は１３件でしたので、制度を改正したために、かなり大幅増になったと思います。平成２１年度の目標ですが… その後のことについて、まだ具体的な説明、情報提供等、東京都からございませんので、現在のところ、その後のことについては把握してございません。… 今後の対応として、その他の対応ができる家庭はよろしいかと思うんですけれども、２次の結果によってどうしても緊急性が高いというのは。２つ目に… その中で、宿泊研修、日帰り研修というのを実施いたしております。…","id":"exchange-141"},{"speaker":"阿部委員","kind":"質問・要望","question":"もちろん認可園を増やしていただきたいというのは常に要望として持っておりますし、それなりの努力もしていらっしゃることと思います。こちらについてもお考えをお伺いできればと思います。","respondent":"永尾高齢事業課長、小林保育課長、冨岡高齢福祉課長","answer":"地震によるけがの原因は、家具の転倒が一番多いと聞いております。とりあえずは、始めてまだ数年ですので… そして、私どもも、どこでだれが育てるのか。公共的な施設、その他まち場の施設も含めて、その可能性を今後検討してまいりたいと思います。 今後も在宅介護支援センター等を活用し、それには利用者との関係等もできているかと思いますので、参考にしてまいりたいと思います。","id":"exchange-142"},{"speaker":"若林委員","kind":"質問・要望","question":"要約筆記の派遣に関する実施要綱等の課題が品川区のほうにまだ残っているやに伺っておりますけれども、お聞かせほしいと求めました。そのことについてお聞きしたいと思います。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"共通な認識のところがまだ整理されてないという段階ですので、十分状況を見ながら、要約筆記についても十分研究してまいりたいと考えています。障害者自立支援法の中でサポートできるんですが… ２人の方をお願いしていますが、これは今後とも、そういう方を対象に進めてまいりたいと考えています。そういうのをあわせて、違うとは思いながら、一緒に自分たちのお仕事だとご認識をいただいているものだと理解しております。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"共助という言葉でしたけれども、ぜひここら辺の部分にも協働という視点で、実施要綱をまた早急に進めていただきたいなと要望をします。ぜひとも民生委員のリフレッシュの場面というのをしっかり持っていただきたいんですが、このことについて一言言及してほしいと求めました。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"他の団体へのことです。この事業を説明し、それぞれの団体に説明させていただきたいと思いますので、よろしくお願いします。 リフレッシュそのものではございませんけれども、それに類したものということで、民生委員の次の活動につながっていくやに聞いております。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"１つだけ。７団体の中でとありましたけれども、今回、なかなかこういう形にはならないのかという考え方をひとつお聞かせほしいと求めました。","respondent":"高橋障害者福祉課長","answer":"障害者自立支援法の指定事業所にならないと……。〔時間切れにより答弁なし〕","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"３９８ページ、あと、時間があれば保育園運営費についてお聞きしたいと思います。品川区内の滞納世帯数はどのぐらいあるんか尋ねました。","respondent":"本城国保年金課長","answer":"平成１９年度末の数ですが、加入世帯８万１,０００世帯のうち約１万８,０００世帯が滞納世帯ということで勘定しておりますが、この場合の滞納というのは、１回でも納め忘れている方はすべて含んだ形の滞納になっておりまして、率といたしましては、１９.２％です。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"ただ事業をやっているということだけで、それで予算化して、それを遂行しているということで終わっているんでしょうか。そこで、品川区がもう一歩この方たちに目を向けるべきじゃないかと思うんですが、その点についてご見解がありましたら、説明を求めました。","respondent":"木下福祉高齢事業部長","answer":"それは１つには、制度として対応する部分というのがありまして、最後のセーフティネットとして生活保護がある。どういうふうに対応していくかということで、この問題はそういう点でいうと、国政レベルできちんとした論議をするべき課題だろうと考えています。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"その中で、１人でも２人でも救えるような仕組みづくり、政策というのは、自治体として必要じゃないかなと考えております。入所ポイントの中に品川区内の在住期間も加算ポイントとして加えるべきじゃないかと思うんですが、その辺についてご見解を説明を求めました。","respondent":"小林保育課長","answer":"子どもを温かく見守るという観点から考えてまいりたいと考えていますので、緊急度をまず前提にして、考えていきたい。現時点では、区に在住している年数等を調整指数に盛り込んでいくのは慎重に対応していたきいと考えています。","id":"exchange-148"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案もしてあるんで、例えばドイツとかノルウェーは、ゼロ歳児保育というのはないわけです。それぐらいのことをそろそろ考え出してやっていくべきで、どういう動きをかけるかということも含めて、説明を求めました。","respondent":"永尾高齢事業課長、小林保育課長","answer":"そういう方を排除するということもできないわけですので、区のほうとしては、耐震化等で改修をする、その際に新しいお部屋をつくる。その中での機能をまた変更しつつ、別の楽しみをしていただくということで… 育休制度に対応した入園予約のシステム等で、１年ではありますが、取り組んでおりますワークライフバランス等の動きもあります。引き続き構造を考えていただきながら、何らかの対応ができないかという点については…","id":"exchange-149"},{"speaker":"石田（秀）委員","kind":"質問","question":"ほかのところは別ですが、そういうことも私は考えるべきだろうと思っているので、そのところの考え方を教えてください。だけど、最初の２つは。","respondent":"永尾高齢事業課長","answer":"シルバーセンターのほうの運営についてですが、これからは少し若い人、団塊の世代以上の方が利用できるような施設を考えたいと考えています。例えばパソコンの導入とか、そういうことも検討の中に入れていきたいと思います。","id":"exchange-150"},{"speaker":"石田（秀）委員","kind":"意見","question":"シルバー人材センターというところがあって、これでお願いしますとか、交渉の中で安くして、だけど、運営費補助は出すと。その金額が余ったらそれで払えばいいんだから、私はそのほうがしっかりこれからできると思うので、それはもう一度考えてほしいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-151"},{"speaker":"川西委員","kind":"質問・要望","question":"２度外気の温度が下がるという、公的施設ですから、取り入れられないのかどうかというのが質問です。それから、２１９ページの児童デイサービス、これも質問が幾つかありましたけれども、具体的な実施内容をお知らせほしいと求めました。","respondent":"冨岡高齢福祉課長、高橋障害者福祉課長、宍戸施設担当課長","answer":"平成２０年度も実施しておりますヘルパー２級の資格取得の支援も含めた部分ですが、福祉人材の再チャレンジ応援講座というのを実施する予定です。… この事業につきましては、障害者自立支援法の中の知的障害者もしくは発達障害者に対する介護給付費のものを児童デイサービスで行うということで。 遮熱性塗装ですが、鉄骨造の建物などで非常に効果があると考えられているものだと思います。ＲＣ造ですので…","id":"exchange-152"},{"speaker":"川西委員","kind":"質問・要望","question":"これはご答弁はいいですから、別のところでもう１回やりますけれども、もう少し積極的にお考えをほしいと求めました。私が再度自覚をしておきたいのですが、この予算の中でやることは可能であると、考えているということで承知しておいてよろしいのか尋ねました。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"児童デイサービスの事業を丁寧に申し上げませんでした。品川児童学園でコンパスということで、やる事業内容を２つの事業をあわせて児童デイサービスということで計上させていただいているものです。 福祉人材再チャレンジ応援講座事業で考えておりますのは、現場に、就業に結びつけるということではありますが、直接的にヘルパー２級の講習会をやるということではございません。","id":"exchange-153"},{"speaker":"川西委員","kind":"質問・要望","question":"ですから、もう１回教えていただきたいのと、その辺もあわせて伺っておきたいと思います。ですから、チャイルドステーションの内容のものを今後区としてどういうふうに指導していかれるのか、その辺もあわせて伺います。","respondent":"諸岡児童課長","answer":"品川区としましては、この赤ちゃん・ふらっと事業にも対応して、補助金を利用して施設整備を図っていきたいと考えているものです。区としても、この辺は区内の事業所等にＰＲはしていきたいと思っているところです。","id":"exchange-154"},{"speaker":"川西委員","kind":"質問","question":"子どものことに関連して、予算にないことを１つ伺います。自分の会社ですから、保育園の入所の継続が認められないという話がありますけれども、この辺の基準についてちょっと伺いたい。","respondent":"小林保育課長","answer":"子どもの安定的な措置という観点もありますので、該当年度末までは継続してお預かりするなど、その状況に応じた対応をやっているところです。しかしながら、特段育児休業法に基づくような措置の代替というような取り扱いは自営業者においては行っておりません。","id":"exchange-155"},{"speaker":"川西委員","kind":"質問","question":"生活保護は、答えていただく時間がないんですが、基準分と住宅と医療の人数の違いだけ教えてください。私はセットだと思っておりましたから。","respondent":"志村生活福祉課長","answer":"ですから、なかなかご説明しづらいんですけれども、生活扶助から充てていきます。ですので、そこで人数が違ってあります。","id":"exchange-156"},{"speaker":"川西委員","kind":"質問","question":"医療扶助だけ受けたいという場合は単独でできるんですか。〔時間切れにより答弁なし〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は２４６ページの生活保護費について伺いたいと思います。時間がありましたら、生活安定応援事業についても伺いたいと思います。","respondent":"志村生活福祉課長","answer":"ご本人のまず意思の尊重が２番目になってまいりますので、私どもで路上生活の事業につきまして、東京都と共同してやってあります。それで、そうしたケースですけれども、今年のまず緊急一時保護センターですけれども、入所者数は４７人です。","id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう実態があるので、私は伺っているんですけれども、先ほど民生委員に生活保護の制度を知ってもらう。どんな目的で、どういうことをやっているのか、説明をほしいと求めました。","respondent":"志村生活福祉課長","answer":"生活保護費の基準改定という作業がありますので、それにつきましては、１３地域センター単位ごとにあります民生委員協議会に行って説明をしています。これに私どもの生活保護部門の課題を検討していただくときに、そういったことで、制度の内容の周知に努めているところです。","id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問","question":"質問していますけれども、私はもっとこの制度を知ってもらうというのが必要だと思うんですけれども、その考え方を聞きたい。困ったら来いじゃなくて、そういういろんなアンテナを張る必要があるんじゃないかと思うんですけれども、どうか尋ねました。","respondent":"志村生活福祉課長","answer":"こういうときには、ご連絡をいただきまして、私どものほうから出張して、面接して、保護を開始する。とりわけ私どもでお世話になっているところも何件かありますので、そうしたところの連携という部分には常日ごろから心しています。","id":"exchange-160"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、ある意味では、大家にとってもしっかりこういう制度を知っておく必要があると思うんですけれども。そういう事態にならないようにするというのが、生活保護の精神じゃないかと思うんですけれども、もう一度聞きたいと思います。","respondent":"志村生活福祉課長","answer":"生活保護の申請に当たりましては、ご本人の意思の確認をしろと、こういうことになってありますので、最低限これが必要だと考えています。","id":"exchange-161"},{"speaker":"宮崎委員","kind":"質問","question":"その前の情報収集というか、アンテナを広げてほしいということを言っているわけで、もう一度しっかりご検討をお願いしたいと思います。先ほどの質問でもありましたけれども、そういう対応ができるかどうか、聞かせていただければなと思います。","respondent":"志村生活福祉課長","answer":"生活安定応援事業ですけれども、歳入のときにもお答えしましたとおり、今年度の８月から事業を開始したものです。この中で、サポートのお金の借用ということに至った方は、この中の１人です。","id":"exchange-162"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう制度は考えられないかというのを答弁いただきたいのと、ちょっとここのところは難しいんじゃないかと思うんですけれども、その点についてもお考えをほしいと求めました。","respondent":"志村生活福祉課長","answer":"答弁漏れで申しわけありませんでした。この充てる順番が、生活扶助、それから住宅扶助と、こうなってきますので、結果的になるということもあります。","id":"exchange-163"},{"speaker":"堺委員","kind":"質問・要望","question":"３点目に、２２１ページの障害者歯科診療促進検討経費、この３点についてお尋ねさせてほしいと求めました。この事業内容について教えていただきたいのと、特に１０人未満の事業所数というんですか、参考までに教えていただきたいと思うんです。","respondent":"冨岡高齢福祉課長","answer":"事業所のほうで支援をするということで、５０人、それぞれ対応させていただいている部分です。そのうち、常勤職員が１０人未満の事業所ですが、私どもの把握ですと、３３事業所です。","id":"exchange-164"},{"speaker":"堺委員","kind":"質問","question":"１月７日だったでしょうか、１月でしょうか、品川区としてこういう事業をやりますよという説明会を開催されたかなと思うんですね。その説明会に声をかけて参加された事業所数というんでしょうか、その辺の説明会の開催状況、その辺についてもお知らせいただけますか。","respondent":"冨岡高齢福祉課長","answer":"今の説明会につきましては、１月２０日に実施をさせていただきました。１０人未満の企業については、申しわけありません、把握をしてございません。","id":"exchange-165"},{"speaker":"堺委員","kind":"質問","question":"その事業所のほうから区のほうに申請をするという流れになってくるんだろうと思うんですが、その辺の申請状況はどうなんですか、これからですか。その辺のところも教えていただけますか。","respondent":"冨岡高齢福祉課長","answer":"１月の説明会の後、その段階で５０名ということで、申請をいただきました。それで、実際、どなたが対象者となるのかというのは、今、報告をいただいている状況です。","id":"exchange-166"},{"speaker":"堺委員","kind":"質問","question":"これから具体的に、そういう人が合格するというんですか、その選に入るかどうか、そういうことになってくるだろうなと思うんです。これはある一定の枠があるんだろうと思うんですが、そういう面で、その辺のところについての考え方を少し教えてほしいと求めました。","respondent":"冨岡高齢福祉課長","answer":"厳しい状況があるですし、私どもとしましては、こういう形で事業者に対して助成をするということも１つの働きかけであると思います。そういうところで状況を把握するとともに、一定の支援を今後ともしてまいりたいと考えているところです。","id":"exchange-167"},{"speaker":"堺委員","kind":"質問","question":"これは前期がたしか平成１７年度から平成２１年度まで、前期に計画した分についての検証というんでしょうか、評価というんでしょうか。その辺の考え方と今後のスケジュールについても参考までに教えていただけますか。","respondent":"福島長期計画担当課長","answer":"平成２１年度に後期計画をつくってまいりますので、検証を行った上で、後期計画をつくっていくという予定です。１０月ぐらいまでに３回から４回審議いただきまして、１２月ごろパブリックコメントを行った上、年度内に策定してまいりたいと考えております。","id":"exchange-168"},{"speaker":"堺委員","kind":"質問","question":"こういう４段階といいましょうか、最後の推進計画という、この部分だけが変更されてくるのか。要するに、ここで言われている基本理念、基本方針、基本目標、こういったものも当然俎上に上がってくるのか、その辺の考え方も教えていただけますか。","respondent":"福島長期計画担当課長","answer":"基本方針、基本目標、推進計画という形で成り立ってあります。あるいは基本方針、このまま進むかどうか、検討していただく予定です。","id":"exchange-169"},{"speaker":"鈴木（真）委員","kind":"質問","question":"２１２ページから高齢福祉費の中から考え方をお聞きしたいのと、それともう１点、質問の中で教えてください。ですから、その辺、どういうふうに考えているのかなということを、今年やるのかどうかというのはちょっとわからないので、そこら辺を説明を求めました。","respondent":"永尾高齢事業課長、小林保育課長","answer":"高齢者住宅の退去の状況ですけれども、平成２０年度の状況ですが、全部で１５名です。施設に入所された方が２名、親族と同居された方が１名ということで、入院等で退去ということも結構あるような状況です。 歌のご披露等、一定、幼児教育に取り組む動機づけとしての成果が得られたものと考えています。できれば大井地区でやっていきたいと考えていますが、その実施方法につきましては…","id":"exchange-170"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当日、ある区立幼稚園の園長先生とお会いしたときに、先生が驚いたぐらいのお話を伺いました。できれば両方から考え方を教えていただけませんか尋ねました。","respondent":"冨岡高齢福祉課長、小林保育課長","answer":"まず１つには、フロアは違っておりますが、日常的に触れ合っていくのかなというのがまず１点です。地域に開かれた施設というのを目指しているのと、あわせて、交流ということについても十分考えていくものと理解しております。 手遊び等、一緒にやっていくというような交流、種々考えられるかと思います。高齢者施設の施設長と幼稚園長がよく協議をした上で、現実、効果的な交流を企画していくように予定しております。","id":"exchange-171"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは要望だけにします。もう１点お聞きしたかったのは、どのぐらいいらっしゃるのか、つかめているんか尋ねました。","respondent":"冨岡高齢福祉課長","answer":"療養病床群には介護型と医療型とあります。介護型の部分の把握しか、１２月末で、してございませんが、２２９名の方が入床されているという状況です。","id":"exchange-172"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"早急に詰めていくべきだと私は思うんですが、いろんな絡みがありますので、すぐに要望もしにくい部分もあります。全体的な、今わかっているところでも結構です。","respondent":"冨岡高齢福祉課長","answer":"２２９名に対してどのくらいの医療機関があるかというのは、どういう対応されるのかというのが、はっきりつかめていない状況です。いずれにいたしましても、十分医療機関の動向も見据えながら、今後とも対応してまいりたいと考えているところです。","id":"exchange-173"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平成２４年ですから、もう少しありますけれども、これから先の考え方として、全体、大きな問題になってくると思うので、ある程度、早目早目に、医療型で、相手があるので、区としてどこまでできるかは別にしても、我々にも考え方を教えてほしいなと思いますが、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-174"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/762663?Template=document&Id=916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2009-01-01&TermEnd=2009-12-31"}],"sourceMeta":{"pages":0,"characters":125994,"voices":412}}]);
